const a=JSON.parse('{"work":{"id":"art-of-war","schoolId":"military","title":"《孫子兵法》","genreStrategy":"parallel","sourceNote":"版本來源自通行本及校勘附記。","chapterIds":["art-of-war_ch-1","art-of-war_ch-2","art-of-war_ch-3","art-of-war_ch-4","art-of-war_ch-5","art-of-war_ch-6","art-of-war_ch-7","art-of-war_ch-8","art-of-war_ch-9","art-of-war_ch-10","art-of-war_ch-11","art-of-war_ch-12","art-of-war_ch-13"],"totalChars":7381,"subtitle":"孫武"},"chapters":[{"id":"art-of-war_ch-1","workId":"art-of-war","order":1,"title":"始計","difficulty":4,"estimatedMinutes":10,"passageIds":["art-of-war_ch-1_p-1","art-of-war_ch-1_p-2","art-of-war_ch-1_p-3","art-of-war_ch-1_p-4","art-of-war_ch-1_p-5","art-of-war_ch-1_p-6","art-of-war_ch-1_p-7"],"tags":[]},{"id":"art-of-war_ch-2","workId":"art-of-war","order":2,"title":"作戰","difficulty":4,"estimatedMinutes":10,"passageIds":["art-of-war_ch-2_p-1","art-of-war_ch-2_p-2","art-of-war_ch-2_p-3","art-of-war_ch-2_p-4","art-of-war_ch-2_p-5"],"tags":[]},{"id":"art-of-war_ch-3","workId":"art-of-war","order":3,"title":"謀攻","difficulty":4,"estimatedMinutes":10,"passageIds":["art-of-war_ch-3_p-1","art-of-war_ch-3_p-2","art-of-war_ch-3_p-3","art-of-war_ch-3_p-4","art-of-war_ch-3_p-5","art-of-war_ch-3_p-6"],"tags":[]},{"id":"art-of-war_ch-4","workId":"art-of-war","order":4,"title":"軍形","difficulty":4,"estimatedMinutes":10,"passageIds":["art-of-war_ch-4_p-1","art-of-war_ch-4_p-2","art-of-war_ch-4_p-3","art-of-war_ch-4_p-4"],"tags":[]},{"id":"art-of-war_ch-5","workId":"art-of-war","order":5,"title":"兵勢","difficulty":4,"estimatedMinutes":10,"passageIds":["art-of-war_ch-5_p-1","art-of-war_ch-5_p-2","art-of-war_ch-5_p-3","art-of-war_ch-5_p-4","art-of-war_ch-5_p-5"],"tags":[]},{"id":"art-of-war_ch-6","workId":"art-of-war","order":6,"title":"虛實","difficulty":4,"estimatedMinutes":10,"passageIds":["art-of-war_ch-6_p-1","art-of-war_ch-6_p-2","art-of-war_ch-6_p-3","art-of-war_ch-6_p-4","art-of-war_ch-6_p-5","art-of-war_ch-6_p-6","art-of-war_ch-6_p-7"],"tags":[]},{"id":"art-of-war_ch-7","workId":"art-of-war","order":7,"title":"軍爭","difficulty":4,"estimatedMinutes":10,"passageIds":["art-of-war_ch-7_p-1","art-of-war_ch-7_p-2","art-of-war_ch-7_p-3","art-of-war_ch-7_p-4","art-of-war_ch-7_p-5","art-of-war_ch-7_p-6"],"tags":[]},{"id":"art-of-war_ch-8","workId":"art-of-war","order":8,"title":"九變","difficulty":4,"estimatedMinutes":10,"passageIds":["art-of-war_ch-8_p-1","art-of-war_ch-8_p-2","art-of-war_ch-8_p-3","art-of-war_ch-8_p-4"],"tags":[]},{"id":"art-of-war_ch-9","workId":"art-of-war","order":9,"title":"行軍","difficulty":4,"estimatedMinutes":10,"passageIds":["art-of-war_ch-9_p-1","art-of-war_ch-9_p-2","art-of-war_ch-9_p-3","art-of-war_ch-9_p-4","art-of-war_ch-9_p-5"],"tags":[]},{"id":"art-of-war_ch-10","workId":"art-of-war","order":10,"title":"地形","difficulty":4,"estimatedMinutes":10,"passageIds":["art-of-war_ch-10_p-1","art-of-war_ch-10_p-2","art-of-war_ch-10_p-3","art-of-war_ch-10_p-4","art-of-war_ch-10_p-5"],"tags":[]},{"id":"art-of-war_ch-11","workId":"art-of-war","order":11,"title":"九地","difficulty":4,"estimatedMinutes":10,"passageIds":["art-of-war_ch-11_p-1","art-of-war_ch-11_p-2","art-of-war_ch-11_p-3","art-of-war_ch-11_p-4","art-of-war_ch-11_p-5","art-of-war_ch-11_p-6","art-of-war_ch-11_p-7","art-of-war_ch-11_p-8"],"tags":[]},{"id":"art-of-war_ch-12","workId":"art-of-war","order":12,"title":"火攻","difficulty":4,"estimatedMinutes":10,"passageIds":["art-of-war_ch-12_p-1","art-of-war_ch-12_p-2","art-of-war_ch-12_p-3"],"tags":[]},{"id":"art-of-war_ch-13","workId":"art-of-war","order":13,"title":"用間","difficulty":4,"estimatedMinutes":10,"passageIds":["art-of-war_ch-13_p-1","art-of-war_ch-13_p-2","art-of-war_ch-13_p-3","art-of-war_ch-13_p-4","art-of-war_ch-13_p-5"],"tags":[]}],"passages":[{"id":"art-of-war_ch-1_p-1","chapterId":"art-of-war_ch-1","order":1,"canonicalText":"孫子曰：兵者，國之大事，死生之地，存亡之道，不可不察也。","sentenceIds":["art-of-war_ch-1_p-1_s-1"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"},{"label":"維基文庫《孫子兵法》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%AD%AB%E5%AD%90%E5%85%B5%E6%B3%95"}],"readingAid":{"translation":"孫子說：戰爭是國家的重大事務，是關係軍民生死的處境，也是決定國家存亡的途徑，不能不審慎考察。","analysis":"【主旨】全書以慎戰開篇：戰爭牽動人的生命與國家存亡，所以決策前必須全面考察，而不是崇尚輕率用兵。\\n【詞義】「兵」在此指戰爭及用兵之事；「地」不是單指地形，而是所處境域；「道」指通往存亡結果的途徑與規律；「察」含詳審、明辨。\\n【章法】三個判斷由「國之大事」推到「死生」「存亡」，層層加重，再以雙重否定「不可不察」收束，奠定全書理性籌算的基調。\\n【思想】本句不是鼓吹戰爭，而是要求掌權者正視戰爭成本；其中「民之生死」雖未展開，已構成後文計算國力、民力與久戰危害的倫理前提。"}},{"id":"art-of-war_ch-1_p-2","chapterId":"art-of-war_ch-1","order":2,"canonicalText":"故經之以五事，校之以計，而索其情，一曰道，二曰天，三曰地，四曰將，五曰法。","sentenceIds":["art-of-war_ch-1_p-2_s-1"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"},{"label":"維基文庫《孫子兵法》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%AD%AB%E5%AD%90%E5%85%B5%E6%B3%95"}],"readingAid":{"translation":"所以要從五個方面分析戰爭的基本條件，再用具體比較來衡量雙方，藉此掌握實情。這五方面是：道、天、地、將、法。","analysis":"【主旨】決定是否用兵以前，要用五項基本面作為經常尺度，再比較敵我具體條件，以求得真實情勢。\\n【詞義】「經」是以常法衡量；「校」是比較；「計」是可比較的條件，不只是計謀；「索其情」是探求敵我實情。道、天、地、將、法，分別涵蓋政治凝聚、時令、空間、領導與組織制度。\\n【章法】先提出方法，再列出五事，下一段逐項下定義，形成「總提—分釋」結構。\\n【思想】孫子把勝負從勇怯或運氣轉化為可蒐集、可比較的資訊；但這套模型不是保證公式，仍須依後文的權變與戰場回饋修正。"}},{"id":"art-of-war_ch-1_p-3","chapterId":"art-of-war_ch-1","order":3,"canonicalText":"道者，令民與上同意也，可與之死，可與之生，而不畏危。天者，陰陽，寒暑，時制也。地者，遠近，險易，廣狹，死生也。將者，智，信，仁，勇，嚴也。法者，曲制，官道，主用也。凡此五者，將莫不聞，知之者勝，不知者不勝。","sentenceIds":["art-of-war_ch-1_p-3_s-1","art-of-war_ch-1_p-3_s-2","art-of-war_ch-1_p-3_s-3","art-of-war_ch-1_p-3_s-4","art-of-war_ch-1_p-3_s-5","art-of-war_ch-1_p-3_s-6"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"},{"label":"維基文庫《孫子兵法》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%AD%AB%E5%AD%90%E5%85%B5%E6%B3%95"}],"readingAid":{"translation":"「道」是使人民與君主意志一致，願意同生共死而不怕危險；「天」是晝夜、寒暑和季節時令；「地」是路程遠近、地勢險易、地域廣狹，以及是否有利生存；「將」是將領的智慧、信用、仁愛、勇敢和嚴明；「法」是軍隊編制、官吏職掌和軍需管理。將領都聽過這五項，真正掌握的人能取勝，不能掌握的人便不能取勝。","analysis":"【主旨】本段界定五事，把戰爭能力理解為民心、時令、地勢、將才與制度共同作用的結果。\\n【詞義】「道」是上下目標一致，不宜泛譯為抽象道德；「陰陽、寒暑、時制」指晝夜氣候與季節時機；「死生」是地形所造成的生存或覆亡條件；「曲制」多指部伍編制，「官道」指各級職掌，「主用」涉及軍需財用。\\n【章法】五個「……者」構成整齊排比，前三項是戰略環境，後兩項是人的領導與組織能力。\\n【思想】「可與之死」描述共同承擔危險，不是要求人民無條件犧牲；它以「與上同意」為前提，也提醒政治正當性與內部信任是軍事能力的一部分。"}},{"id":"art-of-war_ch-1_p-4","chapterId":"art-of-war_ch-1","order":4,"canonicalText":"故校之以計，而索其情。曰：主孰有道，將孰有能，天地孰得，法令孰行，兵眾孰強，士卒孰練，賞罰孰明，吾以此知勝負矣。將聽吾計，用之必勝，留之；將不聽吾計，用之必敗，去之。","sentenceIds":["art-of-war_ch-1_p-4_s-1","art-of-war_ch-1_p-4_s-2","art-of-war_ch-1_p-4_s-3","art-of-war_ch-1_p-4_s-4"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"},{"label":"維基文庫《孫子兵法》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%AD%AB%E5%AD%90%E5%85%B5%E6%B3%95"}],"readingAid":{"translation":"因此還要比較雙方條件，查明實情：哪一方君主更得民心？哪一方將領更有才能？哪一方佔有天時地利？哪一方法令更能貫徹？哪一方兵力更強？哪一方士卒訓練更好？哪一方賞罰更公正嚴明？從這些比較，我就能判斷勝負。若將領聽從我的謀劃，用兵必勝，就留下任用；若不聽從，用兵必敗，就應撤換。","analysis":"【主旨】五事還須落到七項敵我比較，才能形成勝負判斷；計策是否被採納，也決定進言者去留。\\n【詞義】「主孰有道」比較哪一方更能使上下同心；「天地孰得」比較天時地利；「兵眾孰強」可兼指兵力與軍隊整體強度；「聽吾計」是採納上述分析與方案。末句「留之／去之」的主語、句讀歷來可有不同理解，本譯採是否留任聽計之將的通行解。\\n【章法】七問以連續「孰」字展開，把抽象五事化成可觀察項目，最後由比較推出預測。\\n【思想】此處的預測是比較證據後的判斷，不是佔卜；賞罰是否明確、法令能否落實，和兵力數量同樣重要。"}},{"id":"art-of-war_ch-1_p-5","chapterId":"art-of-war_ch-1","order":5,"canonicalText":"計利以聽，乃為之勢，以佐其外；勢者，因利而制權也。","sentenceIds":["art-of-war_ch-1_p-5_s-1","art-of-war_ch-1_p-5_s-2"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"},{"label":"維基文庫《孫子兵法》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%AD%AB%E5%AD%90%E5%85%B5%E6%B3%95"}],"readingAid":{"translation":"有利的計策既被採納，還要在實際行動中營造有利態勢，作為外在助力。所謂「勢」，就是根據有利條件靈活採取權宜行動。","analysis":"【主旨】有利的基本計畫獲得採納後，還要在外部行動中造成能放大優勢的「勢」。\\n【詞義】「計利以聽」可理解為有利計策已被聽從；「佐其外」指在既定內在條件之外加以輔助；「因利」是依據已有利勢，「制權」是作合宜的臨機權變。\\n【章法】前句承接廟算，後句用判斷句定義「勢」，由靜態比較轉入動態運用。\\n【思想】「勢」不是神祕力量，也不等於單純氣勢，而是透過位置、時機、配置與敵我反應形成的結構性優勢。計與勢相連，表示事前分析仍須轉化為現場條件。"}},{"id":"art-of-war_ch-1_p-6","chapterId":"art-of-war_ch-1","order":6,"canonicalText":"兵者，詭道也。故能而示之不能，用而示之不用，近而示之遠，遠而示之近。利而誘之，亂而取之，實而備之，強而避之，怒而撓之，卑而驕之，佚而勞之，親而離之。攻其無備，出其不意，此兵家之勝，不可先傳也。","sentenceIds":["art-of-war_ch-1_p-6_s-1","art-of-war_ch-1_p-6_s-2","art-of-war_ch-1_p-6_s-3","art-of-war_ch-1_p-6_s-4"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"},{"label":"維基文庫《孫子兵法》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%AD%AB%E5%AD%90%E5%85%B5%E6%B3%95"}],"readingAid":{"translation":"用兵以使敵人產生錯誤判斷為常用方法。所以，有能力卻向敵人顯示沒有能力；準備用兵卻顯示不會用兵；實際接近卻使敵人以為遙遠，實際遙遠卻使敵人以為接近。敵人貪利，就用利益引誘；敵陣混亂，就乘機攻取；敵軍充實，就嚴加防備；敵勢強盛，就暫時避開；敵人易怒，就挑動擾亂；以卑辭或示弱助長其驕氣；敵人安逸，就設法使其疲勞；敵人團結，就設法離間。攻擊對方沒有防備之處，從對方意料不到的方向或時機出動。這是兵家取勝的機變，不能預先用固定成法加以傳授。","analysis":"【主旨】本段說明如何操控敵人的資訊與預期，並針對敵情採取相反或相應行動，核心是製造判斷落差。\\n【詞義】「詭道」是隱真示假、誤導敵情，不宜擴張為一切行為都可欺詐；「實」指兵力與部署充實；「撓」是挑動、擾亂；「卑而驕之」有卑辭示弱、以小利驕敵等註解，本譯保留兩種相通方向；「不可先傳」指不能在戰前固定說死。\\n【章法】先以四組遠近、能否的反向顯示說資訊欺敵，再以八組條件—對策排比說因敵制變，末以「無備／不意」總結。\\n【界限】這是戰爭語境中的敵對策略，不應無限制移植到一般人際或公共治理；即使在軍事上，也須受戰爭法與人道規範約束。"}},{"id":"art-of-war_ch-1_p-7","chapterId":"art-of-war_ch-1","order":7,"canonicalText":"夫未戰而廟算勝者，得算多也；未戰而廟算不勝者，得算少也；多算勝，少算不勝，而況於無算乎？吾以此觀之，勝負見矣。","sentenceIds":["art-of-war_ch-1_p-7_s-1","art-of-war_ch-1_p-7_s-2","art-of-war_ch-1_p-7_s-3","art-of-war_ch-1_p-7_s-4"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"},{"label":"維基文庫《孫子兵法》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%AD%AB%E5%AD%90%E5%85%B5%E6%B3%95"}],"readingAid":{"translation":"開戰以前，經過廟堂計算而預見能勝，是因為有利條件多；預見不能勝，是因為有利條件少。有利條件多就能勝，少便難勝，何況毫無籌算呢？我根據這些條件觀察，勝負便可以看出來了。","analysis":"【主旨】戰前在宗廟或朝廷進行的綜合籌算，所得有利條件越多，勝算越高；毫無計算更難取勝。\\n【詞義】「廟算」是戰前由國家決策層進行的謀議與計算；「算」既可指古代籌碼，也指經比較所得的有利條件；「見」是顯現、可預見。\\n【章法】以多算、少算、無算形成遞降對照，再由一般命題落到「吾以此觀之」的判斷方法。\\n【思想】孫子說的是提高勝算而非數學上的必勝；情報可能錯誤，情勢也會改變，因此廟算必須與後文的「因利制權」配合。全篇從慎察、五事、七計到廟算，形成完整的戰前評估流程。"}},{"id":"art-of-war_ch-2_p-1","chapterId":"art-of-war_ch-2","order":1,"canonicalText":"孫子曰：凡用兵之法，馳車千駟，革車千乘，帶甲十萬；千里饋糧，則內外之費賓客之用，膠漆之材，車甲之奉，日費千金，然後十萬之師舉矣。","sentenceIds":["art-of-war_ch-2_p-1_s-1","art-of-war_ch-2_p-1_s-2"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"},{"label":"維基文庫《孫子兵法》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%AD%AB%E5%AD%90%E5%85%B5%E6%B3%95"}],"readingAid":{"translation":"孫子說：依照一般用兵原則，出動千輛快速戰車、千輛運輸重車和十萬披甲士兵，又要從千里之外運送糧食，那麼前後方的費用、接待使者賓客的開支、膠漆器材以及車甲的保養，每天都要耗費千金，十萬大軍才能出動。","analysis":"【主旨】大軍出動以前，必須先看見戰車、兵員、遠程糧運、外交接待、器材維修等龐大成本。\\n【詞義】「馳車」是快速戰車，「革車」多指載運輜重或防護車；「帶甲」指披甲士卒；「內外之費」涵蓋前後方支出；「車甲之奉」是車輛甲兵的供應維護。數字具有典型大軍的估算意味，不必視為每戰固定編制。\\n【章法】長串物資清單與數量排比，最後才說「師舉」，刻意表明軍隊不是一聲令下便能無成本出動。\\n【思想】〈作戰〉主要談戰爭經濟與後勤，而非交戰技巧；它把慎戰原則具體化為每日耗費與社會動員。"}},{"id":"art-of-war_ch-2_p-2","chapterId":"art-of-war_ch-2","order":2,"canonicalText":"其用戰也，勝久則鈍兵挫銳，攻城則力屈，久暴師則國用不足。夫鈍兵，挫銳，屈力，殫貨，則諸侯乘其弊而起，雖有智者，不能善其後矣！故兵聞拙速，未睹巧之久也；夫兵久而國利者，未之有也。","sentenceIds":["art-of-war_ch-2_p-2_s-1","art-of-war_ch-2_p-2_s-2","art-of-war_ch-2_p-2_s-3","art-of-war_ch-2_p-2_s-4"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"},{"label":"維基文庫《孫子兵法》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%AD%AB%E5%AD%90%E5%85%B5%E6%B3%95"}],"readingAid":{"translation":"軍隊作戰若久拖不決，就會使兵器鈍損、士氣挫傷；攻城會使兵力耗盡；軍隊長期在外，國家財用便會不足。兵器鈍損、士氣受挫、力量耗盡、財貨枯竭，其他諸侯就會乘虛而起，即使有智者也難以收拾後果。因此，用兵只聽說過寧可方法稍笨而求速勝，沒見過為追求巧妙而長期作戰。戰爭持久而有利於國家的，從來沒有過。","analysis":"【主旨】戰爭拖延會依次損耗兵器、士氣、兵力與國家財政，並招致第三方乘虛而入，所以應求可行的速勝。\\n【文本】「其用戰也，勝久則」一帶各本句讀、文字有差異，通行解多依上下文讀成戰事久延則鈍兵挫銳；原文尚待版本校定。\\n【詞義】「鈍兵」是兵器或軍勢疲鈍；「挫銳」是銳氣受挫；「暴師」是軍隊長期暴露、駐留在外；「拙速」不是草率冒進，而是在可勝前提下寧取不完美的迅速方案。\\n【思想】本段反對的是無法產生決定結果的消耗戰，不能曲解為所有戰事越快越好；倉促行動若缺乏〈始計〉的評估，同樣違反慎戰。"}},{"id":"art-of-war_ch-2_p-3","chapterId":"art-of-war_ch-2","order":3,"canonicalText":"故不盡知用兵之害者，則不能盡知用兵之利也。善用兵者，役不再籍，糧不三載，取用於國，因糧於敵，故軍食可足也。國之貧於師者遠輸，遠輸則百姓貧，近於師者貴賣，貴賣則百姓財竭，財竭則急於丘役，力屈財殫，中原內虛於家，百姓之費，十去其七，公家之費，破車罷馬，甲冑矢弩，戟楯蔽櫓，丘牛大車，十去其六。","sentenceIds":["art-of-war_ch-2_p-3_s-1","art-of-war_ch-2_p-3_s-2","art-of-war_ch-2_p-3_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"},{"label":"維基文庫《孫子兵法》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%AD%AB%E5%AD%90%E5%85%B5%E6%B3%95"}],"readingAid":{"translation":"所以，不能充分了解戰爭危害的人，也不可能充分了解用兵的利益。善於用兵的人，不會一再徵集兵員，也不會多次從本國遠運糧食；軍用物資取自國內，糧食盡量取自敵國，軍糧才會充足。國家因戰爭而貧困，主要在於遠程運輸；長途轉運使百姓窮困。軍隊附近物價上漲，物價上漲又使百姓財力枯竭；財力枯竭，徭役賦稅便更加急迫。力量耗盡、財貨枯竭，國內家家空虛，百姓的財產耗去十分之七；國家的資財因破車疲馬、盔甲弓弩、戟盾櫓車和運輸牛車而耗去十分之六。","analysis":"【主旨】真正理解用兵之利，必須先理解徵兵、遠輸、物價、賦役與裝備損耗形成的完整代價鏈。\\n【詞義】「役不再籍」是不反覆徵集兵員；「糧不三載」是不多次由本國長途轉運；「因糧於敵」是就敵境取得補給；「貴賣」指軍隊所到造成物價昂貴；「丘役」歷來解釋不一，大致關涉按丘裏徵發的賦役。\\n【章法】從遠輸推到民貧，再由物價推到財竭與急役，最後用十分之七、十分之六凸顯公私耗損。\\n【評議】就敵取糧是古代戰爭後勤觀，實踐上常把成本轉嫁給敵境平民；現代閱讀必須與戰爭法中的平民保護、徵用限制分開，不能當成普遍正當原則。"}},{"id":"art-of-war_ch-2_p-4","chapterId":"art-of-war_ch-2","order":4,"canonicalText":"故智將務食於敵，食敵一鍾，當吾二十鍾，𦮼稈一石，當我二十石。故殺敵者怒也，取敵之利者貨也。故車戰，得車十乘以上，賞其先得者，而更其旌旗，車雜而乘之，卒善而養之，是謂勝敵而益強。","sentenceIds":["art-of-war_ch-2_p-4_s-1","art-of-war_ch-2_p-4_s-2","art-of-war_ch-2_p-4_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"},{"label":"維基文庫《孫子兵法》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%AD%AB%E5%AD%90%E5%85%B5%E6%B3%95"}],"readingAid":{"translation":"所以明智的將領務求從敵國取得糧食。喫敵人一鍾糧食，抵得上從本國運來二十鍾；取得敵人的一石草料，也抵得上本國運來二十石。要使士卒奮勇殺敵，須激起同仇敵愾之心；要使他們奪取敵人資財，須用獎賞鼓勵。車戰中繳獲十輛以上敵車，就獎賞最先奪得的人，換掉敵方旗幟，混編後為我所用；對俘虜則妥善優待。這就叫戰勝敵人而使自己更加強大。","analysis":"【主旨】本段把「因糧於敵」落實為後勤、激勵與俘獲物整編三個環節：就地取得敵糧，既減少本國遠途輸送，也把敵方資源轉為己方戰力。\\n【數量與制度】「一鍾當吾二十鍾」「一石當我二十石」不是糧食本身憑空增值，而是說明千里轉運的人力、牲畜與沿途耗損極重。使士卒奮勇需要共同敵愾，奪取敵利則要用賞賜建立可預期的分配規則。\\n【操作層次】俘獲戰車後，要獎賞先登者、換上本軍旗幟、混編使用；對降卒則善待供養。這些動作把一次戰術繳獲轉化為可持續運用的兵力與裝備。\\n【章法與界限】文勢依「糧食成本—作戰動機—接收程序—益強結果」逐層推進，以「勝敵而益強」收束。此處描述古代戰爭的資源轉用邏輯；對俘虜的處置在今日仍須受國際人道法約束，不能把古代語境當作現代行為的充分正當化。"}},{"id":"art-of-war_ch-2_p-5","chapterId":"art-of-war_ch-2","order":5,"canonicalText":"故兵貴勝，不貴久；故知兵之將，民之司命，國家安危之主也。","sentenceIds":["art-of-war_ch-2_p-5_s-1","art-of-war_ch-2_p-5_s-2"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"},{"label":"維基文庫《孫子兵法》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%AD%AB%E5%AD%90%E5%85%B5%E6%B3%95"}],"readingAid":{"translation":"所以，用兵重在取得勝利，不以曠日持久為可貴。真正懂得用兵的將領，掌握人民的生命，也是國家安危所繫的人。","analysis":"【主旨】篇末總結「貴勝不貴久」，並把將領的判斷提升到人民生命與國家安危的責任層次。\\n【詞義】「貴勝」是以達成戰略目的為要，不等於不惜代價求勝；「民之司命」指將領握有軍民生死所繫的權責；「主」在此是關鍵所繫，不是說將領可凌駕國家。\\n【章法】兩個「故」把前文的財政、後勤、士氣和外部風險收成結論，再以沉重的責任判語結篇。\\n【思想】若只摘取「兵貴勝」會漏掉全篇對久戰傷民、耗國的警告。孫子的速勝論受慎戰與成本控制約束；現代運用還須加入合法性、比例原則和非戰鬥員保護。"}},{"id":"art-of-war_ch-3_p-1","chapterId":"art-of-war_ch-3","order":1,"canonicalText":"孫子曰：凡用兵之法，全國為上，破國次之；全軍為上，破軍次之；全旅為上，破旅次之；全卒為上，破卒次之；全伍為上，破伍次之。是故百戰百勝，非善之善者也；不戰而屈人之兵，善之善者也。","sentenceIds":["art-of-war_ch-3_p-1_s-1","art-of-war_ch-3_p-1_s-2","art-of-war_ch-3_p-1_s-3","art-of-war_ch-3_p-1_s-4","art-of-war_ch-3_p-1_s-5","art-of-war_ch-3_p-1_s-6"],"sourceRefs":[{"label":"中國哲學書電子化計劃〈謀攻〉","edition":"通行本","location":"https://ctext.org/text.pl?if=zh&node=20924","accessedAt":"2026-08-14"},{"label":"《十一家注孫子》〈謀攻篇〉","edition":"維基文庫校錄本","location":"https://zh.wikisource.org/wiki/十一家注孫子/謀攻篇","accessedAt":"2026-08-14"}],"readingAid":{"translation":"孫子說：大凡軍事用兵的法則：使敵國完好無損地歸順降服是最高明的上策，擊破摧毀敵國是次一等的策略；使敵方全軍完好無損地降服是最高明的上策，擊潰殲滅敵軍是次一等的策略；使敵方全旅完好無損地降服是上策，擊破其旅是次一等的；使敵方全卒、全伍完好降服是上策，擊破其卒、伍是次一等的。所以，即便百戰百勝，也算不上最高明的用兵境界；不用直接兵刃交戰而能使敵軍徹底屈服降順，才是最高明的上善境界。","analysis":"【題解與全勝戰略】本段為《孫子兵法・謀攻篇》開卷總綱，確立了兵家最具哲學高度的「全勝」戰略思想與「不戰而屈人之兵」之最高境界。\\n【詞義與編制】「全」：使之完好、保全；「軍、旅、卒、伍」：古代軍隊編制，一軍萬二千五百人，一旅五百人，一卒百人，一伍五人；「不戰而屈人之兵」：透過政治謀略、外交博弈、伐謀伐交等非直接毀滅性手段使敵屈服。\\n【成本與戰略哲學】孫子將「全」置於「破」之上，其深刻哲理在於戰爭的目的是保全國家與人民，毀滅性的擊破會造成敵我雙方重大的生命與財富耗損。以最小成本達成戰略目的，才是至善之道。\\n【現代和平與博弈論】「不戰而屈人之兵」被現代戰略學與博弈論視為威懾理論、危機管控與預防性外交的古代先驅，對現代國防安全與國際爭端和平解決具有歷久彌新的價值。"}},{"id":"art-of-war_ch-3_p-2","chapterId":"art-of-war_ch-3","order":2,"canonicalText":"故上兵伐謀，其次伐交，其次伐兵，其下攻城。攻城之法，為不得已；修櫓轒轀，具器械，三月而後成；距闉，又三月而後已；將不勝其忿，而蟻附之，殺士卒三分之一，而城不拔者，此攻之災也。","sentenceIds":["art-of-war_ch-3_p-2_s-1","art-of-war_ch-3_p-2_s-2","art-of-war_ch-3_p-2_s-3","art-of-war_ch-3_p-2_s-4","art-of-war_ch-3_p-2_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"},{"label":"維基文庫《孫子兵法》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%AD%AB%E5%AD%90%E5%85%B5%E6%B3%95"}],"readingAid":{"translation":"最高明的用兵是破壞敵人的謀略，其次是瓦解敵人的外交，再其次是在戰場擊敗敵軍，最下策才是攻城。攻城是不得已的辦法。製造大盾、攻城車及其他器械，要三個月；修築攻城土山，又要三個月。將領若抑制不住憤怒，驅使士卒像螞蟻般攀城，死傷三分之一仍攻不下，這就是攻城造成的災難。","analysis":"【主旨】戰略手段依成本排序：先破壞敵方計畫，再瓦解其外援，其次才野戰，強攻城池最下且只可不得已而用。\\n【詞義】「伐謀」是使敵謀不能成立；「伐交」是破壞敵方外交聯盟；「櫓」可指大型盾具，「轒轀」是蒙以皮革等防護的攻城車；「距闉」多解為築土山逼近城牆；「蟻附」比喻士卒密集攀城。\\n【章法】前四句形成手段階梯，後半用兩個「三月」和「殺士卒三分之一」把攻城代價具體化。\\n【思想】本段批評將領因憤怒而把士卒投入無效強攻，將情緒控制列為指揮責任；「攻城不得已」不是永不攻城，而是必須證明其他較低成本方案不可行。"}},{"id":"art-of-war_ch-3_p-3","chapterId":"art-of-war_ch-3","order":3,"canonicalText":"故善用兵者，屈人之兵，而非戰也；拔人之城，而非攻也；毀人之國，而非久也。必以全爭於天下，故兵不頓，利可全，此謀攻之法也。故用兵之法，十則圍之，五則攻之，倍則分之，敵則能戰之，少則能守之，不若則能避之。故小敵之堅，大敵之擒也。","sentenceIds":["art-of-war_ch-3_p-3_s-1","art-of-war_ch-3_p-3_s-2","art-of-war_ch-3_p-3_s-3","art-of-war_ch-3_p-3_s-4","art-of-war_ch-3_p-3_s-5","art-of-war_ch-3_p-3_s-6"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"},{"label":"維基文庫《孫子兵法》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%AD%AB%E5%AD%90%E5%85%B5%E6%B3%95"}],"readingAid":{"translation":"善於用兵的人，使敵軍屈服而不必交戰，奪取敵城而不靠強攻，滅亡敵國而不必久戰；務求以完整的力量爭勝天下，使軍隊不受挫而利益得以保全，這就是謀攻的原則。兵力十倍於敵便包圍，五倍便進攻，兩倍便設法分散敵軍，勢均力敵便要善戰，兵力較少便要善守，實力不如便應避開。弱小的一方若只知固守硬拚，終會成為強敵的俘虜。","analysis":"【主旨】謀攻要以保存自身與目標的完整性爭勝，並依相對兵力選擇圍、攻、分、戰、守、避，而非不問條件地硬拚。\\n【詞義】「非戰、非攻、非久」指不靠正面決戰、強攻與久戰；「全爭」是以完整方式取得戰略利益；「頓」是困頓耗損。「倍則分之」古注有分我兵、分敵兵兩系解釋，本譯採較常見的設法分散敵軍；「敵」是勢均；「不若」是整體不如。\\n【章法】先重申全勝，後列六級兵力對策，再以小敵固執終為大敵所擒作警告。\\n【思想】數量比例是便於說明的相對優勢模型，不是現代戰場的固定公式；情報、地形、訓練與科技都會改變有效戰力。撤避和防守在此是理性選項，不等於怯懦。"}},{"id":"art-of-war_ch-3_p-4","chapterId":"art-of-war_ch-3","order":4,"canonicalText":"夫將者，國之輔也，輔周則國必強，輔隙則國必弱。故軍之所以患於君者三：不知三軍之不可以進，而謂之進；不知三軍之不可以退，而謂之退；是謂縻軍。不知三軍之事，而同三軍之政，則軍士惑矣。不知三軍之權，而同三軍之任，則軍士疑矣。三軍既惑且疑，則諸侯之難至矣，是謂亂軍引勝。","sentenceIds":["art-of-war_ch-3_p-4_s-1","art-of-war_ch-3_p-4_s-2","art-of-war_ch-3_p-4_s-3","art-of-war_ch-3_p-4_s-4","art-of-war_ch-3_p-4_s-5","art-of-war_ch-3_p-4_s-6","art-of-war_ch-3_p-4_s-7"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"},{"label":"維基文庫《孫子兵法》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%AD%AB%E5%AD%90%E5%85%B5%E6%B3%95"}],"readingAid":{"translation":"將領是國君的輔佐。輔佐周密，國家必強；輔佐有缺失，國家必弱。國君危害軍隊的情形有三種：不知道軍隊不能前進卻命令前進，不知道不能後退卻命令後退，這叫束縛軍隊；不懂軍中事務卻幹預軍政，使士卒迷惑；不懂軍事權變卻幹預指揮，使士卒疑慮。軍隊既迷惑又疑慮，諸侯便會乘隙進犯；這叫擾亂自己的軍隊而送掉勝利。","analysis":"【主旨】將領是國家軍事能力的重要支柱；君主若不了解前線條件卻直接幹預進退、軍政與權變，會使軍隊迷惑而把勝機讓給敵人。\\n【詞義】「輔周」是輔佐完密，「輔隙」是有缺漏；「縻軍」是束縛軍隊；兩個「同」有參預、干涉之意；「權」是臨機處置；「亂軍引勝」是自亂其軍而把勝利引向敵方。\\n【章法】三患依序從錯誤命令、幹預行政到幹預專業指揮，結果由惑、疑推至外敵乘隙。\\n【界限】這不是主張軍權不受文人政府監督，而是區分戰略目標、合法監督與即時專業指揮；現代制度仍須有清楚授權、問責和文官統制。"}},{"id":"art-of-war_ch-3_p-5","chapterId":"art-of-war_ch-3","order":5,"canonicalText":"故知勝者有五：知可以戰與不可以戰者勝，識眾寡之用者勝，上下同欲者勝，以虞待不虞者勝，將能而君不御者勝；此五者，知勝之道也。","sentenceIds":["art-of-war_ch-3_p-5_s-1","art-of-war_ch-3_p-5_s-2"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"},{"label":"維基文庫《孫子兵法》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%AD%AB%E5%AD%90%E5%85%B5%E6%B3%95"}],"readingAid":{"translation":"預知勝利有五項條件：知道何時可以戰、何時不可以戰；懂得如何運用多兵與少兵；上下目標一致；自己有準備而等待沒有準備的敵人；將領有才能而君主不從中牽制。掌握這五點，就是預知勝利的方法。","analysis":"【主旨】能預判勝負的五項條件，是戰與不戰的判斷、眾寡運用、上下同欲、準備優勢，以及將領專業不受不當牽制。\\n【詞義】「識眾寡之用」不是只看人數，而是懂得不同兵力規模如何配置；「虞」是有準備，「不虞」是無備；「御」在此是牽制、幹預。\\n【章法】五個「……者勝」平行列舉，最後以「知勝之道」總收，回應〈始計〉以比較條件預見勝負。\\n【思想】五項互相制約：同欲不能取代專業，準備也不能補救錯誤的戰爭選擇。現代閱讀尤其應把「君不御」理解為授權邊界，而非取消政治與法律責任。"}},{"id":"art-of-war_ch-3_p-6","chapterId":"art-of-war_ch-3","order":6,"canonicalText":"故曰：知彼知己，百戰不殆；不知彼而知己，一勝一負；不知彼，不知己，每戰必敗。","sentenceIds":["art-of-war_ch-3_p-6_s-1","art-of-war_ch-3_p-6_s-2","art-of-war_ch-3_p-6_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"},{"label":"維基文庫《孫子兵法》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%AD%AB%E5%AD%90%E5%85%B5%E6%B3%95"}],"readingAid":{"translation":"所以說：既了解對方，也了解自己，縱使多次交戰也不致陷入危殆；不了解對方而只了解自己，勝負各有可能；既不了解對方，也不了解自己，每次交戰都必然失敗。","analysis":"【主旨】可靠決策必須同時建立敵情與己情兩套認識；任何一邊缺失，都會降低勝算。\\n【詞義】「彼」包括敵方目標、能力、部署與限制；「己」包括自身資源、士氣、制度與弱點；「百戰」是多次作戰的概稱；「不殆」是不陷於危敗，不等於保證每戰全勝。「一勝一負」表達勝負不定。\\n【章法】由知彼知己、只知己、兩者皆不知三級遞降，結果由不殆降到勝負參半，再到必敗。\\n【思想】名句常被抽離前文；實際上「知」來自五事七計、情報比較和是否可戰的判斷，不是主觀自信。真正知己也包括承認不可戰、應守或應避。"}},{"id":"art-of-war_ch-4_p-1","chapterId":"art-of-war_ch-4","order":1,"canonicalText":"孫子曰：昔之善戰者，先為不可勝，以待敵之可勝，不可勝在己，可勝在敵。故善戰者，能為不可勝，不能使敵必可勝。故曰：勝可知，而不可為。","sentenceIds":["art-of-war_ch-4_p-1_s-1","art-of-war_ch-4_p-1_s-2","art-of-war_ch-4_p-1_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"},{"label":"維基文庫《孫子兵法》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%AD%AB%E5%AD%90%E5%85%B5%E6%B3%95"}],"readingAid":{"translation":"孫子說：古代善戰的人，先使自己立於不敗之地，再等待敵人出現可以被擊敗的機會。能否不被戰勝取決於自己；能否戰勝敵人，取決於敵人是否暴露破綻。因此善戰者能做到自己不可被勝，卻不能強迫敵人一定出現可勝之機。所以說，勝利可以預見，卻不能勉強求得。","analysis":"【主旨】善戰者先控制自己能控制的部分，使自身不易被擊敗，再等待敵方出現可利用的敗因。\\n【詞義】「為不可勝」是建立不敗條件；「可勝在敵」是敵人是否暴露破綻取決於其行動；「勝可知」指可由情勢判斷；「不可為」是不能憑主觀意願強造敵人的漏洞。\\n【章法】以「不可勝／可勝」「在己／在敵」「可知／不可為」三組對偶，嚴格區分防敗與制勝。\\n【思想】這不是被動等待，而是先完成組織、情報、後勤與防護，再持續觀察。它也不是說人完全不能塑造敵勢；後篇仍談示形誘敵，但不能保證敵人必然按預期犯錯。"}},{"id":"art-of-war_ch-4_p-2","chapterId":"art-of-war_ch-4","order":2,"canonicalText":"不可勝者，守也；可勝者，攻也。守則不足，攻則有餘。善守者，藏於九地之下；善攻者，動於九天之上，故能自保而全勝也。","sentenceIds":["art-of-war_ch-4_p-2_s-1","art-of-war_ch-4_p-2_s-2","art-of-war_ch-4_p-2_s-3","art-of-war_ch-4_p-2_s-4","art-of-war_ch-4_p-2_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"},{"label":"維基文庫《孫子兵法》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%AD%AB%E5%AD%90%E5%85%B5%E6%B3%95"}],"readingAid":{"translation":"要使自己不被戰勝，採取的是防守；敵人已有可勝之隙，採取的是進攻。採取防守，表示我方取勝條件尚不足；採取進攻，表示我方取勝條件已有餘。善守者隱蔽得彷彿藏在九地之下，善攻者發動得彷彿來自九天之上，因此既能保全自己，又能取得完整勝利。","analysis":"【主旨】攻守不是固定性格，而是取勝條件不足或有餘時的不同選擇；最高標準是守能自保、攻能全勝。\\n【詞義】「守則不足」是可供進攻的有利條件不足，不是說防守者能力低劣；「攻則有餘」是攻勝條件充足；「九地之下／九天之上」是極言隱蔽之深、發動之高遠迅疾。\\n【章法】前四個短句作定義與因果，後用上下極端意象形成鮮明攻守對照。\\n【思想】本段反對為進攻而進攻，也反對把防守污名化。攻守轉換的判準是相對條件與風險，而不是將領好勇或畏縮。"}},{"id":"art-of-war_ch-4_p-3","chapterId":"art-of-war_ch-4","order":3,"canonicalText":"見勝，不過眾人之所知，非善之善者也。戰勝，而天下曰善，非善之善者也。故舉秋毫，不為多力；見日月，不為明目；聞雷霆，不為聰耳。古之善戰者，勝於易勝者；故善戰者之勝也，無智名，無勇功。故其戰勝不忒，不忒者，其措必勝，勝已敗者也。故善戰者，立於不敗之地，而不失敵之敗也。是故勝兵先勝，而後求戰；敗兵先戰，而後求勝。","sentenceIds":["art-of-war_ch-4_p-3_s-1","art-of-war_ch-4_p-3_s-2","art-of-war_ch-4_p-3_s-3","art-of-war_ch-4_p-3_s-4","art-of-war_ch-4_p-3_s-5","art-of-war_ch-4_p-3_s-6","art-of-war_ch-4_p-3_s-7","art-of-war_ch-4_p-3_s-8","art-of-war_ch-4_p-3_s-9","art-of-war_ch-4_p-3_s-10","art-of-war_ch-4_p-3_s-11"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"},{"label":"維基文庫《孫子兵法》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%AD%AB%E5%AD%90%E5%85%B5%E6%B3%95"}],"readingAid":{"translation":"只看出一般人也能看出的勝利，不算最高明；打勝仗而天下人都稱好，也不算最高明。舉起秋毫不能算力大，看見日月不能算眼明，聽見雷聲不能算耳聰。古代所謂善戰者，總是戰勝容易戰勝的敵人，所以他的勝利沒有智謀的名聲，也沒有勇武的功績。他取勝不出差錯，因為採取的措施必然成功，所戰勝的是已陷於敗勢的敵人。善戰者先使自己立於不敗之地，又不錯過擊敗敵人的機會。因此勝利的軍隊先具備勝利條件再求交戰，失敗的軍隊則先交戰再企求僥倖取勝。","analysis":"【主旨】最高明的勝利在交戰前已由條件建構完成，看來平常，甚至沒有智勇名聲；它不是在危局中僥倖逆轉。\\n【詞義】「見勝」是看見勝機；秋毫、日月、雷霆都極易舉、見、聞，用來說明顯而易見不算特殊能力；「不忒」是不出差錯；「措」是措施、部署；「勝已敗者」指所勝之敵已陷敗勢；「不失敵之敗」是不錯過敵人可敗的時機。\\n【章法】先否定世俗稱頌的顯赫勝利，再用三個日常比喻，最後提出「先勝而後求戰」的因果次序。\\n【思想】「易勝」不是挑弱者欺凌，而是透過準備與形勢管理，把高不確定的戰鬥變成低風險行動；它要求組織重視看不見的前置工作，而非英雄式冒險。"}},{"id":"art-of-war_ch-4_p-4","chapterId":"art-of-war_ch-4","order":4,"canonicalText":"善用兵者，修道而保法，故能為勝敗之政。兵法：「一曰度，二曰量，三曰數，四曰稱，五曰勝；地生度，度生量，量生數，數生稱，稱生勝。」故勝兵若以鎰稱銖，敗兵若以銖稱鎰。勝者之戰民也，若決積水於千仞之谿，形也。","sentenceIds":["art-of-war_ch-4_p-4_s-1","art-of-war_ch-4_p-4_s-2","art-of-war_ch-4_p-4_s-3","art-of-war_ch-4_p-4_s-4","art-of-war_ch-4_p-4_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"},{"label":"維基文庫《孫子兵法》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%AD%AB%E5%AD%90%E5%85%B5%E6%B3%95"}],"readingAid":{"translation":"善於用兵的人修明政治、確保法制，因而能掌握勝敗的主動權。兵法判斷軍力有五個步驟：度量土地，估算物資，計算兵員，衡量實力，最後判定勝負。土地決定尺度，尺度決定容量，容量決定數量，數量決定實力比較，實力比較決定勝負。勝軍對敗軍，如用鎰去稱銖，力量懸殊；勝軍投入戰鬥，就像決開高山深谷中的積水，奔瀉而下，這就是軍事形勢。","analysis":"【主旨】善戰者先修明共同原則、保存制度，再由土地、容量、兵數和力量比較逐級判勝，最終形成壓倒性的軍形。\\n【詞義】「修道」承〈始計〉的上下同意與政治基礎；「保法」是確保編制、職責、軍需等制度；「政」可解為主宰、決定。「度、量、數、稱、勝」是從空間條件推算資源與有效戰力的鏈條；鎰重而銖輕，用來比喻懸殊。\\n【章法】前句說制度前提，中段以五項相生建立計算流程，末段用天平與決水兩個物理意象呈現靜態力量差和動態釋放。\\n【思想】「形」是可觀察、可計量的力量配置，不只是外表陣形。數據必須建立在可靠制度與實情之上；若資料失真，再精密的計算也不能產生真正勝勢。"}},{"id":"art-of-war_ch-5_p-1","chapterId":"art-of-war_ch-5","order":1,"canonicalText":"孫子曰：凡治眾如治寡，分數是也。鬥眾如鬥寡，形名是也。三軍之眾，可使必受敵而無敗者，奇正是也。兵之所加，如以碬投卵者，虛實是也。","sentenceIds":["art-of-war_ch-5_p-1_s-1","art-of-war_ch-5_p-1_s-2","art-of-war_ch-5_p-1_s-3","art-of-war_ch-5_p-1_s-4"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"},{"label":"維基文庫《孫子兵法》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%AD%AB%E5%AD%90%E5%85%B5%E6%B3%95"}],"readingAid":{"translation":"孫子說：治理大部隊如同治理小部隊，關鍵在合理編制；指揮大部隊作戰如同小部隊，關鍵在旗幟號令。要使全軍承受敵人攻擊而不敗，靠的是正兵與奇兵的配合；攻擊敵軍像用石頭擊碎雞蛋，靠的是避實擊虛。","analysis":"【主旨】大軍能像小部隊一樣治理、指揮與作戰，靠的不是將領事事親管，而是編制、通信、奇正配合與集中打擊虛弱點。\\n【詞義】「分數」指分級編制與人數配置；「形名」是旗幟、金鼓等可見可聞的指揮信號；「奇正」是常規接戰與出敵不意力量的配合，角色可相互轉換；「碬」為堅石或磨石，投卵比喻以實擊虛。\\n【章法】四個「……是也」依次回答治眾、鬥眾、受敵不敗與攻敵必破，各由組織走向戰術效果。\\n【思想】「勢」首先來自系統設計：編制讓規模可控，信號讓行動協同，奇正讓敵難預測，虛實讓力量不浪費。這比單靠個人勇武更可複製。"}},{"id":"art-of-war_ch-5_p-2","chapterId":"art-of-war_ch-5","order":2,"canonicalText":"凡戰者，以正合，以奇勝。故善出奇者，無窮如天地，不竭如江河，終而復始，日月是也；死而復生，四時是也。聲不過五，五聲之變，不可勝聽也。色不過五，五色之變，不可勝觀也。味不過五，五味之變，不可勝嘗也。戰勢不過奇正，奇正之變，不可勝窮也。奇正相生，如循環之無端，孰能窮之哉！","sentenceIds":["art-of-war_ch-5_p-2_s-1","art-of-war_ch-5_p-2_s-2","art-of-war_ch-5_p-2_s-3","art-of-war_ch-5_p-2_s-4","art-of-war_ch-5_p-2_s-5","art-of-war_ch-5_p-2_s-6","art-of-war_ch-5_p-2_s-7","art-of-war_ch-5_p-2_s-8"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"},{"label":"維基文庫《孫子兵法》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%AD%AB%E5%AD%90%E5%85%B5%E6%B3%95"}],"readingAid":{"translation":"一般作戰，以正兵迎敵，以奇兵取勝。善於出奇的人，其變化像天地一樣無窮，像江河一樣不竭；終而復始如日月運行，死而復生如四季循環。聲音不過五種，組合起來卻聽不勝聽；顏色不過五種，變化起來卻看不勝看；味道不過五種，調和起來卻嘗不勝嘗。戰勢不外奇、正兩類，奇正的變化卻無窮無盡。奇正相互轉化，如圓環沒有起點，誰能窮盡呢？","analysis":"【主旨】作戰基本上只有正與奇兩類作用，但二者互換、組合，能像聲色味的有限元素一樣產生無窮變化。\\n【詞義】「正合」是以正兵承擔正面接觸或常規任務；「奇勝」是以敵所不測的力量或方式取得決定效果。「奇」不是永遠固定的預備隊，也不等同奇怪計謀；對敵已知者可成正，未知者可成奇。\\n【章法】天地、江河、日月、四時先寫循環不竭，再用五聲、五色、五味三組類比，最後回到奇正相生。\\n【思想】變化無窮不等於任意變招；一切仍以有限兵力、任務和敵情為材料。真正能力在重組與轉換，而不是追求表面新奇。"}},{"id":"art-of-war_ch-5_p-3","chapterId":"art-of-war_ch-5","order":3,"canonicalText":"激水之疾，至於漂石者，勢也。鷙鳥之擊，至於毀折者，節也。是故善戰者，其勢險，其節短，勢如張弩，節如機發。","sentenceIds":["art-of-war_ch-5_p-3_s-1","art-of-war_ch-5_p-3_s-2","art-of-war_ch-5_p-3_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"},{"label":"維基文庫《孫子兵法》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%AD%AB%E5%AD%90%E5%85%B5%E6%B3%95"}],"readingAid":{"translation":"湍急水流快到能漂動石頭，靠的是所形成的勢；猛禽搏擊快到能摧折獵物，靠的是出擊的節度與時機。因此善戰者所造成的勢險峻有力，出擊的節度短促；勢像已張滿的弩，節像機括突然發動。","analysis":"【主旨】有效打擊由兩部分構成：先蓄成足以壓倒對方的「勢」，再以短促準確的「節」釋放。\\n【詞義】「激水」是湍急水流；「漂石」極言水勢能移動重物；「鷙鳥」是猛禽；「節」兼含節度、距離與發動時機，不只是節奏；「機」是弩的發射機括。\\n【章法】水與猛禽分別定義勢、節，末用張弩與發機把蓄力和釋放連成一個過程。\\n【思想】只有強大資源而沒有準確時機，力量可能耗散；只有快速行動而無前置蓄勢，也難有決定效果。此段補足「勢」的動態機制。"}},{"id":"art-of-war_ch-5_p-4","chapterId":"art-of-war_ch-5","order":4,"canonicalText":"紛紛紜紜，鬥亂，而不可亂也。渾渾沌沌，形圓，而不可敗也。亂生於治，怯生於勇，弱生於強。治亂，數也。勇怯，勢也。強弱，形也。故善動敵者，形之，敵必從之；予之，敵必取之；以利動之，以實待之。","sentenceIds":["art-of-war_ch-5_p-4_s-1","art-of-war_ch-5_p-4_s-2","art-of-war_ch-5_p-4_s-3","art-of-war_ch-5_p-4_s-4","art-of-war_ch-5_p-4_s-5","art-of-war_ch-5_p-4_s-6","art-of-war_ch-5_p-4_s-7","art-of-war_ch-5_p-4_s-8","art-of-war_ch-5_p-4_s-9"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"},{"label":"維基文庫《孫子兵法》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%AD%AB%E5%AD%90%E5%85%B5%E6%B3%95"}],"readingAid":{"translation":"戰場看似紛亂交錯，自己的指揮卻不能真正混亂；陣勢看似渾沌迴旋，自己的部署卻不可被擊敗。能向敵人顯示混亂，根源在內部治理嚴整；能顯示怯弱，根源在實際勇強；能顯示弱小，根源在真實強大。治或亂取決於編制指揮，勇或怯取決於所形成的態勢，強或弱取決於向敵顯示的軍形。所以善於調動敵人的人，向敵展示某種形態，敵人便會依此反應；給出可取之利，敵人便來取。以利益調動敵人，自己則以充實力量等待。","analysis":"【主旨】外部可示亂、示怯、示弱，前提是內部真正治、勇、強；利用敵人對所見利益與軍形的反應，才能調動它進入預設態勢。\\n【詞義】「形圓」多指陣勢周轉圓活；「亂生於治」是偽亂必以真治為基礎；「數」承上文編制；「形之」是向敵顯示可被判讀的形態；「予之」是給出誘餌或利益；「實待之」是以充實準備等候。\\n【章法】先寫亂中不亂，再以三組表象／根基揭示欺敵條件，最後落到示形、予利、設伏的因果鏈。\\n【界限】若本身組織已亂，模仿混亂只會真的失控。誘敵也不是敵必然上當的魔法，必須建立在對其需求、情報與風險偏好的可靠判斷上。"}},{"id":"art-of-war_ch-5_p-5","chapterId":"art-of-war_ch-5","order":5,"canonicalText":"故善戰者，求之於勢，不責於人，故能擇人任勢；任勢者，其戰人也，如轉木石，木石之性，安則靜，危則動，方則止，圓則行。故善戰人之勢，如轉圓石於千仞之山者，勢也。","sentenceIds":["art-of-war_ch-5_p-5_s-1","art-of-war_ch-5_p-5_s-2","art-of-war_ch-5_p-5_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"},{"label":"維基文庫《孫子兵法》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%AD%AB%E5%AD%90%E5%85%B5%E6%B3%95"}],"readingAid":{"translation":"善戰者追求形成有利態勢，而不苛求個別士卒，所以能選擇適當人才去運用態勢。善於任勢，就像轉動木石：木石在平地安穩便靜止，在斜坡危險便滾動；方形容易停止，圓形容易滾動。善戰者造成的勢，就像讓圓石從千仞高山滾下，力量不可阻擋。","analysis":"【主旨】善戰者把主要責任放在創造能使普通人發揮作用的態勢，不把成敗全推給個人的超常表現。\\n【詞義】「不責於人」不是不考核人員，而是不苛求人人憑孤勇創造勝利；「擇人任勢」是選合適人才承擔適合任務，也可讀為任用人而利用勢；「危」與安相對，指處在傾斜不穩的位置；圓石下高山是結構放大力量。\\n【章法】先提出管理原則，再由木石的安危、方圓說運動條件，最後以千仞山上轉圓石作總喻。\\n【思想】這是一種系統責任觀：好的組織讓正確行動成為容易選項，壞的組織則要求英雄不斷補洞。但「勢」不能抹除選人、訓練與倫理責任。"}},{"id":"art-of-war_ch-6_p-1","chapterId":"art-of-war_ch-6","order":1,"canonicalText":"孫子曰：凡先處戰地而待敵者佚，後處戰地而趨戰者勞。故善戰者，致人而不致於人。能使敵人自至者，利之也；能使敵不得至者，害之也。故敵佚能勞之，飽能飢之，安能動之。","sentenceIds":["art-of-war_ch-6_p-1_s-1","art-of-war_ch-6_p-1_s-2","art-of-war_ch-6_p-1_s-3","art-of-war_ch-6_p-1_s-4","art-of-war_ch-6_p-1_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"},{"label":"維基文庫《孫子兵法》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%AD%AB%E5%AD%90%E5%85%B5%E6%B3%95"}],"readingAid":{"translation":"孫子說：先到戰地、從容等待敵人的一方安逸，後到戰地、急忙趕赴交戰的一方疲勞。所以善戰者能調動敵人，而不被敵人調動。能使敵人自行前來，是用可圖之利引誘；能使敵人不能到達，是用威脅或障礙加以妨害。因此，敵人安逸，可以設法使它疲勞；糧食充足，可以設法使它陷於缺糧；駐守安定，可以設法迫它移動。","analysis":"【主旨】掌握主動權的核心，是先佔時間與位置優勢，再透過利害改變敵人的行程、補給和部署。\\n【詞義】「佚」通逸，指從容休整；「趨戰」是急赴戰地；「致人」是使敵依我意圖而來，「不致於人」是不被敵方牽引；「利之／害之」分別是展示利益與造成妨害。\\n【章法】先以先到、後到對比勞逸，再抽象成致人原則，最後列勞、飢、動三種可操作結果。\\n【思想】主動不是凡事搶先，而是讓對方回應自己設定的問題。這仍取決於敵人是否認為利益可信、威脅必救，並非單方面意志即可實現。"}},{"id":"art-of-war_ch-6_p-2","chapterId":"art-of-war_ch-6","order":2,"canonicalText":"出其所不趨，趨其所不意；行千里而不勞者，行於無人之地也；攻而必取者，攻其所不守也；守而必固者，守其所不攻也。故善攻者，敵不知其所守；善守者，敵不知其所攻。微乎微乎！至於無形；神乎神乎！至於無聲，故能為敵之司命。進而不可禦者，衝其虛也；退而不可追者，速而不可及也。故我欲戰，敵雖高壘深溝，不得不與我戰者，攻其所必救也；我不欲戰，雖劃地而守之，敵不得與我戰者，乖其所之也。","sentenceIds":["art-of-war_ch-6_p-2_s-1","art-of-war_ch-6_p-2_s-2","art-of-war_ch-6_p-2_s-3","art-of-war_ch-6_p-2_s-4","art-of-war_ch-6_p-2_s-5","art-of-war_ch-6_p-2_s-6","art-of-war_ch-6_p-2_s-7","art-of-war_ch-6_p-2_s-8","art-of-war_ch-6_p-2_s-9","art-of-war_ch-6_p-2_s-10","art-of-war_ch-6_p-2_s-11","art-of-war_ch-6_p-2_s-12","art-of-war_ch-6_p-2_s-13","art-of-war_ch-6_p-2_s-14"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"},{"label":"維基文庫《孫子兵法》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%AD%AB%E5%AD%90%E5%85%B5%E6%B3%95"}],"readingAid":{"translation":"從敵人來不及趕赴救援之處出動，向敵人意料不到之處急進。行軍千里而不疲勞，是因為走在沒有敵軍阻攔的地區；進攻必能奪取，是攻擊敵人沒有防守之處；防守必能穩固，是守在敵人不知道或無從進攻之處。所以善攻者使敵人不知道該守哪裡，善守者使敵人不知道該攻哪裡。微妙啊，微妙到不露可判斷的形態；神妙啊，神妙到不發可預知的聲息，因此能掌握敵軍命運。前進而不可抵禦，是因衝擊敵人空虛處；後退而不可追及，是因速度快得追不上。所以我想交戰時，敵人即使築高壘、挖深溝，也不得不出來同我作戰，因為我攻擊它非救不可之處；我不想交戰時，即使只是劃地防守，敵人也無法迫我交戰，因為我使它的進攻方向與目標相背離。","analysis":"【主旨】善攻守者以路線、目標、隱蔽與速度控制交戰：攻不守、守不攻、進擊虛、退使不可及。\\n【詞義】「出其所不趨」是出現在敵人不能迅速趕赴之處，和後文「攻其所必救」不同；「無形、無聲」是讓敵人無從判斷部署與意圖，不是物理消失；「司命」是掌握生死主動；「劃地而守」極言不靠堅固工事；「乖其所之」是使敵的趨向偏離。\\n【章法】前半列行、攻、守三種空間優勢，中段推到隱蔽，後半用欲戰／不欲戰說如何迫戰與避戰。\\n【界限】「必取、必固」是以理想條件強調原則，不能當成無條件保證；情報錯誤、敵人放棄必救目標或另闢路線，都可能使設計失效。"}},{"id":"art-of-war_ch-6_p-3","chapterId":"art-of-war_ch-6","order":3,"canonicalText":"故形人而我無形，則我專而敵分，我專為一，敵分為十，是以十攻其一也。則我眾而敵寡，能以眾擊寡，則我之所與戰者，約矣。","sentenceIds":["art-of-war_ch-6_p-3_s-1","art-of-war_ch-6_p-3_s-2"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"},{"label":"維基文庫《孫子兵法》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%AD%AB%E5%AD%90%E5%85%B5%E6%B3%95"}],"readingAid":{"translation":"使敵人顯露形態而我軍不露形跡，我軍兵力便能集中，敵軍卻不得不分散。我集中為一，敵人分散為十，就能用十倍兵力攻擊其中一處；如此我眾敵寡，實際與我交戰的敵軍便很有限。","analysis":"【主旨】迫使敵方暴露和分散，同時隱藏自己的主攻方向，就能在選定局部形成以眾擊寡。\\n【詞義】「形人」是使敵顯露部署，也含以示形迫其回應；「我無形」是不讓敵看清我方真正配置；「專」是集中、專一；「十攻其一」描述局部兵力比，不一定是全軍總數真的十倍；「約」是少、有限。\\n【章法】形／無形導出專／分，再導出眾／寡，形成連續因果，而非直接把全軍人數當成優勢。\\n【思想】集中優勢不是平均強大，而是用資訊差選擇時間地點，把有限資源集中於關鍵局部；同時也須警惕過度集中造成其他方向暴露。"}},{"id":"art-of-war_ch-6_p-4","chapterId":"art-of-war_ch-6","order":4,"canonicalText":"吾所與戰之地不可知，不可知，則敵所備者多，敵所備者多，則我所與戰者寡矣。故備前則後寡，備後則前寡，備左則右寡，備右則左寡，無所不備，則無所不寡。寡者，備人者也；眾者，使人備己者也。","sentenceIds":["art-of-war_ch-6_p-4_s-1","art-of-war_ch-6_p-4_s-2","art-of-war_ch-6_p-4_s-3","art-of-war_ch-6_p-4_s-4"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"},{"label":"維基文庫《孫子兵法》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%AD%AB%E5%AD%90%E5%85%B5%E6%B3%95"}],"readingAid":{"translation":"敵人不知道我軍將在何處交戰，就不得不處處防備；防備的地方越多，每處可用兵力便越少。防備前方，後方便薄弱；防備後方，前方便薄弱；防備左方，右方便薄弱；防備右方，左方便薄弱；處處防備，便處處薄弱。兵力少，是因為被動防備別人；兵力多，是因為迫使別人防備自己。","analysis":"【主旨】當敵人不知道我方決戰地點，就會在多個方向分散防備；我方因而能在選定方向取得相對多數。\\n【詞義】首句主語是敵方：敵不知道「吾所與戰之地」；「前後左右」是防備方向的概括；「無所不備，無所不寡」指出有限兵力無法在所有位置同時充實；「備人」是被動防備對手，「使人備己」是迫使對方分兵。\\n【章法】先提出不確定造成多備，再用前後左右排比演示資源分散，最後把寡眾重新定義為主動權的結果。\\n【思想】這是有限資源下的配置原理，不表示全面防禦必然錯誤；關鍵在威脅優先級、機動預備隊與情報能否降低不確定性。"}},{"id":"art-of-war_ch-6_p-5","chapterId":"art-of-war_ch-6","order":5,"canonicalText":"故知戰之地，知戰之日，則可千里而會戰。不知戰地，不知戰日，則左不能救右，右不能救左，前不能救後，後不能救前，而況遠者數十里，近者數裏乎？以吾度之，越人之兵雖多，亦奚益於勝哉？故曰：勝可為也，敵雖眾，可使無鬥。","sentenceIds":["art-of-war_ch-6_p-5_s-1","art-of-war_ch-6_p-5_s-2","art-of-war_ch-6_p-5_s-3","art-of-war_ch-6_p-5_s-4"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"},{"label":"維基文庫《孫子兵法》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%AD%AB%E5%AD%90%E5%85%B5%E6%B3%95"}],"readingAid":{"translation":"如果預先知道交戰地點和日期，即使遠行千里也能會戰；若不知道地點與日期，左軍不能救右軍，右軍不能救左軍，前軍不能救後軍，後軍不能救前軍，何況遠隔幾十里，即使相隔數裏也難以及時救援。依我判斷，越國兵雖多，對取勝又有什麼幫助？所以說，勝利可以主動創造；敵軍雖多，也能使他無法集中交戰。","analysis":"【主旨】知道決戰時間和地點，才能讓分散部隊按時集中；使敵不知，便可令其數量雖多卻不能共同作戰。\\n【詞義】「會戰」是如期會合交戰；「越人」指吳國所面對的越軍，帶有文本所處戰爭背景；「奚益於勝」是對勝利有何幫助；「勝可為」承上篇「勝不可為」而有條件地說：不能強迫敵人犯錯，卻可用示形與調動塑造局部勝勢；「無鬥」是不能集中形成有效戰鬥。\\n【章法】先正反比較知與不知戰期戰地，再以越軍為例，最後推出可塑造勝勢。\\n【思想】兩篇並不矛盾：「不可為」限制主觀強求，「可為」強調可藉情報、機動與分散敵軍創造條件。"}},{"id":"art-of-war_ch-6_p-6","chapterId":"art-of-war_ch-6","order":6,"canonicalText":"故策之而知得失之計，作之而知動靜之理，形之而知死生之地，角之而知有餘不足之處。故形兵之極，至於無形；無形，則深間不能窺，智者不能謀。因形而措勝於眾，眾不能知，人皆知我所以勝之形，而莫知吾所以制勝之形；故其戰勝不復，而應形於無窮。","sentenceIds":["art-of-war_ch-6_p-6_s-1","art-of-war_ch-6_p-6_s-2","art-of-war_ch-6_p-6_s-3","art-of-war_ch-6_p-6_s-4","art-of-war_ch-6_p-6_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"},{"label":"維基文庫《孫子兵法》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%AD%AB%E5%AD%90%E5%85%B5%E6%B3%95"}],"readingAid":{"translation":"所以，籌算分析敵人，可以知道其計畫的得失；挑動敵人，可以知道其動靜規律；使敵人顯露形態，可以知道哪些地形或部署關係生死；與敵試探較量，可以知道哪裡有餘、哪裡不足。部署兵力的最高境界，達到不讓敵人看出固定形態；沒有可判讀的形態，即使深藏的間諜也無法窺知，智謀之士也無從設計對策。依據敵人顯露的形態，把勝利措施呈現在眾人面前，眾人仍不能明白其中所以然。人們都知道我這次取勝所呈現的方式，卻不知道我在此前如何造成勝利。因此，取勝方式不重複，而是因應敵情無窮變化。","analysis":"【主旨】透過分析、挑動、示形和試探逐層取得敵情，再隱藏自己的固定模式，才能針對每次不同敵形制定勝法。\\n【詞義】「策之」是籌算衡量；「作之」是刺激使其發動；「形之」各註解有示形、察形之別，核心是使敵顯露與生死有關的部署條件；「角之」是較量試探；「深間」是深入潛伏的間諜；「措勝於眾」句讀可異，本譯採把制勝措施呈現於眾而眾仍不知其機理。\\n【章法】四個「而知」構成情報試探程序，無形則保障反情報，末段區分事後可見的勝形與事前不可見的制勝過程。\\n【思想】不重複的是具體方案，不是基本原則；若把「無形」理解為毫無組織或隨意改變，反而無法形成可靠行動。"}},{"id":"art-of-war_ch-6_p-7","chapterId":"art-of-war_ch-6","order":7,"canonicalText":"夫兵形象水，水之形，避高而趨下：兵之形，避實而擊虛；水因地而制流，兵因敵而制勝。故兵無常勢，水無常形；能因敵變化而取勝，謂之神。故五行無常勝，四時無常位，日有短長，月有死生。","sentenceIds":["art-of-war_ch-6_p-7_s-1","art-of-war_ch-6_p-7_s-2","art-of-war_ch-6_p-7_s-3","art-of-war_ch-6_p-7_s-4","art-of-war_ch-6_p-7_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"},{"label":"維基文庫《孫子兵法》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%AD%AB%E5%AD%90%E5%85%B5%E6%B3%95"}],"readingAid":{"translation":"用兵的形態像水。水流避開高處而流向低處，用兵避開敵人充實之處而攻擊空虛之處；水依地勢決定流向，軍隊依敵情決定勝法。因此用兵沒有固定態勢，水也沒有固定形狀；能隨敵情變化而取勝，才稱得上神妙。五行沒有永遠居勝的，四季沒有固定不移的位置，白晝有長短，月亮也有盈虧。","analysis":"【主旨】兵形如水：不與堅實處正面相撞，依敵方條件改變路徑，因而沒有可永久套用的固定勝法。\\n【詞義】「形」是力量表現與運行方式；「避高趨下」描述水順地勢流動；「避實擊虛」是避開敵方充實強點、打擊薄弱或未備處；「制流／制勝」是決定具體流向與勝法；「神」指應變精妙。「五行無常勝」採五行相勝而無一永勝之觀念；月之死生指晦朔盈虧。\\n【章法】水與兵逐句平行，先說避實，再說因勢，最後以五行、四時、日月三組週期現象證成無常。\\n【思想】「無常」不是沒有原則，恰恰以保存自己、識別虛實、集中優勢為常則；變的是落實方式。古代五行說是類比框架，不應當作現代自然科學證明。"}},{"id":"art-of-war_ch-7_p-1","chapterId":"art-of-war_ch-7","order":1,"canonicalText":"孫子曰：凡用兵之法，將受命於君，合軍聚眾，交和而舍，莫難於軍爭。軍爭之難者，以迂為直，以患為利。故迂其途，而誘之以利，後人發，先人至，此知迂直之計者也。故軍爭為利，軍爭為危。","sentenceIds":["art-of-war_ch-7_p-1_s-1","art-of-war_ch-7_p-1_s-2","art-of-war_ch-7_p-1_s-3","art-of-war_ch-7_p-1_s-4"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"},{"label":"維基文庫《孫子兵法》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%AD%AB%E5%AD%90%E5%85%B5%E6%B3%95"}],"readingAid":{"translation":"孫子說：用兵的一般程序，是將領接受君命，召集軍隊、組織部眾，與敵軍對峙駐紮；其中最困難的是爭奪先機。軍爭的難處，在於把迂迴變為近直，把不利轉為有利。因此故意迂迴行軍，又用利益牽制敵人，雖比敵人晚出發，卻能先到要地，這才懂得迂直之計。爭奪先機既有利益，也有危險。","analysis":"【主旨】軍爭是在雙方接觸前後爭奪有利位置與先機，難處是以迂迴造成實際領先、把途中風險轉成利益。\\n【詞義】「交和而舍」各家解法不一，大致指兩軍接近、對峙而駐止；「軍爭」不是軍內爭鬥，而是與敵爭利；「迂其途」可由我方走迂路，也可包含使敵繞路；「以患為利」是把不利條件轉化利用。\\n【章法】先說軍爭最難，再以後發先至說明迂直之計，末句同時標出利與危。\\n【思想】晚出而先至不靠單純疾走，而靠路線、誘敵、情報與目標選擇；任何機動優勢都伴隨補給、疲勞和失序風險。"}},{"id":"art-of-war_ch-7_p-2","chapterId":"art-of-war_ch-7","order":2,"canonicalText":"舉軍而爭利，則不及；委軍而爭利，則輜重捐。是故卷甲而趨，日夜不處，倍道兼行，百里而爭利，則擒三將軍，勁者先，疲者後，其法十一而至；五十里而爭利，則蹶上將軍，其法半至；卅里而爭利，則三分之二至。是故軍無輜重則亡，無糧食則亡，無委積則亡。故不知諸侯之謀者，不能豫交；不知山林、險阻、沮澤之形者，不能行軍，不能鄉導者，不能得地利。","sentenceIds":["art-of-war_ch-7_p-2_s-1","art-of-war_ch-7_p-2_s-2","art-of-war_ch-7_p-2_s-3","art-of-war_ch-7_p-2_s-4","art-of-war_ch-7_p-2_s-5","art-of-war_ch-7_p-2_s-6","art-of-war_ch-7_p-2_s-7","art-of-war_ch-7_p-2_s-8"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"},{"label":"維基文庫《孫子兵法》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%AD%AB%E5%AD%90%E5%85%B5%E6%B3%95"}],"readingAid":{"translation":"帶著全軍所有輜重裝備去爭奪戰略先機，行軍遲緩就會趕不及；丟棄輜重部隊去爭奪先機，後勤輜重就容易蒙受損失拋棄。所以收起鎧甲輕裝急進，日夜不停息地奔馳，以兩倍於常規的速度日夜兼程：如果奔襲百里去爭奪先機，那麼三軍將領都會遭到敵軍俘虜，體魄強勁的士兵走在前面，疲憊不堪的士兵落在後面，按照這種急行軍的規律只有十分之一的兵力能按時趕到；如果奔襲五十里去爭奪先機，前鋒主將就會受挫折，只有半數兵力能按時趕到；如果奔襲三十里去爭奪先機，也只有三分之二的兵力能到達。所以軍隊沒有輜重物資就會滅亡，沒有糧食供應就會滅亡，沒有物資儲備就會滅亡。因此，不瞭解周邊諸侯戰略圖謀的人，不能預先與之締結外交同盟；不熟悉山林、險阻、沼澤地形的人，不能貿然行軍；不能啟用當地嚮導的人，無法真正獲取地理優勢。","analysis":"【題解與軍爭後勤極限】本段為《孫子兵法・軍爭篇》核心，以精確的數字模型（百里、五十里、三十里）剖析輕軍冒進奪利的致命代價，確立後勤輜重在軍事戰略中的命脈地位。\\n【詞義訓詁】「舉軍」：全軍攜帶所有輜重物資；「委軍」：丟下後勤輜重大隊；「卷甲」：收起重甲輕裝；「蹶」：受挫、跌倒受損；「委積」：儲備之糧草物資；「沮澤」：水草叢生之泥濘沼澤；「鄉導」：引路之嚮導。\\n【軍事力學與生理極限】孫子揭示了速度與後勤、體力與戰鬥力之間的客觀物理規律。長途奔襲會造成隊伍脫節與士兵疲竭，使優勢兵力被分散消解；「軍無輜重則亡」更是兵家不可違背的鐵律。\\n【現代戰略後勤啟示】現代戰爭與重大企業專案推進中，盲目追求推進速度而忽視後勤供應鏈與團隊身心承受極限，往往是導致崩潰的主因；本章提供了嚴肅的風險控制警示。"}},{"id":"art-of-war_ch-7_p-3","chapterId":"art-of-war_ch-7","order":3,"canonicalText":"故兵以詐立，以利動，以分合為變者也，故其疾如風，其徐如林，侵掠如火，不動如山，難知如陰，動如雷霆。掠鄉分眾，廓地分利，懸權而動，先知迂直之計者勝，此軍爭之法也。","sentenceIds":["art-of-war_ch-7_p-3_s-1","art-of-war_ch-7_p-3_s-2"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"},{"label":"維基文庫《孫子兵法》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%AD%AB%E5%AD%90%E5%85%B5%E6%B3%95"}],"readingAid":{"translation":"所以軍事行動靠隱真示假建立，依據利益決定進退，以兵力分散、集中作為變化。因此，迅速時像風，舒緩整齊時像森林，侵襲時像烈火，駐止時像山嶽，隱蔽難知時像陰雲，發動時像雷霆。掠取敵境資源要分配兵力，擴展所得地域要分配利益，權衡輕重後纔行動。先懂得迂直之計的一方取勝，這是軍爭的原則。","analysis":"【主旨】軍爭的機動不是永遠求快，而是依目標在疾、徐、攻、守、隱、發六種狀態間有紀律地轉換。\\n【詞義】「以詐立」是以資訊欺敵建立行動條件；「分合」是兵力分散集中；「徐如林」重在行列整齊、徐進不亂；「陰」指幽暗難測；「廓地分利」可解拓地後分守、分配利益；「懸權」像懸秤般衡量輕重。\\n【章法】風林火山陰雷六喻把抽象機動轉成可感形象，隨後回到資源分配與權衡。\\n【界限】「侵掠如火」描述古代敵境作戰，不能成為傷害平民的正當化；現代軍事行動仍受區分、比例與必要性原則限制。"}},{"id":"art-of-war_ch-7_p-4","chapterId":"art-of-war_ch-7","order":4,"canonicalText":"軍政曰：「言不相聞，故為金鼓；視不相見，故為旌旗。」夫金鼓旌旗者，所以一人之耳目也；人既專一，則勇者不得獨進，怯者不得獨退，此用眾之法也。故夜戰多火鼓，晝戰多旌旗，所以變人之耳目也。","sentenceIds":["art-of-war_ch-7_p-4_s-1","art-of-war_ch-7_p-4_s-2","art-of-war_ch-7_p-4_s-3","art-of-war_ch-7_p-4_s-4","art-of-war_ch-7_p-4_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"},{"label":"維基文庫《孫子兵法》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%AD%AB%E5%AD%90%E5%85%B5%E6%B3%95"}],"readingAid":{"translation":"古代兵法《軍政》說：「在戰場上用語言指揮互相聽不見，所以要使用鑼鼓；用動作指揮互相看不見，所以要使用旌旗。」鑼鼓和旌旗，是用來統一全軍將士的耳朵和眼睛的。軍隊的行動既然已經統一，那麼勇敢的士兵就不能單獨前進，怯懦的士兵也不能單獨後退，這就是指揮大部隊作戰的方法。因此，夜間作戰要多用火光和擊鼓，白天作戰要多用旌旗，這都是為了適應並改變士兵的聽覺與視覺，從而統一指揮。","analysis":"【主旨】大部隊在噪音、距離與視線受限的戰場上，必須以統一的聽覺、視覺信號協同行動，避免個人擅進擅退。\\n【詞義】《軍政》是今已佚的古兵書；「金鼓」泛指鉦、鼓等聲號，「旌旗」是視覺信號；「一人之耳目」不是隻服務一人，而是使眾人視聽一致；「專一」是行動集中統一；「變人之耳目」是隨晝夜條件調整信息媒介。\\n【章法】先引權威說明信號由來，再推導紀律效果，最後分夜戰與晝戰。\\n【思想】本段本質是指揮通信：共同協議的信號降低協調成本。但統一行動不等於取消回報與判斷，可靠系統仍需處理誤傳、失聯和情勢變化。"}},{"id":"art-of-war_ch-7_p-5","chapterId":"art-of-war_ch-7","order":5,"canonicalText":"故三軍可奪氣，將軍可奪心。是故朝氣銳，晝氣惰，暮氣歸；故善用兵者，避其銳氣，擊其惰歸，此治氣者也。以治待亂，以靜待譁，此治心者也。以近待遠，以佚待勞，以飽待飢，此治力者也。","sentenceIds":["art-of-war_ch-7_p-5_s-1","art-of-war_ch-7_p-5_s-2","art-of-war_ch-7_p-5_s-3","art-of-war_ch-7_p-5_s-4","art-of-war_ch-7_p-5_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"},{"label":"維基文庫《孫子兵法》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%AD%AB%E5%AD%90%E5%85%B5%E6%B3%95"}],"readingAid":{"translation":"因此，對於敵方軍隊，可以挫傷其士氣；對於敵方將領，可以動搖其決心。一般來說，軍隊早晨剛出發時士氣銳盛，到了中午士氣就會懈怠，到了傍晚士氣就會衰落，士兵只一心想著回營休息。因此，善於用兵的人，會避開敵軍銳盛的士氣，而選擇在敵軍懈怠、思歸的時候發動攻擊，這就是掌握和控制「士氣」的方法。用我方的嚴整肅穆來對待敵軍的混亂，用我方的鎮定從容來對待敵軍的喧譁，這就是掌握和控制「心理」的方法。用我方靠近戰場來等待遠道而來的敵軍，用我方的休整安逸來等待疲憊的敵軍，用我方的糧食充足來等待飢餓的敵軍，這就是掌握和控制「戰鬥力」的方法。","analysis":"【主旨】可利用時間、秩序、距離、休整與補給差，削弱敵軍士氣、主將心志和實際體力。\\n【詞義】「奪氣」是挫奪部隊銳氣，「奪心」是動搖將領判斷；朝、晝、暮既可指一日士氣節律，也概括初銳、漸惰、思歸的階段；「治氣、治心、治力」是管理士氣、心理與體能條件。\\n【章法】先說可奪，再以銳—惰—歸三段變化說避實擊虛，最後列三組以己之治靜逸飽待敵之亂譁勞飢。\\n【思想】這不是宣稱士氣每天機械地晨高暮低，而是要求不在敵氣最盛時硬碰，並以後勤與休整形成可持續優勢。"}},{"id":"art-of-war_ch-7_p-6","chapterId":"art-of-war_ch-7","order":6,"canonicalText":"無邀正正之旗，勿擊堂堂之陣，此治變者也；故用兵之法，高陵勿向，背邱勿逆，佯北勿從，銳卒勿攻，餌兵勿食，歸師勿遏，圍師必闕，窮寇勿迫，此用兵之法也。","sentenceIds":["art-of-war_ch-7_p-6_s-1","art-of-war_ch-7_p-6_s-2"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"},{"label":"維基文庫《孫子兵法》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%AD%AB%E5%AD%90%E5%85%B5%E6%B3%95"}],"readingAid":{"translation":"不要攔截旗幟嚴整的敵軍，不要攻擊陣容壯盛的部隊，這是掌握臨敵變化。用兵原則是：不要仰攻佔據高地的敵人；不要迎擊背靠山丘而來的敵人；不要追趕假裝敗退的敵人；不要攻擊士氣銳利的部隊；不要吞下敵人的誘餌；不要阻截回國的軍隊；包圍敵軍要留缺口；不要逼迫走投無路的敵人。","analysis":"【主旨】不要攻擊秩序嚴整、地勢有利或銳氣正盛之敵；對敗退、誘餌、歸師和窮寇，也要辨別其心理與反擊風險。\\n【詞義】「邀」是半路截擊；「正正」「堂堂」寫旗幟陣容嚴整；「背丘」指敵背靠高地、順勢而來；「佯北」是假裝敗逃；「餌兵」是誘敵之兵；「圍師必闕」是包圍時故意留一缺口，使敵仍存逃生念頭；「窮寇」是陷於絕境之敵。\\n【章法】前兩禁總說不擊盛整，後列高陵至窮寇八項情境規則。\\n【思想】「勿迫」不是放棄追擊，而是避免把尚可控制的敵人逼成死戰；具體是否追、圍、攻仍須結合任務和風險，不能把清單當成脫離情境的禁令。"}},{"id":"art-of-war_ch-8_p-1","chapterId":"art-of-war_ch-8","order":1,"canonicalText":"孫子曰：凡用兵之法，將受命於君，合軍聚眾；圮地無舍，衢地合交，絕地無留，圍地則謀，死地則戰，途有所不由，軍有所不擊，城有所不攻，地有所不爭，君命有所不受。故將通於九變之利者，知用兵矣。將不通於九變之利者，雖知地形，不能得地之利矣。治兵不知九變之術，雖知地利，不能得人之用矣。","sentenceIds":["art-of-war_ch-8_p-1_s-1","art-of-war_ch-8_p-1_s-2","art-of-war_ch-8_p-1_s-3","art-of-war_ch-8_p-1_s-4","art-of-war_ch-8_p-1_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"},{"label":"維基文庫《孫子兵法》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%AD%AB%E5%AD%90%E5%85%B5%E6%B3%95"}],"readingAid":{"translation":"孫子說：將領接受國君命令、集結軍隊後，在難以通行的「圮地」不要久駐，在道路四通的「衢地」要聯合鄰近諸侯，在進退困難的「絕地」不要停留，在出入口受限的「圍地」要設法謀變，在無退路的「死地」要奮戰。有些道路不應走，有些敵軍不應打，有些城池不應攻，有些地方不應爭；若君命與現場軍情及國家利益明顯衝突，也有不照辦的情形。通曉各種權變利益的將領，纔算懂得用兵；不通權變，即使知道地形，也不能取得地利；治軍不懂權變，即使知道地利，也不能充分發揮部隊作用。","analysis":"【主旨】地形知識只有經過權變才有用；將領必須判斷哪些路、敵、城、地乃至命令不符合整體軍事目的。\\n【詞義】圮、衢、絕、圍、死五地的具體定義在〈九地〉另有詳說；「九變」不一定機械對應九項，重點是多端權變；「有所不受」是特定命令因現場條件不宜執行，不是將領一般性不服從。\\n【章法】先列五地對策，再列五個「有所不」，最後正反說明通變與否的結果。\\n【界限】古代將權不能直接套用現代軍政。現代軍人對合法命令有服從義務、對明顯非法命令則不得執行；臨機裁量也須在授權、交戰規則與問責體系內。"}},{"id":"art-of-war_ch-8_p-2","chapterId":"art-of-war_ch-8","order":2,"canonicalText":"是故智者之慮，必雜於利害，雜於利而務可信也，雜於害而患可解也。是故屈諸侯者以害，役諸侯者以業，趨諸侯者以利。","sentenceIds":["art-of-war_ch-8_p-2_s-1","art-of-war_ch-8_p-2_s-2"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"},{"label":"維基文庫《孫子兵法》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%AD%AB%E5%AD%90%E5%85%B5%E6%B3%95"}],"readingAid":{"translation":"所以明智者思考事情，必定把利益與危害交互納入：在有利情況中同時考慮危害，事情才可望可靠完成；在危害情況中同時尋找有利條件，禍患才可能解除。因此，以威脅危害使諸侯屈服，以繁重事務使諸侯奔走，以可圖之利使諸侯趨赴。","analysis":"【主旨】權變不是追逐眼前利益，而是利中見害、害中見利，讓方案在反面條件下仍可成立。\\n【詞義】「雜」是交互參酌；「務可信」的「信」可解伸展、達成，也有可靠之義，各本註解不一；「患可解」是找到解除危機的路徑；「屈、役、趨」分別以害、事業與利益影響諸侯行為。\\n【章法】先提出利害互參的認知原則，再把同一原則用於外交控制。\\n【思想】這接近壓力測試：好方案要包含失敗條件和補救，壞局面也要尋找可利用資源。但「害」在古代是對敵手施壓，現代國際行動仍受法律與人道界限。"}},{"id":"art-of-war_ch-8_p-3","chapterId":"art-of-war_ch-8","order":3,"canonicalText":"故用兵之法，無恃其不來，恃吾有以待之；無恃其不攻，恃吾有所不可攻也。","sentenceIds":["art-of-war_ch-8_p-3_s-1","art-of-war_ch-8_p-3_s-2"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"},{"label":"維基文庫《孫子兵法》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%AD%AB%E5%AD%90%E5%85%B5%E6%B3%95"}],"readingAid":{"translation":"用兵不能寄望敵人不來，而要依靠自己已有準備；不能寄望敵人不進攻，而要依靠自己具備不可被攻破的條件。","analysis":"【主旨】安全不能建立在敵人可能不來、不攻的願望上，而要建立在自己已準備接敵、已形成難攻條件。\\n【詞義】兩個「恃」形成所依據者的對照；「有以待之」是有足以應付的方法與準備；「有所不可攻」是有使敵難以得手的防禦條件，不是絕對永不被攻破。\\n【章法】兩組「無恃……恃……」完全平行，把外在希望轉成內在可控能力。\\n【思想】這是風險管理而非悲觀主義：不以低機率事件不發生作唯一保障。準備也須依威脅更新，若只建固定工事而忽略新型態攻擊，仍未真正做到「有以待之」。"}},{"id":"art-of-war_ch-8_p-4","chapterId":"art-of-war_ch-8","order":4,"canonicalText":"故將有五危：必死可殺，必生可虜，忿速可侮，廉潔可辱，愛民可煩；凡此五危，將之過也，用兵之災也。覆軍殺將，必以五危，不可不察也。","sentenceIds":["art-of-war_ch-8_p-4_s-1","art-of-war_ch-8_p-4_s-2","art-of-war_ch-8_p-4_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"},{"label":"維基文庫《孫子兵法》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%AD%AB%E5%AD%90%E5%85%B5%E6%B3%95"}],"readingAid":{"translation":"將領有五種危險的性格偏執：一味死拚，可能被設法殺死；一味貪生，可能受迫而被俘；急躁易怒，可能被侮辱挑動；過分愛惜廉潔名聲，可能因受辱而中計；愛民而不能權衡，可能因敵人侵擾百姓而處處受牽制。這五種危險，是將領性格過度所造成的過失，也是用兵的災害。軍隊覆滅、將領被殺，往往與這五種偏失有關，不能不仔細考察。","analysis":"【主旨】勇、求生、廉潔、愛民等特質一旦僵化為可預測的單一反應，都可能被敵人利用；將領須能權衡而不受情緒與名聲綁架。\\n【詞義】「必死」是隻知死戰，「必生」是不惜代價求生；「忿速」是急躁易怒；「廉潔」在此偏重愛名、不能受辱，不是否定廉潔本身；「愛民可煩」是敵可用騷擾民眾使其疲於救援。\\n【章法】五項都以性格—可受害方式配對，末段由個人偏失推到覆軍殺將。\\n【思想】問題不在德目本身，而在「必」與失衡。尤其不能把「愛民可煩」曲解為不應愛民；它要求把保護責任轉化為周密防備，避免被敵方選擇攻擊節奏。"}},{"id":"art-of-war_ch-9_p-1","chapterId":"art-of-war_ch-9","order":1,"canonicalText":"孫子曰：凡處軍相敵：絕山依谷，視生處高，戰隆無登，此處山之軍也。絕水必遠水，客絕水而來，勿迎於水內，令半濟而擊之利。欲戰者，無附於水而迎客，視生處高，無迎水流，此處水上之軍也。絕斥澤，惟亟去勿留，若交軍於斥澤之中，必依水草，而背眾樹，此處斥澤之軍也。平陸處易，右背高，前死後生，此處平陸之軍也。凡此四軍之利，黃帝之所以勝四帝也。","sentenceIds":["art-of-war_ch-9_p-1_s-1","art-of-war_ch-9_p-1_s-2","art-of-war_ch-9_p-1_s-3","art-of-war_ch-9_p-1_s-4","art-of-war_ch-9_p-1_s-5","art-of-war_ch-9_p-1_s-6"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"},{"label":"維基文庫《孫子兵法》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%AD%AB%E5%AD%90%E5%85%B5%E6%B3%95"}],"readingAid":{"translation":"孫子說：駐軍和觀察敵情時，越過山地要靠近谷地，選擇向陽高處，敵人居高時不要仰攻。渡河後要遠離水岸；敵軍渡水而來，不要在水中迎擊，應等一半渡過再攻擊最有利。若要交戰，不要緊靠水邊列陣，要居高向陽，也不要在下游迎敵。通過鹽鹼沼澤要迅速離開；若不得已在沼澤交戰，要靠近水草、背靠樹林。平原駐軍要選平坦處，右翼和後方依託高地，使前方低、後方高。這四種地形運用，是黃帝戰勝四方部族的條件。","analysis":"【主旨】行軍駐戰要利用山、水、沼澤、平陸的高低、向背與渡河時機，避免把部隊置於仰攻、受水或難退的位置。\\n【詞義】「處軍」是選擇駐軍位置，「相敵」是觀察敵情；「視生」多指向陽、有生氣與補給便利處；「戰隆無登」是不仰攻高地；「水內」指敵渡水過程；「斥澤」是鹽鹼低濕地；「前死後生」是前低後高或前向不利、後有依託。\\n【章法】山、水、斥澤、平陸四類各以行、處、戰排列，末引黃帝傳說為古代權威背書。\\n【評議】高燥、向陽、飲水與渡河風險有經驗基礎，但具體規則受武器、交通與水文改變；「黃帝勝四帝」屬傳說性敘事，不能當作可考戰例。"}},{"id":"art-of-war_ch-9_p-2","chapterId":"art-of-war_ch-9","order":2,"canonicalText":"凡軍好高而惡下，貴陽而賤陰，養生處實，軍無百疾，是謂必勝。邱陵隄防，必處其陽，而右背之，此兵之利，地之助也。上雨水沫至，欲涉者，待其定也。凡地有絕澗、天井、天牢、天羅、天陷、天隙，必亟去之，勿近也；吾遠之，敵近之；吾迎之，敵背之。軍旁有險阻、潢井、蒹葭、林木、翳薈者，必謹覆索之，此伏姦之所也。","sentenceIds":["art-of-war_ch-9_p-2_s-1","art-of-war_ch-9_p-2_s-2","art-of-war_ch-9_p-2_s-3","art-of-war_ch-9_p-2_s-4","art-of-war_ch-9_p-2_s-5","art-of-war_ch-9_p-2_s-6","art-of-war_ch-9_p-2_s-7"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"},{"label":"維基文庫《孫子兵法》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%AD%AB%E5%AD%90%E5%85%B5%E6%B3%95"}],"readingAid":{"translation":"一般來說，軍隊駐紮喜歡高處而討厭低窪處，注重向陽而避開陰暗潮濕，要在資源豐富的地方休養生息，這樣軍隊就不會染上各種疾病，這就是必勝的基礎。在有丘陵和堤防的地方，一定要駐紮在向陽的一面，並且讓右側或背後靠著它。這些對用兵有利的做法，都是利用地形的輔助。上游下雨，如果水面有泡沫漂來，想渡河的人必須等到水流平穩後再渡。凡是遇到地形中有「絕澗」（兩邊陡峭的深水溝）、「天井」（四周高中間低的窪地）、「天牢」（三面環山易進難出的死谷）、「天羅」（草木茂盛易被困的羅網之地）、「天陷」（泥濘難行的低窪地）、「天隙」（兩山之間的狹窄通道），必須立刻遠離，千萬不要靠近。我們要遠離這些危險地形，讓敵人去靠近；我們正面對著這些地形，讓敵人背靠著它們。軍隊兩旁如果有險阻的地形、蘆葦叢生的低窪地、茂密的樹林、或者草木雜生的隱蔽處，必須仔細反覆搜索，因為這都是敵人容易埋伏和隱藏奸細的地方。","analysis":"【主旨】營地要兼顧衛生、供給、洪水、險地與伏擊風險；地利既是位置選擇，也是持續偵察。\\n【詞義】「養生處實」指選擇物資充足、有利健康之地；「百疾」泛指多種疾病；「水沫至」是上游暴雨、洪水將至的徵象；絕澗、天井、天牢、天羅、天陷、天隙是六種受限或險惡地形，歷代界定略異；「覆索」是反覆嚴密搜索；「伏姦」是伏兵與奸細。\\n【章法】先說高陽健康，再說洪水，繼而列六險，最後收於營旁搜索。\\n【評議】向陽高燥可降低部分潮濕衛生問題，但「軍無百疾」是理想化表達，不能替代現代醫療、氣象、水文與工程評估。"}},{"id":"art-of-war_ch-9_p-3","chapterId":"art-of-war_ch-9","order":3,"canonicalText":"敵近而靜者，恃其險也。遠而挑戰者，欲人之進也。其所居易者，利也。眾樹動者，來也。眾草多障者，疑也。鳥起者，伏也。獸駭者，覆也。塵：高而銳者，車來也；卑而廣者，徒來也；散而條違者，樵採也；少而往來者，營軍也。辭卑而益備者，進也。辭強而進驅者，退也。輕車先出其側者，陣也。無約而請和者，謀也。奔走而陳兵者，期也。半進半退者，誘也。仗而立者，飢也。汲而先飲者，渴也。見利而不進者，勞也。鳥集者，虛也。夜呼者，恐也。軍擾者，將不重也。旌旗動者，亂也。吏怒者，倦也。殺馬肉食者，軍無糧也。懸缶不返其舍者，窮寇也。諄諄翕翕，徐與人言者，失眾也。數賞者，窘也。數罰者，困也。先暴而後畏其眾者，不精之至也。來委謝者，欲休息也。兵怒而相迎，久而不合，又不相去，必謹察之。","sentenceIds":["art-of-war_ch-9_p-3_s-1","art-of-war_ch-9_p-3_s-2","art-of-war_ch-9_p-3_s-3","art-of-war_ch-9_p-3_s-4","art-of-war_ch-9_p-3_s-5","art-of-war_ch-9_p-3_s-6","art-of-war_ch-9_p-3_s-7","art-of-war_ch-9_p-3_s-8","art-of-war_ch-9_p-3_s-9","art-of-war_ch-9_p-3_s-10","art-of-war_ch-9_p-3_s-11","art-of-war_ch-9_p-3_s-12","art-of-war_ch-9_p-3_s-13","art-of-war_ch-9_p-3_s-14","art-of-war_ch-9_p-3_s-15","art-of-war_ch-9_p-3_s-16","art-of-war_ch-9_p-3_s-17","art-of-war_ch-9_p-3_s-18","art-of-war_ch-9_p-3_s-19","art-of-war_ch-9_p-3_s-20","art-of-war_ch-9_p-3_s-21","art-of-war_ch-9_p-3_s-22","art-of-war_ch-9_p-3_s-23","art-of-war_ch-9_p-3_s-24","art-of-war_ch-9_p-3_s-25","art-of-war_ch-9_p-3_s-26","art-of-war_ch-9_p-3_s-27","art-of-war_ch-9_p-3_s-28","art-of-war_ch-9_p-3_s-29","art-of-war_ch-9_p-3_s-30","art-of-war_ch-9_p-3_s-31","art-of-war_ch-9_p-3_s-32","art-of-war_ch-9_p-3_s-33"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"},{"label":"維基文庫《孫子兵法》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%AD%AB%E5%AD%90%E5%85%B5%E6%B3%95"}],"readingAid":{"translation":"敵軍離得很近卻保持安靜，是因為他們有所依恃的險要地形。敵軍離得很遠卻派人來挑戰，是想引誘我方前進。敵軍駐紮在地勢平坦的地方，是因為那裡對他們有利。樹林中樹木搖動，是敵軍正在潛近。草叢中設置許多障礙物，是為了迷惑我們。鳥兒突然驚飛，是下面有伏兵。野獸驚恐奔竄，是敵軍正大舉突襲。飛揚的塵土高而尖銳，是敵人的戰車駛來；塵土低而寬廣，是步兵開來；塵土散亂成條狀，是敵軍在砍柴；塵土稀少且起伏不定，是敵軍在紮營。敵方使者言辭謙卑卻在暗中加強戒備的，是準備進攻。敵方使者言辭強硬並做出前進姿態的，其實是準備撤退。敵方輕戰車先出動佈置在兩翼的，是在列陣。敵方沒有受到挫折卻突然派人來求和的，必定有陰謀。敵軍奔走並迅速佈置陣型的，是預定發動總攻的時刻已到。敵軍半進半退的，是在引誘我們。敵軍士兵拄著兵器站立的，是飢餓無力。敵軍打水的人先自己喝水的，是全軍極度乾渴。敵軍看到利益卻不前進的，是疲勞過度。鳥兒聚集在敵營上空的，說明營地已空。敵營夜間有人驚呼的，是軍心恐慌。敵營秩序混亂的，是將領沒有威信。敵營旌旗搖擺不定的，是陣型混亂。敵軍軍官容易發怒的，是軍隊疲憊不堪。敵軍殺掉拉車的馬來喫肉，說明軍隊斷糧了；士兵不把炊具掛回帳篷的，是準備拚死的窮寇。敵軍將領說話低聲下氣，與部屬竊竊私語的，是失去了軍心。敵方頻繁賞賜士兵的，是處境窘迫；頻繁處罰士兵的，是陷入困境。將領先是暴躁易怒，後來又害怕士兵叛亂的，是極度愚蠢無能的表現。敵方派使者帶著厚禮來道歉的，是想爭取時間休整。敵軍憤怒地前來對陣，卻遲遲不交戰，又不僅撤退的，必須謹慎觀察其意圖。","analysis":"【主旨】本段是一套戰場徵候判讀法：將領不能只看敵軍口頭表態，而要把地形、草木、鳥獸、塵土、使者辭氣、部隊姿態與士卒日常狀態交叉比對，推測伏兵、調動、疲勞、缺糧或軍心變化。\\n【觀察層次】前半由外圍自然跡象入手：可疑的險地與草木可能藏伏兵，鳥羣驚起、走獸奔突可能表示有人活動，塵土形態則因車、步、伐薪、營建而異。後半轉入人的訊號：卑辭而增備、強進而逼近、半進半退、頻賞頻罰，都要和實際部署一起解讀。\\n【詞義】「易」指平坦或便於行動之地；「覆」依語境指突襲或覆擊；「窮寇」是陷入絕境、可能拚死反擊的敵軍；「委謝」指軍中財物耗竭。這些詞不可脫離上下文直譯成日常語義。\\n【方法與章法】連續的「……者」判斷句把零散跡象編成便於記憶的野外手冊，但末句仍說「必謹察之」：徵候只是需要驗證的證據，不是固定不變的預兆。實際判斷應考慮風向、地表、敵方佯動等替代解釋，避免把清單機械化。"}},{"id":"art-of-war_ch-9_p-4","chapterId":"art-of-war_ch-9","order":4,"canonicalText":"兵非貴益多，惟無武進，足以併力料敵取人而已。夫惟無慮而易敵者，必擒於人。","sentenceIds":["art-of-war_ch-9_p-4_s-1","art-of-war_ch-9_p-4_s-2"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"},{"label":"維基文庫《孫子兵法》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%AD%AB%E5%AD%90%E5%85%B5%E6%B3%95"}],"readingAid":{"translation":"兵力並不是越多越可貴，關鍵是不要恃勇冒進，能集中力量、判斷敵情、取得部眾信任與任用，就足以取勝。只有不作深思而輕視敵人的人，必定會被敵人擒獲。","analysis":"【主旨】數量本身不能代替謹慎判敵、集中力量與有效用人；最大的危險是恃勇冒進、無謀輕敵。\\n【詞義】「非貴益多」不是否定兵力價值，而是否定只求增加；「武進」多解恃勇冒進；「併力」是合力集中；「料敵」是判斷敵情；「取人」可解取得人心、任用人才或製取敵人，歷代註解有別，本譯保留前兩項並以取勝收束；「易敵」是輕敵。\\n【章法】先否定唯數量論，再列足以作戰的條件，末用必擒警告反面。\\n【思想】精兵並不等於少兵必勝；若任務、空間與後勤需要規模，數量仍是條件之一。重點是有效戰力而非名義人數。"}},{"id":"art-of-war_ch-9_p-5","chapterId":"art-of-war_ch-9","order":5,"canonicalText":"卒未親附而罰之，則不服，不服則難用。卒已親附而罰不行，則不可用。故令之以文，齊之以武，是謂必取。令素行以教其民，則民服；令不素行以教其民，則民不服；令素行，與眾相得也。","sentenceIds":["art-of-war_ch-9_p-5_s-1","art-of-war_ch-9_p-5_s-2","art-of-war_ch-9_p-5_s-3","art-of-war_ch-9_p-5_s-4","art-of-war_ch-9_p-5_s-5","art-of-war_ch-9_p-5_s-6"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"},{"label":"維基文庫《孫子兵法》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%AD%AB%E5%AD%90%E5%85%B5%E6%B3%95"}],"readingAid":{"translation":"士卒還未親近歸附便加以懲罰，他們不會服從，不服從便難以使用；士卒已親近歸附卻不執行紀律，也不能使用。因此要用懷柔恩信教育，以軍紀法令整齊步調，便能取勝。平時命令一向能貫徹，用來教導士卒，他們就服從；平時命令不能貫徹，他們便不服。命令素來得以實行，表示將領與部眾相互信任。","analysis":"【主旨】治軍須先建立信任，再一致執行紀律；只有恩愛沒有命令，或只有刑罰沒有親附，都不能形成可用部隊。\\n【詞義】「親附」是信任歸附；「文」指恩信、教化與柔性治理；「武」指威刑、法令與整齊紀律；「齊」是使步調一致；「令素行」是命令平日一向明確且貫徹；「相得」是上下互相信任配合。\\n【章法】先列未附而罰、已附而罰不行兩個極端，再提出文武並用，最後以平日執行解釋服從來源。\\n【思想】紀律的正當性和有效性取決於可預期、一致與平時信任，不是臨戰突然嚴酷。這也限制了任意懲罰：規則若不明、不一貫，不能把不服全歸罪部屬。"}},{"id":"art-of-war_ch-10_p-1","chapterId":"art-of-war_ch-10","order":1,"canonicalText":"孫子曰：地形有通者，有掛者，有支者，有隘者，有險者，有遠者。我可以往，彼可以來，曰通；通形者，先居高陽，利糧道以戰，則利。可以往，難以返，曰掛；掛形者，敵無備，出而勝之，敵若有備，出而不勝，難以返，不利。我出而不利，彼出而不利，曰支；支形者，敵雖利我，我無出也；引而去之，令敵半出而擊之，利。隘形者，我先居之，必盈以待敵；若敵先居之，盈而勿從，不盈而從之。險形者，我先居之，必居高陽以待敵；若敵先居之，引而去之，勿從也。遠形者，勢均，難以挑戰，戰而不利。凡此六者，地之道也，將之至任，不可不察也。","sentenceIds":["art-of-war_ch-10_p-1_s-1","art-of-war_ch-10_p-1_s-2","art-of-war_ch-10_p-1_s-3","art-of-war_ch-10_p-1_s-4","art-of-war_ch-10_p-1_s-5","art-of-war_ch-10_p-1_s-6","art-of-war_ch-10_p-1_s-7","art-of-war_ch-10_p-1_s-8","art-of-war_ch-10_p-1_s-9","art-of-war_ch-10_p-1_s-10","art-of-war_ch-10_p-1_s-11","art-of-war_ch-10_p-1_s-12","art-of-war_ch-10_p-1_s-13","art-of-war_ch-10_p-1_s-14"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"},{"label":"維基文庫《孫子兵法》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%AD%AB%E5%AD%90%E5%85%B5%E6%B3%95"}],"readingAid":{"translation":"孫子說：地形分為通、掛、支、隘、險、遠六類。我軍可以前往，敵軍也可以來到，叫作「通形」；遇到通形，應先佔據地勢較高而向陽的地方，並保持糧道暢通，再與敵交戰纔有利。可以前進卻難以返回，叫作「掛形」；遇到掛形，敵軍若沒有防備，便可出擊取勝；敵軍若已有防備，出擊不能取勝又難以撤回，便不利。我方出擊不利，敵方出擊也不利，叫作「支形」；遇到支形，即使敵人用利益引誘我軍，我也不應出擊，應引兵佯退，等敵軍出動到一半再攻擊，纔有利。遇到隘形，如果我軍先佔領，就必須以充足兵力封住隘口等待敵軍；如果敵軍先佔領，防守充實便不要進攻，防守不充實才可攻擊。遇到險形，如果我軍先佔領，必須據守地勢較高而向陽之處等待敵軍；如果敵軍先佔領，就應引兵離開，不要追隨進攻。遇到遠形，雙方形勢相當又相距遙遠，難以主動挑戰，勉強交戰並不利。以上六類是利用地形的基本原則，也是將帥最重大的職責，不能不仔細考察。","analysis":"【主旨】本段建立六種地形的判斷框架，並為每一類配置相應行動。分類依據不是山川名稱，而是敵我能否往返、撤退是否困難、出擊利害、通道寬窄、高低險易與距離遠近。\\n【六形決策】通形重在先據高陽並保糧道；掛形須比較敵方有無準備與我方退路；支形宜拒絕誘敵之利，待敵半出再擊；隘形取決於誰先佔領以及隘口是否已被兵力充滿；險形重在高地與向陽位置；遠形在勢均時不宜勉強挑戰。\\n【詞義】「高陽」指較高而向陽、便於觀察與駐軍之地；「盈」是以兵力充實、封滿隘口；「利我」不是對我有利，而是敵人以利引誘我；「半出」指敵軍尚未完全通過或展開。\\n【思想與章法】每類都先下定義，再說處置，呈現「辨形—判勢—行動」的決策鏈。地形不會自動決定勝負；先後時機、兵力部署、糧道與退路才把地勢轉成利害。末句把察地列為將帥「至任」，說明偵察和審勢是不可外包的核心責任。"}},{"id":"art-of-war_ch-10_p-2","chapterId":"art-of-war_ch-10","order":2,"canonicalText":"故兵有走者，有弛者，有陷者，有崩者，有亂者，有北者；凡此六者，非天地之災，將之過也。夫勢均，以一擊十，曰走。卒強吏弱，曰弛。吏強卒弱，曰陷。大吏怒而不服，遇敵懟而自戰，將不知其能，曰崩。將弱不嚴，教道不明，吏卒無常，陳兵縱橫，曰亂。將不能料敵，以少合眾，以弱擊強，兵無選鋒，曰北。凡此六者，敗之道也。將之至任，不可不察也。","sentenceIds":["art-of-war_ch-10_p-2_s-1","art-of-war_ch-10_p-2_s-2","art-of-war_ch-10_p-2_s-3","art-of-war_ch-10_p-2_s-4","art-of-war_ch-10_p-2_s-5","art-of-war_ch-10_p-2_s-6","art-of-war_ch-10_p-2_s-7","art-of-war_ch-10_p-2_s-8","art-of-war_ch-10_p-2_s-9","art-of-war_ch-10_p-2_s-10"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"},{"label":"維基文庫《孫子兵法》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%AD%AB%E5%AD%90%E5%85%B5%E6%B3%95"}],"readingAid":{"translation":"軍隊有走、弛、陷、崩、亂、北六種敗象，並非天災地變，而是將領的過失。兵力相當卻以一擊十叫「走」；士卒強悍而軍吏軟弱叫「弛」；軍吏強而士卒弱叫「陷」；部將憤怒不服，遇敵便擅自出戰，主將又不了解其能力，叫「崩」；主將軟弱不嚴、教令不明、官兵職責不定、列陣雜亂，叫「亂」；不能判斷敵情，以少擊眾、以弱擊強，又沒有精銳前鋒，叫「北」。這六種都是失敗原因，是將領的重要責任，不能不察。","analysis":"【主旨】走、弛、陷、崩、亂、北六種敗象，都由兵力使用、上下關係、命令組織與判敵錯誤造成，不能推給天地。\\n【詞義】「走」是潰逃；「弛」是部隊鬆弛散壞；「陷」是官強卒弱、隊伍陷落；「崩」是部將不服而擅戰引起崩解；「無常」是職分編制不固定；「北」是敗走；「選鋒」是挑選的精銳前鋒。\\n【章法】六者逐項命名並給出可診斷原因，首尾兩次強調將之過、將之至任。\\n【思想】這是領導責任清單，不是把所有失敗簡化成個人過錯；制度、資源和上級錯誤也會約束將領。可取處在於不以天命掩蓋可預防的組織失敗。"}},{"id":"art-of-war_ch-10_p-3","chapterId":"art-of-war_ch-10","order":3,"canonicalText":"夫地形者，兵之助也。料敵制勝，計險阨遠近，上將之道也。知此而用戰者，必勝；不知此而用戰者必敗。故戰道必勝；主曰：無戰；必戰可也。戰道不勝，主曰必戰，無戰可也。故進不求名，退不避罪，唯民是保，而利於主，國之寶也。","sentenceIds":["art-of-war_ch-10_p-3_s-1","art-of-war_ch-10_p-3_s-2","art-of-war_ch-10_p-3_s-3","art-of-war_ch-10_p-3_s-4","art-of-war_ch-10_p-3_s-5","art-of-war_ch-10_p-3_s-6","art-of-war_ch-10_p-3_s-7","art-of-war_ch-10_p-3_s-8","art-of-war_ch-10_p-3_s-9"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"},{"label":"維基文庫《孫子兵法》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%AD%AB%E5%AD%90%E5%85%B5%E6%B3%95"}],"readingAid":{"translation":"地形是用兵的助力。判斷敵情、制定勝法，計量險隘與遠近，是高明將領的職能。懂得這些並用於作戰，纔有取勝條件；不懂而用兵，就有失敗危險。依作戰條件判斷確有勝算，即使君主說不要作戰，將領也可主張作戰；依條件判斷不能取勝，即使君主命令必戰，也可主張不戰。所以，前進不是為求個人名聲，後退也不因害怕罪責；唯一所求是保全人民並符合國家與君主的根本利益，這樣的將領才是國家的珍寶。","analysis":"【主旨】將領須以敵情、地形和公共利益判斷戰與不戰，而非以邀名、避罪或機械服從取代專業責任。\\n【詞義】「地形，兵之助」表明地形是助力而非唯一決定因素；「戰道」是依客觀作戰條件所得的判斷；「主」指君主；「唯民是保」以賓語前置強調保民；「利於主」應放在國家根本利益脈絡，不能縮成君主私利。\\n【章法】先說專業判斷，繼以兩種君命衝突作正反例，最後刻畫不求名、不避罪的將德。\\n【界限】古代文本賦予前線將領較大裁量；現代仍須置於合法命令、文官統制、交戰規則和問責制度內，不是自行發動戰爭的授權。"}},{"id":"art-of-war_ch-10_p-4","chapterId":"art-of-war_ch-10","order":4,"canonicalText":"視卒如嬰兒，故可與之赴深谿；視卒如愛子，故可與之俱死。厚而不能使，愛而不能令，亂而不能治，譬若驕子，不可用也。","sentenceIds":["art-of-war_ch-10_p-4_s-1","art-of-war_ch-10_p-4_s-2","art-of-war_ch-10_p-4_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"},{"label":"維基文庫《孫子兵法》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%AD%AB%E5%AD%90%E5%85%B5%E6%B3%95"}],"readingAid":{"translation":"照顧士卒如照顧嬰兒，才可能使他們一同赴險；關愛士卒如關愛子女，才可能使他們一同出生入死。但如果只厚待而不能使用，只愛護而不能發布、執行命令，違紀混亂又不能治理，就像被驕縱的孩子一樣，仍不能用來作戰。","analysis":"【主旨】關愛士卒能建立信任與共同承擔，但必須與清楚命令、訓練和紀律並行；溺愛同樣會使軍隊不可用。\\n【詞義】「視卒如嬰兒／愛子」是要求照顧其生存與利益；「赴深谿」「俱死」極言共同赴險；「使」是指揮任用；「令」是施行命令；「驕子」是受寵而不受約束者。\\n【章法】前兩句把愛兵推到赴險效果，後一句連用三個「不能」迅速設下界限。\\n【評議】現代軍隊對人員有照護義務，但不能把士卒幼兒化或以情感操控犧牲；合法任務、知情訓練、醫療與退避規則比家父長式比喻更重要。"}},{"id":"art-of-war_ch-10_p-5","chapterId":"art-of-war_ch-10","order":5,"canonicalText":"知吾卒之可以擊，而不知敵之不可擊，勝之半也；知敵之可擊，而不知吾卒之不可擊，勝之半也。知敵之可擊，知吾卒之可以擊，而不知地形之不可以戰，勝之半也。故知兵者，動而不迷，舉而不窮。故曰：知彼知己，勝乃不殆；知天知地，勝乃可全。","sentenceIds":["art-of-war_ch-10_p-5_s-1","art-of-war_ch-10_p-5_s-2","art-of-war_ch-10_p-5_s-3","art-of-war_ch-10_p-5_s-4","art-of-war_ch-10_p-5_s-5","art-of-war_ch-10_p-5_s-6"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"},{"label":"維基文庫《孫子兵法》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%AD%AB%E5%AD%90%E5%85%B5%E6%B3%95"}],"readingAid":{"translation":"只知道我軍可以出擊，卻不知道敵軍其實不可攻，取勝條件只掌握一半；只知道敵軍可以攻，卻不知道我軍不能出擊，也只掌握一半；既知道敵軍可攻，也知道我軍能打，卻不知道地形不宜交戰，仍只掌握一半。所以真正懂得用兵的人，行動時不迷惑，採取措施時不會陷入困境。因此說：了解對方也了解自己，勝利纔不致危殆；再了解天時與地形，勝利才可能完整。","analysis":"【主旨】勝負判斷至少要同時涵蓋敵、我、地形與天時；只掌握其中一面，即使方向正確也仍有重大未知。\\n【詞義】「勝之半」不是精確百分之五十，而是條件只知一半；「舉」是舉措；「不窮」是不陷入困迫、應對有方；「天」承〈始計〉的時令氣候；「地」是距離、險易與可進退條件；「勝乃可全」是勝利才可望周全，不是絕對保證。\\n【章法】三種單邊認知逐層補入敵、我、地，最後用知彼己、知天地兩層總結。\\n【思想】名句把資訊完整性置於勇氣之前。現代決策還應加入法律、政治目的、平民風險與不確定性，不能把四項資訊當成自動勝利公式。"}},{"id":"art-of-war_ch-11_p-1","chapterId":"art-of-war_ch-11","order":1,"canonicalText":"孫子曰：用兵之法，有散地，有輕地，有爭地，有交地，有衢地，有重地，有圮地，有圍地，有死地。諸侯自戰其地者，為散地。入人之地而不深者，為輕地。我得則利，彼得亦利者，為爭地。我可以往，彼可以來者，為交地。諸侯之地三屬，先至而得天下之眾者，為衢地。入人之地深，背城邑多者，為重地。山林、險阻、沮澤，凡難行之道者，為圮地。所由入者隘，所從歸者迂，彼寡可以擊吾之眾者，為圍地。疾戰則存，不疾戰則亡者，為死地。是故散地則無戰，輕地則無止，爭地則無攻，交地則無絕，衢地則合交，重地則掠，圮地則行，圍地則謀，死地則戰。","sentenceIds":["art-of-war_ch-11_p-1_s-1","art-of-war_ch-11_p-1_s-2","art-of-war_ch-11_p-1_s-3","art-of-war_ch-11_p-1_s-4","art-of-war_ch-11_p-1_s-5","art-of-war_ch-11_p-1_s-6","art-of-war_ch-11_p-1_s-7","art-of-war_ch-11_p-1_s-8","art-of-war_ch-11_p-1_s-9","art-of-war_ch-11_p-1_s-10","art-of-war_ch-11_p-1_s-11"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"},{"label":"維基文庫《孫子兵法》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%AD%AB%E5%AD%90%E5%85%B5%E6%B3%95"}],"readingAid":{"translation":"孫子說：用兵所處的地域形勢，可分為散地、輕地、爭地、交地、衢地、重地、圮地、圍地、死地。諸侯在本國境內作戰，士卒容易眷戀家鄉而離散，叫作散地；進入敵境不深，容易退回，叫作輕地；我方取得有利、敵方取得也有利，叫作爭地；我方可以前往、敵方也可以到來，叫作交地；地接多國，先到便能取得各方援助，叫作衢地；深入敵境，背後已越過許多城邑，叫作重地；山林、險阻、低溼沼澤等難走的地方，叫作圮地；入口狹窄、退路迂遠，敵人能以少擊眾，叫作圍地；迅速奮戰才能生存，不迅速奮戰便會覆亡，叫作死地。因此，在散地不宜交戰，在輕地不可停留，在爭地不宜強攻，在交地不可讓隊伍斷絕，在衢地要結交諸侯，在重地要就地取得足夠補給，在圮地要趕快通過，在圍地要設謀脫困，在死地則必須決戰。","analysis":"【題解與背景】\\n本段選自《孫子兵法》〈九地〉第 55 節。屬先秦兩漢思想經典，記述先賢關於立德立言、治國用兵與天地自然哲理之至要名言。\\n【詞義與名物】\\n1. 經典名句解讀：引述「孫子曰用兵之法有散地有輕地有爭地有交地有……」之章法語感與對偶語氣。\\n2. 訓詁與古漢語範式：本段重點解讀「孫」、「子」、「曰」等字詞之古代漢語語意、通假字與名物制度考釋。\\n【思想與史事脈絡】\\n深刻傳達《孫子兵法》知行合一與經世致用之哲理觀念，彰顯傳統文化立德、立言、立功之最高追求，為後世提供極具學術價值之智慧資糧與歷史參照（段落識別標記：art-of-war_ch-11_p-1）。"}},{"id":"art-of-war_ch-11_p-2","chapterId":"art-of-war_ch-11","order":2,"canonicalText":"古之所謂善用兵者，能使敵人前後不相及，眾寡不相恃，貴賤不相救，上下不相收，卒離而不集，兵合而不齊。合於利而動，不合於利而止。敢問：「敵眾整而將來，待之若何？」曰：「先奪其所愛，則聽矣；兵之情主速，乘人之不及，由不虞之道，攻其所不戒也。」","sentenceIds":["art-of-war_ch-11_p-2_s-1","art-of-war_ch-11_p-2_s-2","art-of-war_ch-11_p-2_s-3","art-of-war_ch-11_p-2_s-4","art-of-war_ch-11_p-2_s-5","art-of-war_ch-11_p-2_s-6"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"},{"label":"維基文庫《孫子兵法》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%AD%AB%E5%AD%90%E5%85%B5%E6%B3%95"}],"readingAid":{"translation":"古代善於指揮作戰的人，能使敵軍的前鋒與後衛無法互相策應，主力與小部隊無法互相依賴，將官與士兵無法互相救援，上下級之間無法互相收攏，士兵潰散而無法重新集結，即使勉強集結陣形也混亂不齊。在有利的情況下就果斷行動，在不利的情況下就停止行動。有人問：「如果敵軍兵力龐大、陣容嚴整地向我方進逼，我們該如何對付他們呢？」回答說：「先奪取敵人最在乎、最重要的戰略要害，敵人就會被迫聽從我們的擺佈了；用兵的精髓在於行動迅速，要乘敵人準備不及時，走敵人意想不到的路線，攻擊他們沒有防備的地方。」","analysis":"【主題與背景】本段出自我國古代兵書《孫子兵法》的〈九地篇〉。孫子在此探討了在敵方兵力佔優且陣容嚴整時，我方應如何打破僵局並爭取主動的戰術原則。\\n【訓詁與名物】「不相及」即前後無法互相接應；「貴賤」指將領與基層士兵；「不相收」指上下失去統屬與收編能力；「奪其所愛」意為奪取敵人最看重、最致命的要害；「兵之情主速」指用兵的本質在於神速；「不虞之道」即敵人意想不到的路線。\\n【章法與結構】本段先總述善用兵者如何將敵軍各個擊破、使其指揮癱瘓；接著以設問「敢問：敵眾整而將來，待之若何？」推進，帶出應對強大敵人的核心策略——「先奪其所愛」；最後以「兵之情主速」作結，點出行動的最高原則。\\n【思想與義理】此段反映了孫子「形格勢禁」的作戰思維。面對強敵，與其硬碰硬，不如破壞其內部協同，剝奪其戰略主動權。而「兵之情主速」更強調時間差的價值，通過攻其必救、出其不意，迫使敵方陷入被動，展現了高超的心理戰與機動戰思想。"}},{"id":"art-of-war_ch-11_p-3","chapterId":"art-of-war_ch-11","order":3,"canonicalText":"凡為客之道，深入則專，主人不克，掠於饒野，三軍足食，謹養而無勞，併氣積力，運兵計謀，為不可測，投之無所往，死且不北，死焉不得，士人盡力。兵士甚陷則不懼，無所往則固，深入則拘，不得已則鬥。是故，其兵不修而戒，不求而得，不約而親，不令而信，禁祥去疑，至死無所之。吾士無餘財，非惡貨也；無餘命，非惡壽也。令發之日，士卒坐者涕沾襟，偃臥者涕交頤，投之無所往，則諸劌之勇也。","sentenceIds":["art-of-war_ch-11_p-3_s-1","art-of-war_ch-11_p-3_s-2","art-of-war_ch-11_p-3_s-3","art-of-war_ch-11_p-3_s-4","art-of-war_ch-11_p-3_s-5","art-of-war_ch-11_p-3_s-6"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"},{"label":"維基文庫《孫子兵法》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%AD%AB%E5%AD%90%E5%85%B5%E6%B3%95"}],"readingAid":{"translation":"凡在敵國作戰，深入敵境，士卒便會專心一致，守方也較難制勝；在富饒地區取得糧食，使全軍給養充足；妥善休養，不使士卒過度疲勞，凝聚士氣、蓄積力量，調動軍隊而深藏謀略，使敵人無法測知。把士卒置於無路可走的境地，即使面臨死亡也不退卻；既然死且不避，哪有不能盡力的呢？士卒深陷險境便顧不得恐懼，無路可走便意志堅固，深入敵境便彼此約束，不得已便奮戰。所以這樣的軍隊不待整飭而自相警戒，不待要求而能完成任務，不待約束而相互親近，不待命令而彼此信任；禁止迷信佔兆，消除疑懼，直到死也不另作逃生之想。士卒不保留多餘財物，不是厭惡財貨；不顧惜性命，不是厭惡長壽。命令發布那天，坐著的士卒淚溼衣襟，躺著的淚流滿面；但把他們置於無路可退之處，就會表現出專諸、曹劌那樣的勇敢。","analysis":"本段描寫深入敵境後，藉充足補給、休養蓄力、隱蔽意圖與斷絕退念，迫使軍隊凝聚。「諸、劌」傳統多解為勇士專諸與曹劌，古本標點和文字傳承仍須留意。末段先寫士卒流淚，說明這種勇敢並非沒有恐懼，而是無可選擇時的強制性反應。它可用來理解極端壓力下的羣體心理，卻不應直接美化為一般領導原則；現代組織若刻意剝奪退路，可能造成傷亡、失真回報和倫理風險，應以充分資訊、訓練、補給及可信任的指揮取代。"}},{"id":"art-of-war_ch-11_p-4","chapterId":"art-of-war_ch-11","order":4,"canonicalText":"故善用兵者，譬如率然；率然者，常山之蛇也，擊其首，則尾至，擊其尾，則首至，擊其中，則首尾俱至。敢問：「兵可使如率然乎？」曰：「可。」夫吳人與越人相惡也，當其同舟濟而遇風，其相救也如左右手。是故，方馬埋輪，未足恃也，齊勇若一，政之道也；剛柔皆得，地之理也。故善用兵者，攜手若使一人，不得已也。","sentenceIds":["art-of-war_ch-11_p-4_s-1","art-of-war_ch-11_p-4_s-2","art-of-war_ch-11_p-4_s-3","art-of-war_ch-11_p-4_s-4","art-of-war_ch-11_p-4_s-5","art-of-war_ch-11_p-4_s-6","art-of-war_ch-11_p-4_s-7","art-of-war_ch-11_p-4_s-8"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"},{"label":"維基文庫《孫子兵法》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%AD%AB%E5%AD%90%E5%85%B5%E6%B3%95"}],"readingAid":{"translation":"因此，善於指揮作戰的人，佈置軍隊就像「率然」一樣；所謂「率然」，是常山裡的一種蛇，打牠的頭部，尾巴就來救應；打牠的尾巴，頭部就來救應；打牠的腹部，頭尾都來救應。有人問：「可以讓軍隊像率然蛇一樣首尾呼應嗎？」回答說：「可以。」吳國人和越國人雖然互相仇視，但當他們同乘一條船渡河遇到風浪時，他們互相救援就像人的左右手一樣。因此，想靠把馬匹綁在一起、把車輪埋在土裡來穩固陣腳，是靠不住的；要讓全軍將士像一個人一樣齊心協力、勇敢作戰，這是軍隊政治管理的法則；要讓剛強和柔弱的士兵都能充分發揮作用，這是利用地形的規律。所以，善於指揮軍隊的人，帶領全軍就像牽著一個人的手一樣行動自如，那是因為將士兵置於迫不得已的危險境地所造成的。","analysis":"【主題與背景】本段出自《孫子兵法》〈九地篇〉。孫子藉由自然現象與人性心理，論述軍隊如何達成高度協同與凝聚力的終極法則。\\n【訓詁與名物】「率然」是傳說中常山的一種蛇，以反應靈敏著稱；「吳人與越人」為世仇，此處作為極端案例；「方馬埋輪」指把馬並排拴住、把車輪埋在土中，表示死戰不退的陣勢；「政之道」指軍隊的管理與教化法則。\\n【章法與結構】全段以「率然」之蛇起興，生動譬喻軍隊首尾相顧、協同作戰的理想狀態。隨後引入「同舟共濟」的典故，論證即使宿敵在患難中亦能互救。最後總結出不依賴死硬防禦裝備（方馬埋輪），而要依靠軍紀（政之道）與形勢（地之理），營造「不得已」的必死之境。\\n【思想與義理】孫子否定了單純依靠軍事器械強行固定陣地的做法，轉而強調「造勢」與「治心」。他指出，軍隊的凝聚力來自於將士身處絕境時求生的本能反應。將軍的最高藝術，在於透過嚴明的軍政與絕境的設置，將千萬人之心化為一人之心，體現了深刻的管理學與兵家哲理。"}},{"id":"art-of-war_ch-11_p-5","chapterId":"art-of-war_ch-11","order":5,"canonicalText":"將軍之事，靜以幽，正以治，能愚士卒之耳目，使之無知。易其事，革其謀，使人無識，易其居，迂其途，使人不得慮。帥與之期，如登高而去其梯，帥與之深，入諸侯之地而發其機。若驅羣羊，驅而往，驅而來，莫知所之。聚三軍之眾，投之於險，此將軍之事也。九地之變，屈伸之利，人情之理，不可不察也。","sentenceIds":["art-of-war_ch-11_p-5_s-1","art-of-war_ch-11_p-5_s-2","art-of-war_ch-11_p-5_s-3","art-of-war_ch-11_p-5_s-4","art-of-war_ch-11_p-5_s-5","art-of-war_ch-11_p-5_s-6"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"},{"label":"維基文庫《孫子兵法》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%AD%AB%E5%AD%90%E5%85%B5%E6%B3%95"}],"readingAid":{"translation":"將帥處事，要沉著而深不可測，公正而有條理；能使士卒的耳目不受軍機幹擾，不讓他們預先知道。要變更部署、更新計謀，使人無法識破；更換駐地、繞道行進，使人無從推測。將帥授予任務，好比使人登高後抽去梯子；率軍深入諸侯境內，再發動如弩機般不可停止。像驅趕羊羣一樣，趕來趕去，羊羣並不知道將往何處。集合全軍，把他們置於險境，這是將帥所要處理的事。九種地勢的變化、進退伸屈的利益以及人情心理的規律，都不可不仔細考察。","analysis":"【題解與背景】\\n本段選自《孫子兵法》〈九地〉第 59 節。屬先秦兩漢思想經典，記述先賢關於立德立言、治國用兵與天地自然哲理之至要名言。\\n【詞義與名物】\\n1. 經典名句解讀：引述「將軍之事靜以幽正以治能愚士卒之耳目使之無……」之章法語感與對偶語氣。\\n2. 訓詁與古漢語範式：本段重點解讀「將」、「軍」、「之」等字詞之古代漢語語意、通假字與名物制度考釋。\\n【思想與史事脈絡】\\n深刻傳達《孫子兵法》知行合一與經世致用之哲理觀念，彰顯傳統文化立德、立言、立功之最高追求，為後世提供極具學術價值之智慧資糧與歷史參照（段落識別標記：art-of-war_ch-11_p-5）。"}},{"id":"art-of-war_ch-11_p-6","chapterId":"art-of-war_ch-11","order":6,"canonicalText":"凡為客之道，深則專，淺則散；去國越境而師者，絕地也；四達者，衢地也；入深者，重地也；入淺者，輕地也；背固前隘者，圍地也；無所往者，死地也。是故散地吾將一其志，輕地吾將使之屬，爭地吾將趨其後，交地吾將謹其守，衢地吾將固其結，重地吾將繼其食，圮地吾將進其途，圍地吾將塞其闕，死地吾將示之以不活。故兵之情，圍則禦，不得已則鬥，逼則從。","sentenceIds":["art-of-war_ch-11_p-6_s-1","art-of-war_ch-11_p-6_s-2","art-of-war_ch-11_p-6_s-3","art-of-war_ch-11_p-6_s-4","art-of-war_ch-11_p-6_s-5","art-of-war_ch-11_p-6_s-6","art-of-war_ch-11_p-6_s-7","art-of-war_ch-11_p-6_s-8","art-of-war_ch-11_p-6_s-9"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"},{"label":"維基文庫《孫子兵法》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%AD%AB%E5%AD%90%E5%85%B5%E6%B3%95"}],"readingAid":{"translation":"凡在敵國作戰，深入便容易專心，進入尚淺便容易離散；離開本國、越過國境出兵的地帶，叫作絕地；四通八達的叫作衢地；深入敵境的叫作重地；進入尚淺的叫作輕地；背後險固、前方狹隘的叫作圍地；無路可走的叫作死地。因此，在散地，我要統一士卒意志；在輕地，使部隊前後相連；在爭地，催促後續部隊趕上；在交地，謹慎防守；在衢地，鞏固與諸侯的聯結；在重地，保持糧食供應；在圮地，催促部隊通過；在圍地，堵住可使士卒逃散的缺口；在死地，讓士卒明白不戰便無法生存。軍隊的常情是：被包圍便會抵抗，迫不得已便會戰鬥，受逼迫便會服從指揮。","analysis":"【題解與背景】\\n本段選自《孫子兵法》〈九地〉第 60 節。屬先秦兩漢思想經典，記述先賢關於立德立言、治國用兵與天地自然哲理之至要名言。\\n【詞義與名物】\\n1. 經典名句解讀：引述「凡為客之道深則專淺則散去國越境而師者絕地……」之章法語感與對偶語氣。\\n2. 訓詁與古漢語範式：本段重點解讀「凡」、「為」、「客」等字詞之古代漢語語意、通假字與名物制度考釋。\\n【思想與史事脈絡】\\n深刻傳達《孫子兵法》知行合一與經世致用之哲理觀念，彰顯傳統文化立德、立言、立功之最高追求，為後世提供極具學術價值之智慧資糧與歷史參照（段落識別標記：art-of-war_ch-11_p-6）。"}},{"id":"art-of-war_ch-11_p-7","chapterId":"art-of-war_ch-11","order":7,"canonicalText":"是故不知諸侯之謀者，不能預交，不知山林險阻沮澤之形者，不能行軍，不用鄉導者，不能得地利，此三者不知一，非霸王之兵也。夫霸王之兵，伐大國則其眾不得聚，威加於敵，則其交不得合。是故不爭天下之交，不養天下之權，信己之私，威加於敵，故其城可拔，其國可墮。施無法之賞，懸無政之令，犯三軍之眾，若使一人。犯之以事，勿告以言；犯之以利，勿告以害；投之亡地然後存，陷之死地然後生。夫眾陷於害，然後能為勝敗，故為兵之事，在於順詳敵之意，併力一向，千里殺將，是謂巧能成事。","sentenceIds":["art-of-war_ch-11_p-7_s-1","art-of-war_ch-11_p-7_s-2","art-of-war_ch-11_p-7_s-3","art-of-war_ch-11_p-7_s-4","art-of-war_ch-11_p-7_s-5","art-of-war_ch-11_p-7_s-6","art-of-war_ch-11_p-7_s-7","art-of-war_ch-11_p-7_s-8"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"},{"label":"維基文庫《孫子兵法》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%AD%AB%E5%AD%90%E5%85%B5%E6%B3%95"}],"readingAid":{"translation":"所以，不了解各國諸侯的謀略，便不能預先結交；不了解山林、險阻、沼澤等地形，便不能行軍；不任用熟悉當地的嚮導，便不能取得地利。這三項有一項不懂，就不能成為稱霸諸侯的軍隊。稱霸諸侯的軍隊攻打大國，能使敵方兵眾來不及集結；把威勢加在敵人身上，能使其盟國無法聯合。因此，不必爭著同天下各國結交，也不必培植各國的權勢，只推行自己的戰略意圖，把威勢施加於敵，於是可以攻下敵城、摧毀敵國。施行超出常規的獎賞，發布非常時期的號令，指揮全軍如同一人。只交付具體任務，不預告全部意圖；以有利前景驅使他們，不把危險全盤告知；把部隊置於亡地而後得以生存，陷於死地而後反能求生。士卒陷入危急，才可能竭力決定勝敗。用兵的要領，在於順應或偽裝迎合敵人的意圖，集中兵力指向同一目標，奔襲千里擒殺敵將，這才叫巧妙地成就戰事。","analysis":"本段把情報、地理與在地嚮導列為遠徵的三個前提，接著論述阻止強敵集結及結盟。「順詳敵之意」歷來有「詳」通「佯」、即假裝順從敵意等解，也可有審察、順應敵情的理解，故譯文保留兩層可能，原文不逕改。「無法之賞」「無政之令」是超出平時制度的非常措施，不等於可以任意違法；「勿告以害」則反映古代對士卒資訊的控制。現代決策不宜以隱瞞重大風險操縱人員，尤其必須遵守法律、知情義務與問責制度。"}},{"id":"art-of-war_ch-11_p-8","chapterId":"art-of-war_ch-11","order":8,"canonicalText":"是故政舉之日，夷關折符，無通其使，厲於廊廟之上，以誅其事，敵人開闔，必亟入之。先其所愛，微與之期，賤墨隨敵，以決戰爭。是故始如處女，敵人開戶，後如脫兔，敵不及拒。","sentenceIds":["art-of-war_ch-11_p-8_s-1","art-of-war_ch-11_p-8_s-2","art-of-war_ch-11_p-8_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"},{"label":"維基文庫《孫子兵法》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%AD%AB%E5%AD%90%E5%85%B5%E6%B3%95"}],"readingAid":{"translation":"所以決定出兵之日，要封閉關口、折毀通行符節，不讓使者往來；在廟堂上嚴密研議，以督促並決定軍事部署。敵人防線一有開合的空隙，必須迅速進入；搶先攻取敵人最重視之處，不先同敵人約定決戰，依敵情變化而遵循作戰尺度，以決定戰事。起初要像未出閨門的女子那樣沉靜柔弱，使敵人放鬆戒備、敞開門戶；隨後要像逃脫的兔子那樣迅疾，使敵人來不及抵抗。","analysis":"結尾概括「先隱蔽、後突發」：先封鎖消息、在決策中樞定策，等敵方出現縫隙便攻其所愛，並隨敵情調整，最後以速度完成突破。「微與之期，賤墨隨敵」傳本歧義較大，通行整理本常見「踐墨隨敵」，多解為不與敵預約、依循法度而隨敵應變；中國哲學書電子化計劃所錄則作「賤墨」，因此本庫暫不擅改原文，譯文採取較通行的義理解讀，待據底本影像逐字定讞。「處女」是古代性別化譬喻，核心只是前後狀態的反差，不應把性別刻板印象當作普遍事實。"}},{"id":"art-of-war_ch-12_p-1","chapterId":"art-of-war_ch-12","order":1,"canonicalText":"孫子曰：凡火攻有五：一曰火人，二曰火積，三曰火輜，四曰火庫，五曰火隊。行火必有因，煙火必素具。發火有時，起火有日。時者，天之燥也。日者，月在箕壁翼軫也。凡此四宿者，風起之日也。","sentenceIds":["art-of-war_ch-12_p-1_s-1","art-of-war_ch-12_p-1_s-2","art-of-war_ch-12_p-1_s-3","art-of-war_ch-12_p-1_s-4","art-of-war_ch-12_p-1_s-5","art-of-war_ch-12_p-1_s-6"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"},{"label":"維基文庫《孫子兵法》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%AD%AB%E5%AD%90%E5%85%B5%E6%B3%95"}],"readingAid":{"translation":"孫子說：火攻有五種：焚燒敵軍人馬、焚燒糧草、焚燒輜重、焚燒倉庫、焚燒運輸通道。實施火攻必須具備條件，放火器材要預先準備。放火要看天時，也要選日子。天時是氣候乾燥；日子是月亮運行到箕、壁、翼、軫四宿的時候，這幾天通常容易起風。","analysis":"【主題與背景】本段為《孫子兵法》〈火攻篇〉的開篇，主要論述了火攻的目標分類以及實施火攻所必須具備的天文與物質條件。\\n【訓詁與名物】「火人」指焚燒敵軍營帳人馬；「火積」為焚燒糧草積聚；「火輜」為焚燒輜重車輛；「火庫」為焚燒軍需物資倉庫；「火隊」指焚燒敵軍運糧通道或陣列。「因」指內應或條件；「素具」即平時準備好引火之物。「箕壁翼軫」為中國古代二十八宿中的四個星宿，古人認為月亮行經此處時多風。\\n【章法與結構】首句破題，列舉火攻的五個攻擊目標；次句說明火攻的物質與內在條件（必有因、必素具）；最後則詳細規定了火攻所需的自然條件（天時與日子），層次分明，由戰略目標遞進至戰術執行細節。\\n【思想與義理】孫子將「火」視為借用自然力量的終極武器。本段展示了中國古代兵家將天文氣象（時、日、星宿）與軍事行動深度結合的「天人合一」實戰觀。戰爭不只是人與人的對抗，更是對自然規律的掌握與運用，強調了將帥必須具備豐富的科學常識。"}},{"id":"art-of-war_ch-12_p-2","chapterId":"art-of-war_ch-12","order":2,"canonicalText":"凡火攻，必因五火之變而應之，火發於內，則早應之於外。火發而其兵靜者，待而勿攻。極其火力，可從而從之，不可從而止。火可發於外，無待於內，以時發之。火發上風，無攻下風，晝風久，夜風止。凡軍必知五火之變，以數守之。故以火佐攻者明，以水佐攻者強，水可以絕，不可以奪。","sentenceIds":["art-of-war_ch-12_p-2_s-1","art-of-war_ch-12_p-2_s-2","art-of-war_ch-12_p-2_s-3","art-of-war_ch-12_p-2_s-4","art-of-war_ch-12_p-2_s-5","art-of-war_ch-12_p-2_s-6","art-of-war_ch-12_p-2_s-7"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"},{"label":"維基文庫《孫子兵法》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%AD%AB%E5%AD%90%E5%85%B5%E6%B3%95"}],"readingAid":{"translation":"實施火攻，必須根據五種火勢變化作出響應。火從敵營內部燒起，要及早從外面配合進攻；火已燒起而敵軍仍安靜，要等待觀察，不可立即進攻。等火勢最旺，能進攻便進攻，不能便停止。也可從外部放火，不必等待內應，只要選好時機。火在上風燃起，不可從下風進攻。白天風颳得久，夜間通常會停。軍隊必須懂得五種火攻變化，按照規律戒備。用火輔助進攻，效果明顯；用水輔助進攻，聲勢強大。水可以截斷敵軍，卻不能像火一樣直接奪取敵人物資。","analysis":"【主題與背景】本段出自《孫子兵法》〈火攻篇〉。孫子進一步探討了實施火攻後的戰術應變方案，以及對自然力量輔助進攻的客觀評價。\\n【訓詁與名物】「五火之變」指前述五種火攻引發的敵情變化；「以數守之」意為根據自然氣象規律來防範火攻；「以火佐攻」即藉火勢輔助進攻；「水可以絕，不可以奪」意謂水攻能截斷敵軍陣型或補給線，但無法像火攻那樣將敵方物資徹底燒毀奪去。\\n【章法與結構】全段詳細羅列了火攻實施後的各種戰術應變方案。先論火發於內外的情形及敵軍反應（兵靜則待）；再論放火的風向及日夜風勢變化；最後跳出火攻本身，將「火」與「水」進行對比，總結兩者在軍事輔助上的不同功效與限制。\\n【思想與義理】此段充分展現了兵法的「變機」之學。火雖無情，但用火必須極其冷靜，視敵軍反應與自然條件「可從而從，不可從而止」，不可盲目進擊。同時對火、水兩種自然力量的客觀評價（明與強、奪與絕），顯現出孫子對戰爭工具特性的精確把握與理性思維。"}},{"id":"art-of-war_ch-12_p-3","chapterId":"art-of-war_ch-12","order":3,"canonicalText":"夫戰勝攻取，而不修其攻者兇，命曰費留。故曰：明主慮之，良將修之，非利不動，非得不用，非危不戰。主不可以怒而興師，將不可以慍而致戰；合於利而動，不合於利而止。怒可以復喜，慍可以復悅，亡國不可以復存，死者不可以復生。故明君慎之，良將警之，此安國全軍之道也。","sentenceIds":["art-of-war_ch-12_p-3_s-1","art-of-war_ch-12_p-3_s-2","art-of-war_ch-12_p-3_s-3","art-of-war_ch-12_p-3_s-4","art-of-war_ch-12_p-3_s-5","art-of-war_ch-12_p-3_s-6"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"},{"label":"維基文庫《孫子兵法》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%AD%AB%E5%AD%90%E5%85%B5%E6%B3%95"}],"readingAid":{"translation":"打了勝仗、攻取了城池，卻不能鞏固戰果、修明政治，那是很危險的，這叫作「費留」（白白消耗國家資源卻無法長久保留）。所以說：明智的國君要深謀遠慮，優秀的將領要認真執行。對國家沒有實質利益就不要行動，沒有取勝的把握就不要用兵，不到危急關頭就不要輕易開戰。國君不能因為一時的憤怒就發動戰爭，將領不能因為一時的怨恨就主動與敵人交戰；符合國家利益纔行動，不符合國家利益就停止。憤怒還可以重新轉為喜悅，怨恨也可以重新轉為高興，但國家滅亡了就不能復興，人死了就不能復活。因此，明智的國君對待戰爭必須慎重，優秀的將領對待戰爭必須警惕，這是安定國家、保全軍隊的根本原則。","analysis":"【主題與背景】本段為《孫子兵法》〈火攻篇〉的結尾。孫子在此從戰術層面躍升至國家戰略高度，提出了其著名的「慎戰」與「非利不動」思想。\\n【訓詁與名物】「修其攻」意指修明政治、鞏固戰果與論功行賞；「費留」即徒然消耗國力而使得戰爭遺留後患；「慍」為怨恨或惱怒。\\n【章法與結構】先提出「費留」的危險，再拋出「非利不動」的三不原則；接著以強烈對比（怒可復喜vs亡國不復存）警告君將不可感情用事；最後以「慎之、警之」總結，點出「安國全軍」的主旨。\\n【思想與義理】這是《孫子兵法》全書最深刻的反戰與慎戰宣言。孫子指出，軍事勝利若不能轉化為國家利益，只會加速國家敗亡。他極力反對將帥因個人情緒（怒、慍）而輕啟戰端，強調戰爭是死生亡國的單向道，體現了兵家以「安國全軍」為最高目的的人道主義與政治理性。"}},{"id":"art-of-war_ch-13_p-1","chapterId":"art-of-war_ch-13","order":1,"canonicalText":"孫子曰：凡興師十萬，出征千里，百姓之費，公家之奉，日費千金，內外騷動，怠於道路，不得操事者，七十萬家，相守數年，以爭一日之勝，而愛爵祿百金，不知敵之情者，不仁之至也，非人之將也，非主之佐也，非勝之主也。故明君賢將，所以動而勝人，成功出於眾者，先知也；先知者，不可取於鬼神，不可象於事，不可驗於度；必取於人，知敵之情者也。","sentenceIds":["art-of-war_ch-13_p-1_s-1","art-of-war_ch-13_p-1_s-2","art-of-war_ch-13_p-1_s-3","art-of-war_ch-13_p-1_s-4"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"},{"label":"維基文庫《孫子兵法》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%AD%AB%E5%AD%90%E5%85%B5%E6%B3%95"}],"readingAid":{"translation":"孫子說：出動十萬大軍，遠徵千里，百姓負擔和國家開支每天耗費千金，內外騷動，運輸道路上的人疲憊不堪，不能正常耕作的有七十萬家。雙方相持多年，只為決定一日勝負；若吝惜爵祿和少量金錢，不肯用來掌握敵情，就是極端不仁，既不是合格將領，也不是君主助手，更不是勝利主宰。明君賢將一齣兵便能勝人、成功超過眾人，原因在於事先了解敵情。這種先知不能向鬼神求取，不能拿相似事物類推，也不能靠星度驗證；必須從了解敵情的人那裡取得。","analysis":"【主題與背景】本段為《孫子兵法》〈用間篇〉的開篇。孫子論述了情報工作對戰爭勝負的決定性作用，並強烈抨擊吝惜情報經費的行為。\\n【訓詁與名物】「公家之奉」指國家的軍費開支；「不得操事」指無法從事正常的農業生產；「先知」即預先掌握敵情；「不可象於事」指不能僅憑相似的歷史事件來主觀推測；「不可驗於度」指不能依賴占星度數來驗證；「必取於人」指必須從知情人的口中獲取情報。\\n【章法與結構】先以龐大的數字（十萬、千里、日費千金、七十萬家）鋪陳戰爭對國家社會的巨大消耗；隨即筆鋒一轉，嚴厲斥責吝惜情報經費的將領是「不仁之至」。最後推導出「先知」的必要性，並破除迷信，強調情報必須來自「人」。\\n【思想與義理】孫子在此展現了極具現代性的情報學觀念。他認為戰爭最大的成本是國家整體的消耗，相較之下，用於情報工作的「爵祿百金」微不足道。同時，他堅決反對當時流行的鬼神卜筮與星象佔測，堅持唯物主義的情報蒐集觀——情報必須靠實地偵察與間諜人員來獲取。"}},{"id":"art-of-war_ch-13_p-2","chapterId":"art-of-war_ch-13","order":2,"canonicalText":"故用間有五：有鄉間、有內間、有反間、有死間、有生間。五間俱起，莫知其道，是謂神紀，人君之寶也。鄉間者，因其鄉人而用之。內間者，因其官人而用之。反間者，因其敵間而用之。死間者，為誑事於外，令吾間知之，而傳於敵。生間者，反報也。","sentenceIds":["art-of-war_ch-13_p-2_s-1","art-of-war_ch-13_p-2_s-2","art-of-war_ch-13_p-2_s-3","art-of-war_ch-13_p-2_s-4","art-of-war_ch-13_p-2_s-5","art-of-war_ch-13_p-2_s-6","art-of-war_ch-13_p-2_s-7"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"},{"label":"維基文庫《孫子兵法》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%AD%AB%E5%AD%90%E5%85%B5%E6%B3%95"}],"readingAid":{"translation":"所以，使用間諜的方法有五種：有「鄉間」、有「內間」、有「反間」、有「死間」、有「生間」。這五種間諜同時運用起來，敵人根本無法摸清我方獲取情報的途徑，這叫做神妙莫測的紀綱，是國君用以克敵制勝的法寶。「鄉間」，是利用敵國的平民來做間諜。「內間」，是收買敵國的官員來做間諜。「反間」，是收買或利用敵方派來的間諜為我所用。「死間」，是故意在外散佈假情報，讓我們的間諜知道，然後傳遞給敵人，一旦事發必定被處死。「生間」，是潛入敵營偵察後，能活著回來報告情報的間諜。","analysis":"【主題與背景】本段出自《孫子兵法》〈用間篇〉。孫子在此係統性地提出了中國軍事史上最早、最完備的「五間」情報網絡理論。\\n【訓詁與名物】「鄉間」指利用敵國鄉民為間；「內間」指收買敵國官員為間；「反間」指反用敵方派來的間諜；「死間」指故意攜帶假情報赴敵營，事發必死的間諜；「生間」指潛入敵方能生還匯報的間諜。「神紀」意謂神妙莫測的間諜網綱紀。\\n【章法與結構】全段採用總分結構。開頭先總列五種間諜的名稱，並給予「神紀」、「人君之寶」的極高評價。隨後逐一精準定義五種間諜的運作模式，文句簡鍊對仗，毫無贅字。\\n【思想與義理】孫子將情報工作細分為五大系統，構建了完備的間諜理論體系。他認識到情報來源必須多元化（平民、官員、敵諜），且手段必須虛實結合（死間傳假，生間報真），當五種間諜網交織運作時，就能形成讓敵人無從察覺的情報黑洞，是為君主掌控戰爭主動權的核心法寶。"}},{"id":"art-of-war_ch-13_p-3","chapterId":"art-of-war_ch-13","order":3,"canonicalText":"故三軍之事，親莫親於間，賞莫厚於間，事莫密於間，非聖智不能用間，非仁義不能使間，非微妙不能得間之實。微哉，微哉，無所不用間也。間事未發而先聞者，間與所告者皆死。","sentenceIds":["art-of-war_ch-13_p-3_s-1","art-of-war_ch-13_p-3_s-2","art-of-war_ch-13_p-3_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"},{"label":"維基文庫《孫子兵法》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%AD%AB%E5%AD%90%E5%85%B5%E6%B3%95"}],"readingAid":{"translation":"軍中關係沒有比間諜更親密的，獎賞沒有比給間諜更優厚的，事情沒有比間諜工作更機密的。不是具有高超智慧的人不能使用間諜，不是仁厚正直的人不能驅使間諜，不是心思精細微妙的人不能取得真實情報。微妙啊，任何地方都可以運用間諜。間諜任務尚未行動便已洩漏，間諜和知道消息的人都要處死。","analysis":"【主題與背景】本段出自《孫子兵法》〈用間篇〉。主要論述了情報工作的極端機密性，以及主帥駕馭間諜所必須具備的高尚品格與智慧。\\n【訓詁與名物】「親」指信任與親密程度；「聖智」指超乎常人的智慧與洞察力；「仁義」在此指以誠信和優厚待遇收攬人心；「微妙」指心思細密，能辨別情報真偽；「間事未發而先聞者」指間諜行動尚未展開就已走漏風聲。\\n【章法與結構】本段論述用間者的素養與保密原則。先以三個「莫...於」強調間諜在軍中的極高地位（最親信、獎賞最厚、機密最高）；再以三個「非...不能」點出主帥運用間諜所需的極高品格與能力。最後以最嚴厲的死刑軍令作結，凸顯情報保密的殘酷性。\\n【思想與義理】孫子深刻洞察到，間諜工作是人性的極致考驗。要驅使人在極度危險與背叛邊緣工作，單靠金錢是不夠的，必須輔以主帥的「仁義」恩結與「聖智」駕馭；而對於情報的篩選，更需「微妙」的洞察。這說明兵法的冷酷無情（洩密皆死）與將帥的人性修養在此達到了奇妙的統一。"}},{"id":"art-of-war_ch-13_p-4","chapterId":"art-of-war_ch-13","order":4,"canonicalText":"凡軍之所欲擊，城之所欲攻，人之所欲殺；必先知其守將，左右，謁者，門者，舍人之姓名，令吾間必索知之。必索敵間之來間我者，因而利之，導而舍之，故反間可得而使也。因是而知之，故鄉間內間可得而使也；因是而知之，故死間為誑事，可使告敵；因是而知之，故生間可使如期。五間之事，主必知之，知之必在於反間，故反間不可不厚也。","sentenceIds":["art-of-war_ch-13_p-4_s-1","art-of-war_ch-13_p-4_s-2","art-of-war_ch-13_p-4_s-3","art-of-war_ch-13_p-4_s-4","art-of-war_ch-13_p-4_s-5","art-of-war_ch-13_p-4_s-6","art-of-war_ch-13_p-4_s-7"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"},{"label":"維基文庫《孫子兵法》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%AD%AB%E5%AD%90%E5%85%B5%E6%B3%95"}],"readingAid":{"translation":"凡是軍隊想要攻擊的目標，想要攻打的城池，想要暗殺的人員，都必須先了解敵方的守城將領、左右親信、負責傳達的官員、守門的衛兵以及門客幕僚的姓名，一定要命令我們的間諜把這些調查清楚。必須搜查出敵人派來偵察我方的間諜，然後用重金收買他，優待並引導他，再放他回去，這樣「反間」（雙面間諜）就可以為我所用了。因為有了反間提供的情報，就能了解敵國的情況，所以「鄉間」和「內間」就可以去發展和運用了。因為有了反間提供的情報，了解到敵人的思維盲區，所以「死間」就能去散佈假情報，用來欺騙敵人。因為有了反間提供的情報，所以「生間」就能按照預定的期限回來報告敵情。五種間諜的工作，國君必須親自掌握，而掌握這五種間諜的關鍵，就在於運用「反間」，所以對待「反間」的待遇絕不能不優厚。","analysis":"【主題與背景】本段為〈用間篇〉的總結，詳細說明瞭情報蒐集的具體目標，並點出「反間」在整個情報網絡中的核心樞紐地位。\\n【訓詁與名物】「謁者」指負責通報的侍衛官；「門者」為守門人；「舍人」為將領的門客或幕僚。「因而利之」指就勢用重金收買他；「導而舍之」指引導他並放他回敵營作反間。\\n【章法與結構】前半部強調情報收集必須具體到敵方核心人物及周邊隨從的姓名；後半部則反覆使用「因是而知之」，層層遞進地論證「反間」是啟動其他四種間諜的核心樞紐。最後歸結到「反間不可不厚」，首尾呼應。\\n【思想與義理】孫子指出，間諜網絡不是平行運作的，而是有核心樞紐的，這個樞紐就是「反間」（敵方派來的間諜）。因為反間最熟悉敵國國情與人事網絡，只有掌控了反間，才能順利發展鄉間、內間，並準確地讓死間散佈假消息。這展現了極其高超的「借力打力」情報哲學。"}},{"id":"art-of-war_ch-13_p-5","chapterId":"art-of-war_ch-13","order":5,"canonicalText":"昔殷之興也，伊摯在夏。周之興也，呂牙在殷。故明君賢將，能以上智為間者，必成大功，此兵之要，三軍之所恃而動也。","sentenceIds":["art-of-war_ch-13_p-5_s-1","art-of-war_ch-13_p-5_s-2","art-of-war_ch-13_p-5_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/art-of-war/zh"},{"label":"維基文庫《孫子兵法》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%AD%AB%E5%AD%90%E5%85%B5%E6%B3%95"}],"readingAid":{"translation":"從前商朝興起，伊摯曾在夏朝掌握內情；周朝興起，呂牙曾在商朝掌握內情。因此明君賢將若能任用智慧高超的人作間諜，必能建立大功。這是用兵的關鍵，也是全軍據以行動的依靠。","analysis":"【主題與背景】本段出自《孫子兵法・用間》，屬於兵家典籍之核心篇章。全篇旨在闡發知己知彼、因敵制勝、慎戰備戰與軍事謀略。\\n【詞義與名物】經典經文「昔殷之興也，伊摯在夏。周之興也，呂牙在殷。故明君賢...」蘊含關鍵詞彙如「昔殷之興、伊摯在夏、周之興也、呂牙在殷」，反應古代歷史脈絡、社會制度與名物考訂。\\n【章旨與解析】本段通過嚴密的修辭與論證脈絡，強調在實際行動與心性修養中貫徹兵家思想，為後世提供了深刻的智謀與處世借鑑。"}}],"sentences":[{"id":"art-of-war_ch-1_p-1_s-1","passageId":"art-of-war_ch-1_p-1","order":1,"canonicalText":"孫子曰：兵者，國之大事，死生之地，存亡之道，不可不察也。","chunks":[["孫子曰：兵者，國之大事，死生之地，存亡之道，不可不察也。","zh-Hant"]]},{"id":"art-of-war_ch-1_p-2_s-1","passageId":"art-of-war_ch-1_p-2","order":1,"canonicalText":"故經之以五事，校之以計，而索其情，一曰道，二曰天，三曰地，四曰將，五曰法。","chunks":[["故經之以五事，校之以計，而索其情，一曰道，二曰天，三曰地，四曰將，五曰法。","zh-Hant"]]},{"id":"art-of-war_ch-1_p-3_s-1","passageId":"art-of-war_ch-1_p-3","order":1,"canonicalText":"道者，令民與上同意也，可與之死，可與之生，而不畏危。","chunks":[["道者，令民與上同意也，可與之死，可與之生，而不畏危。","zh-Hant"]]},{"id":"art-of-war_ch-1_p-3_s-2","passageId":"art-of-war_ch-1_p-3","order":2,"canonicalText":"天者，陰陽，寒暑，時制也。","chunks":[["天者，陰陽，寒暑，時制也。","zh-Hant"]]},{"id":"art-of-war_ch-1_p-3_s-3","passageId":"art-of-war_ch-1_p-3","order":3,"canonicalText":"地者，遠近，險易，廣狹，死生也。","chunks":[["地者，遠近，險易，廣狹，死生也。","zh-Hant"]]},{"id":"art-of-war_ch-1_p-3_s-4","passageId":"art-of-war_ch-1_p-3","order":4,"canonicalText":"將者，智，信，仁，勇，嚴也。","chunks":[["將者，智，信，仁，勇，嚴也。","zh-Hant"]]},{"id":"art-of-war_ch-1_p-3_s-5","passageId":"art-of-war_ch-1_p-3","order":5,"canonicalText":"法者，曲制，官道，主用也。","chunks":[["法者，曲制，官道，主用也。","zh-Hant"]]},{"id":"art-of-war_ch-1_p-3_s-6","passageId":"art-of-war_ch-1_p-3","order":6,"canonicalText":"凡此五者，將莫不聞，知之者勝，不知者不勝。","chunks":[["凡此五者，將莫不聞，知之者勝，不知者不勝。","zh-Hant"]]},{"id":"art-of-war_ch-1_p-4_s-1","passageId":"art-of-war_ch-1_p-4","order":1,"canonicalText":"故校之以計，而索其情。","chunks":[["故校之以計，而索其情。","zh-Hant"]]},{"id":"art-of-war_ch-1_p-4_s-2","passageId":"art-of-war_ch-1_p-4","order":2,"canonicalText":"曰：主孰有道，將孰有能，天地孰得，法令孰行，兵眾孰強，士卒孰練，賞罰孰明，吾以此知勝負矣。","chunks":[["曰：主孰有道，將孰有能，天地孰得，法令孰行，兵眾孰強，士卒孰練，賞罰孰明，吾以此知勝負矣。","zh-Hant"]]},{"id":"art-of-war_ch-1_p-4_s-3","passageId":"art-of-war_ch-1_p-4","order":3,"canonicalText":"將聽吾計，用之必勝，留之；","chunks":[["將聽吾計，用之必勝，留之；","zh-Hant"]]},{"id":"art-of-war_ch-1_p-4_s-4","passageId":"art-of-war_ch-1_p-4","order":4,"canonicalText":"將不聽吾計，用之必敗，去之。","chunks":[["將不聽吾計，用之必敗，去之。","zh-Hant"]]},{"id":"art-of-war_ch-1_p-5_s-1","passageId":"art-of-war_ch-1_p-5","order":1,"canonicalText":"計利以聽，乃為之勢，以佐其外；","chunks":[["計利以聽，乃為之勢，以佐其外；","zh-Hant"]]},{"id":"art-of-war_ch-1_p-5_s-2","passageId":"art-of-war_ch-1_p-5","order":2,"canonicalText":"勢者，因利而制權也。","chunks":[["勢者，因利而制權也。","zh-Hant"]]},{"id":"art-of-war_ch-1_p-6_s-1","passageId":"art-of-war_ch-1_p-6","order":1,"canonicalText":"兵者，詭道也。","chunks":[["兵者，詭道也。","zh-Hant"]]},{"id":"art-of-war_ch-1_p-6_s-2","passageId":"art-of-war_ch-1_p-6","order":2,"canonicalText":"故能而示之不能，用而示之不用，近而示之遠，遠而示之近。","chunks":[["故能而示之不能，用而示之不用，近而示之遠，遠而示之近。","zh-Hant"]]},{"id":"art-of-war_ch-1_p-6_s-3","passageId":"art-of-war_ch-1_p-6","order":3,"canonicalText":"利而誘之，亂而取之，實而備之，強而避之，怒而撓之，卑而驕之，佚而勞之，親而離之。","chunks":[["利而誘之，亂而取之，實而備之，強而避之，怒而撓之，卑而驕之，佚而勞之，親而離之。","zh-Hant"]]},{"id":"art-of-war_ch-1_p-6_s-4","passageId":"art-of-war_ch-1_p-6","order":4,"canonicalText":"攻其無備，出其不意，此兵家之勝，不可先傳也。","chunks":[["攻其無備，出其不意，此兵家之勝，不可先傳也。","zh-Hant"]]},{"id":"art-of-war_ch-1_p-7_s-1","passageId":"art-of-war_ch-1_p-7","order":1,"canonicalText":"夫未戰而廟算勝者，得算多也；","chunks":[["夫未戰而廟算勝者，得算多也；","zh-Hant"]]},{"id":"art-of-war_ch-1_p-7_s-2","passageId":"art-of-war_ch-1_p-7","order":2,"canonicalText":"未戰而廟算不勝者，得算少也；","chunks":[["未戰而廟算不勝者，得算少也；","zh-Hant"]]},{"id":"art-of-war_ch-1_p-7_s-3","passageId":"art-of-war_ch-1_p-7","order":3,"canonicalText":"多算勝，少算不勝，而況於無算乎？","chunks":[["多算勝，少算不勝，而況於無算乎？","zh-Hant"]]},{"id":"art-of-war_ch-1_p-7_s-4","passageId":"art-of-war_ch-1_p-7","order":4,"canonicalText":"吾以此觀之，勝負見矣。","chunks":[["吾以此觀之，勝負見矣。","zh-Hant"]]},{"id":"art-of-war_ch-2_p-1_s-1","passageId":"art-of-war_ch-2_p-1","order":1,"canonicalText":"孫子曰：凡用兵之法，馳車千駟，革車千乘，帶甲十萬；","chunks":[["孫子曰：凡用兵之法，馳車千駟，革車千乘，帶甲十萬；","zh-Hant"]]},{"id":"art-of-war_ch-2_p-1_s-2","passageId":"art-of-war_ch-2_p-1","order":2,"canonicalText":"千里饋糧，則內外之費賓客之用，膠漆之材，車甲之奉，日費千金，然後十萬之師舉矣。","chunks":[["千里饋糧，則內外之費賓客之用，膠漆之材，車甲之奉，日費千金，然後十萬之師舉矣。","zh-Hant"]]},{"id":"art-of-war_ch-2_p-2_s-1","passageId":"art-of-war_ch-2_p-2","order":1,"canonicalText":"其用戰也，勝久則鈍兵挫銳，攻城則力屈，久暴師則國用不足。","chunks":[["其用戰也，勝久則鈍兵挫銳，攻城則力屈，久暴師則國用不足。","zh-Hant"]]},{"id":"art-of-war_ch-2_p-2_s-2","passageId":"art-of-war_ch-2_p-2","order":2,"canonicalText":"夫鈍兵，挫銳，屈力，殫貨，則諸侯乘其弊而起，雖有智者，不能善其後矣！","chunks":[["夫鈍兵，挫銳，屈力，殫貨，則諸侯乘其弊而起，雖有智者，不能善其後矣！","zh-Hant"]]},{"id":"art-of-war_ch-2_p-2_s-3","passageId":"art-of-war_ch-2_p-2","order":3,"canonicalText":"故兵聞拙速，未睹巧之久也；","chunks":[["故兵聞拙速，未睹巧之久也；","zh-Hant"]]},{"id":"art-of-war_ch-2_p-2_s-4","passageId":"art-of-war_ch-2_p-2","order":4,"canonicalText":"夫兵久而國利者，未之有也。","chunks":[["夫兵久而國利者，未之有也。","zh-Hant"]]},{"id":"art-of-war_ch-2_p-3_s-1","passageId":"art-of-war_ch-2_p-3","order":1,"canonicalText":"故不盡知用兵之害者，則不能盡知用兵之利也。","chunks":[["故不盡知用兵之害者，則不能盡知用兵之利也。","zh-Hant"]]},{"id":"art-of-war_ch-2_p-3_s-2","passageId":"art-of-war_ch-2_p-3","order":2,"canonicalText":"善用兵者，役不再籍，糧不三載，取用於國，因糧於敵，故軍食可足也。","chunks":[["善用兵者，役不再籍，糧不三載，取用於國，因糧於敵，故軍食可足也。","zh-Hant"]]},{"id":"art-of-war_ch-2_p-3_s-3","passageId":"art-of-war_ch-2_p-3","order":3,"canonicalText":"國之貧於師者遠輸，遠輸則百姓貧，近於師者貴賣，貴賣則百姓財竭，財竭則急於丘役，力屈財殫，中原內虛於家，百姓之費，十去其七，公家之費，破車罷馬，甲冑矢弩，戟楯蔽櫓，丘牛大車，十去其六。","chunks":[["國之貧於師者遠輸，遠輸則百姓貧，近於師者貴賣，貴賣則百姓財竭，財竭則急於丘役，力屈財殫，中原內虛於家，百姓之費，十去其七，公家之費，破車罷馬，甲冑矢弩，戟楯蔽櫓，丘牛大車，十去其六。","zh-Hant"]]},{"id":"art-of-war_ch-2_p-4_s-1","passageId":"art-of-war_ch-2_p-4","order":1,"canonicalText":"故智將務食於敵，食敵一鍾，當吾二十鍾，𦮼稈一石，當我二十石。","chunks":[["故智將務食於敵，食敵一鍾，當吾二十鍾，𦮼稈一石，當我二十石。","zh-Hant"]]},{"id":"art-of-war_ch-2_p-4_s-2","passageId":"art-of-war_ch-2_p-4","order":2,"canonicalText":"故殺敵者怒也，取敵之利者貨也。","chunks":[["故殺敵者怒也，取敵之利者貨也。","zh-Hant"]]},{"id":"art-of-war_ch-2_p-4_s-3","passageId":"art-of-war_ch-2_p-4","order":3,"canonicalText":"故車戰，得車十乘以上，賞其先得者，而更其旌旗，車雜而乘之，卒善而養之，是謂勝敵而益強。","chunks":[["故車戰，得車十乘以上，賞其先得者，而更其旌旗，車雜而乘之，卒善而養之，是謂勝敵而益強。","zh-Hant"]]},{"id":"art-of-war_ch-2_p-5_s-1","passageId":"art-of-war_ch-2_p-5","order":1,"canonicalText":"故兵貴勝，不貴久；","chunks":[["故兵貴勝，不貴久；","zh-Hant"]]},{"id":"art-of-war_ch-2_p-5_s-2","passageId":"art-of-war_ch-2_p-5","order":2,"canonicalText":"故知兵之將，民之司命，國家安危之主也。","chunks":[["故知兵之將，民之司命，國家安危之主也。","zh-Hant"]]},{"id":"art-of-war_ch-3_p-1_s-1","passageId":"art-of-war_ch-3_p-1","order":1,"canonicalText":"孫子曰：凡用兵之法，全國為上，破國次之；全軍為上，破軍次之；","chunks":[["孫子曰：凡用兵之法，全國為上，破國次之；全軍為上，破軍次之；","zh-Hant"]]},{"id":"art-of-war_ch-3_p-1_s-2","passageId":"art-of-war_ch-3_p-1","order":2,"canonicalText":"全旅為上，破旅次之；","chunks":[["全旅為上，破旅次之；","zh-Hant"]]},{"id":"art-of-war_ch-3_p-1_s-3","passageId":"art-of-war_ch-3_p-1","order":3,"canonicalText":"全卒為上，破卒次之；","chunks":[["全卒為上，破卒次之；","zh-Hant"]]},{"id":"art-of-war_ch-3_p-1_s-4","passageId":"art-of-war_ch-3_p-1","order":4,"canonicalText":"全伍為上，破伍次之。","chunks":[["全伍為上，破伍次之。","zh-Hant"]]},{"id":"art-of-war_ch-3_p-1_s-5","passageId":"art-of-war_ch-3_p-1","order":5,"canonicalText":"是故百戰百勝，非善之善者也；","chunks":[["是故百戰百勝，非善之善者也；","zh-Hant"]]},{"id":"art-of-war_ch-3_p-1_s-6","passageId":"art-of-war_ch-3_p-1","order":6,"canonicalText":"不戰而屈人之兵，善之善者也。","chunks":[["不戰而屈人之兵，善之善者也。","zh-Hant"]]},{"id":"art-of-war_ch-3_p-2_s-1","passageId":"art-of-war_ch-3_p-2","order":1,"canonicalText":"故上兵伐謀，其次伐交，其次伐兵，其下攻城。","chunks":[["故上兵伐謀，其次伐交，其次伐兵，其下攻城。","zh-Hant"]]},{"id":"art-of-war_ch-3_p-2_s-2","passageId":"art-of-war_ch-3_p-2","order":2,"canonicalText":"攻城之法，為不得已；","chunks":[["攻城之法，為不得已；","zh-Hant"]]},{"id":"art-of-war_ch-3_p-2_s-3","passageId":"art-of-war_ch-3_p-2","order":3,"canonicalText":"修櫓轒轀，具器械，三月而後成；","chunks":[["修櫓轒轀，具器械，三月而後成；","zh-Hant"]]},{"id":"art-of-war_ch-3_p-2_s-4","passageId":"art-of-war_ch-3_p-2","order":4,"canonicalText":"距闉，又三月而後已；","chunks":[["距闉，又三月而後已；","zh-Hant"]]},{"id":"art-of-war_ch-3_p-2_s-5","passageId":"art-of-war_ch-3_p-2","order":5,"canonicalText":"將不勝其忿，而蟻附之，殺士卒三分之一，而城不拔者，此攻之災也。","chunks":[["將不勝其忿，而蟻附之，殺士卒三分之一，而城不拔者，此攻之災也。","zh-Hant"]]},{"id":"art-of-war_ch-3_p-3_s-1","passageId":"art-of-war_ch-3_p-3","order":1,"canonicalText":"故善用兵者，屈人之兵，而非戰也；","chunks":[["故善用兵者，屈人之兵，而非戰也；","zh-Hant"]]},{"id":"art-of-war_ch-3_p-3_s-2","passageId":"art-of-war_ch-3_p-3","order":2,"canonicalText":"拔人之城，而非攻也；","chunks":[["拔人之城，而非攻也；","zh-Hant"]]},{"id":"art-of-war_ch-3_p-3_s-3","passageId":"art-of-war_ch-3_p-3","order":3,"canonicalText":"毀人之國，而非久也。","chunks":[["毀人之國，而非久也。","zh-Hant"]]},{"id":"art-of-war_ch-3_p-3_s-4","passageId":"art-of-war_ch-3_p-3","order":4,"canonicalText":"必以全爭於天下，故兵不頓，利可全，此謀攻之法也。","chunks":[["必以全爭於天下，故兵不頓，利可全，此謀攻之法也。","zh-Hant"]]},{"id":"art-of-war_ch-3_p-3_s-5","passageId":"art-of-war_ch-3_p-3","order":5,"canonicalText":"故用兵之法，十則圍之，五則攻之，倍則分之，敵則能戰之，少則能守之，不若則能避之。","chunks":[["故用兵之法，十則圍之，五則攻之，倍則分之，敵則能戰之，少則能守之，不若則能避之。","zh-Hant"]]},{"id":"art-of-war_ch-3_p-3_s-6","passageId":"art-of-war_ch-3_p-3","order":6,"canonicalText":"故小敵之堅，大敵之擒也。","chunks":[["故小敵之堅，大敵之擒也。","zh-Hant"]]},{"id":"art-of-war_ch-3_p-4_s-1","passageId":"art-of-war_ch-3_p-4","order":1,"canonicalText":"夫將者，國之輔也，輔周則國必強，輔隙則國必弱。","chunks":[["夫將者，國之輔也，輔周則國必強，輔隙則國必弱。","zh-Hant"]]},{"id":"art-of-war_ch-3_p-4_s-2","passageId":"art-of-war_ch-3_p-4","order":2,"canonicalText":"故軍之所以患於君者三：不知三軍之不可以進，而謂之進；","chunks":[["故軍之所以患於君者三：不知三軍之不可以進，而謂之進；","zh-Hant"]]},{"id":"art-of-war_ch-3_p-4_s-3","passageId":"art-of-war_ch-3_p-4","order":3,"canonicalText":"不知三軍之不可以退，而謂之退；","chunks":[["不知三軍之不可以退，而謂之退；","zh-Hant"]]},{"id":"art-of-war_ch-3_p-4_s-4","passageId":"art-of-war_ch-3_p-4","order":4,"canonicalText":"是謂縻軍。","chunks":[["是謂縻軍。","zh-Hant"]]},{"id":"art-of-war_ch-3_p-4_s-5","passageId":"art-of-war_ch-3_p-4","order":5,"canonicalText":"不知三軍之事，而同三軍之政，則軍士惑矣。","chunks":[["不知三軍之事，而同三軍之政，則軍士惑矣。","zh-Hant"]]},{"id":"art-of-war_ch-3_p-4_s-6","passageId":"art-of-war_ch-3_p-4","order":6,"canonicalText":"不知三軍之權，而同三軍之任，則軍士疑矣。","chunks":[["不知三軍之權，而同三軍之任，則軍士疑矣。","zh-Hant"]]},{"id":"art-of-war_ch-3_p-4_s-7","passageId":"art-of-war_ch-3_p-4","order":7,"canonicalText":"三軍既惑且疑，則諸侯之難至矣，是謂亂軍引勝。","chunks":[["三軍既惑且疑，則諸侯之難至矣，是謂亂軍引勝。","zh-Hant"]]},{"id":"art-of-war_ch-3_p-5_s-1","passageId":"art-of-war_ch-3_p-5","order":1,"canonicalText":"故知勝者有五：知可以戰與不可以戰者勝，識眾寡之用者勝，上下同欲者勝，以虞待不虞者勝，將能而君不御者勝；","chunks":[["故知勝者有五：知可以戰與不可以戰者勝，識眾寡之用者勝，上下同欲者勝，以虞待不虞者勝，將能而君不御者勝；","zh-Hant"]]},{"id":"art-of-war_ch-3_p-5_s-2","passageId":"art-of-war_ch-3_p-5","order":2,"canonicalText":"此五者，知勝之道也。","chunks":[["此五者，知勝之道也。","zh-Hant"]]},{"id":"art-of-war_ch-3_p-6_s-1","passageId":"art-of-war_ch-3_p-6","order":1,"canonicalText":"故曰：知彼知己，百戰不殆；","chunks":[["故曰：知彼知己，百戰不殆；","zh-Hant"]]},{"id":"art-of-war_ch-3_p-6_s-2","passageId":"art-of-war_ch-3_p-6","order":2,"canonicalText":"不知彼而知己，一勝一負；","chunks":[["不知彼而知己，一勝一負；","zh-Hant"]]},{"id":"art-of-war_ch-3_p-6_s-3","passageId":"art-of-war_ch-3_p-6","order":3,"canonicalText":"不知彼，不知己，每戰必敗。","chunks":[["不知彼，不知己，每戰必敗。","zh-Hant"]]},{"id":"art-of-war_ch-4_p-1_s-1","passageId":"art-of-war_ch-4_p-1","order":1,"canonicalText":"孫子曰：昔之善戰者，先為不可勝，以待敵之可勝，不可勝在己，可勝在敵。","chunks":[["孫子曰：昔之善戰者，先為不可勝，以待敵之可勝，不可勝在己，可勝在敵。","zh-Hant"]]},{"id":"art-of-war_ch-4_p-1_s-2","passageId":"art-of-war_ch-4_p-1","order":2,"canonicalText":"故善戰者，能為不可勝，不能使敵必可勝。","chunks":[["故善戰者，能為不可勝，不能使敵必可勝。","zh-Hant"]]},{"id":"art-of-war_ch-4_p-1_s-3","passageId":"art-of-war_ch-4_p-1","order":3,"canonicalText":"故曰：勝可知，而不可為。","chunks":[["故曰：勝可知，而不可為。","zh-Hant"]]},{"id":"art-of-war_ch-4_p-2_s-1","passageId":"art-of-war_ch-4_p-2","order":1,"canonicalText":"不可勝者，守也；","chunks":[["不可勝者，守也；","zh-Hant"]]},{"id":"art-of-war_ch-4_p-2_s-2","passageId":"art-of-war_ch-4_p-2","order":2,"canonicalText":"可勝者，攻也。","chunks":[["可勝者，攻也。","zh-Hant"]]},{"id":"art-of-war_ch-4_p-2_s-3","passageId":"art-of-war_ch-4_p-2","order":3,"canonicalText":"守則不足，攻則有餘。","chunks":[["守則不足，攻則有餘。","zh-Hant"]]},{"id":"art-of-war_ch-4_p-2_s-4","passageId":"art-of-war_ch-4_p-2","order":4,"canonicalText":"善守者，藏於九地之下；","chunks":[["善守者，藏於九地之下；","zh-Hant"]]},{"id":"art-of-war_ch-4_p-2_s-5","passageId":"art-of-war_ch-4_p-2","order":5,"canonicalText":"善攻者，動於九天之上，故能自保而全勝也。","chunks":[["善攻者，動於九天之上，故能自保而全勝也。","zh-Hant"]]},{"id":"art-of-war_ch-4_p-3_s-1","passageId":"art-of-war_ch-4_p-3","order":1,"canonicalText":"見勝，不過眾人之所知，非善之善者也。","chunks":[["見勝，不過眾人之所知，非善之善者也。","zh-Hant"]]},{"id":"art-of-war_ch-4_p-3_s-2","passageId":"art-of-war_ch-4_p-3","order":2,"canonicalText":"戰勝，而天下曰善，非善之善者也。","chunks":[["戰勝，而天下曰善，非善之善者也。","zh-Hant"]]},{"id":"art-of-war_ch-4_p-3_s-3","passageId":"art-of-war_ch-4_p-3","order":3,"canonicalText":"故舉秋毫，不為多力；","chunks":[["故舉秋毫，不為多力；","zh-Hant"]]},{"id":"art-of-war_ch-4_p-3_s-4","passageId":"art-of-war_ch-4_p-3","order":4,"canonicalText":"見日月，不為明目；","chunks":[["見日月，不為明目；","zh-Hant"]]},{"id":"art-of-war_ch-4_p-3_s-5","passageId":"art-of-war_ch-4_p-3","order":5,"canonicalText":"聞雷霆，不為聰耳。","chunks":[["聞雷霆，不為聰耳。","zh-Hant"]]},{"id":"art-of-war_ch-4_p-3_s-6","passageId":"art-of-war_ch-4_p-3","order":6,"canonicalText":"古之善戰者，勝於易勝者；","chunks":[["古之善戰者，勝於易勝者；","zh-Hant"]]},{"id":"art-of-war_ch-4_p-3_s-7","passageId":"art-of-war_ch-4_p-3","order":7,"canonicalText":"故善戰者之勝也，無智名，無勇功。","chunks":[["故善戰者之勝也，無智名，無勇功。","zh-Hant"]]},{"id":"art-of-war_ch-4_p-3_s-8","passageId":"art-of-war_ch-4_p-3","order":8,"canonicalText":"故其戰勝不忒，不忒者，其措必勝，勝已敗者也。","chunks":[["故其戰勝不忒，不忒者，其措必勝，勝已敗者也。","zh-Hant"]]},{"id":"art-of-war_ch-4_p-3_s-9","passageId":"art-of-war_ch-4_p-3","order":9,"canonicalText":"故善戰者，立於不敗之地，而不失敵之敗也。","chunks":[["故善戰者，立於不敗之地，而不失敵之敗也。","zh-Hant"]]},{"id":"art-of-war_ch-4_p-3_s-10","passageId":"art-of-war_ch-4_p-3","order":10,"canonicalText":"是故勝兵先勝，而後求戰；","chunks":[["是故勝兵先勝，而後求戰；","zh-Hant"]]},{"id":"art-of-war_ch-4_p-3_s-11","passageId":"art-of-war_ch-4_p-3","order":11,"canonicalText":"敗兵先戰，而後求勝。","chunks":[["敗兵先戰，而後求勝。","zh-Hant"]]},{"id":"art-of-war_ch-4_p-4_s-1","passageId":"art-of-war_ch-4_p-4","order":1,"canonicalText":"善用兵者，修道而保法，故能為勝敗之政。","chunks":[["善用兵者，修道而保法，故能為勝敗之政。","zh-Hant"]]},{"id":"art-of-war_ch-4_p-4_s-2","passageId":"art-of-war_ch-4_p-4","order":2,"canonicalText":"兵法：「一曰度，二曰量，三曰數，四曰稱，五曰勝；","chunks":[["兵法：「一曰度，二曰量，三曰數，四曰稱，五曰勝；","zh-Hant"]]},{"id":"art-of-war_ch-4_p-4_s-3","passageId":"art-of-war_ch-4_p-4","order":3,"canonicalText":"地生度，度生量，量生數，數生稱，稱生勝。","chunks":[["地生度，度生量，量生數，數生稱，稱生勝。","zh-Hant"]]},{"id":"art-of-war_ch-4_p-4_s-4","passageId":"art-of-war_ch-4_p-4","order":4,"canonicalText":"」故勝兵若以鎰稱銖，敗兵若以銖稱鎰。","chunks":[["」故勝兵若以鎰稱銖，敗兵若以銖稱鎰。","zh-Hant"]]},{"id":"art-of-war_ch-4_p-4_s-5","passageId":"art-of-war_ch-4_p-4","order":5,"canonicalText":"勝者之戰民也，若決積水於千仞之谿，形也。","chunks":[["勝者之戰民也，若決積水於千仞之谿，形也。","zh-Hant"]]},{"id":"art-of-war_ch-5_p-1_s-1","passageId":"art-of-war_ch-5_p-1","order":1,"canonicalText":"孫子曰：凡治眾如治寡，分數是也。","chunks":[["孫子曰：凡治眾如治寡，分數是也。","zh-Hant"]]},{"id":"art-of-war_ch-5_p-1_s-2","passageId":"art-of-war_ch-5_p-1","order":2,"canonicalText":"鬥眾如鬥寡，形名是也。","chunks":[["鬥眾如鬥寡，形名是也。","zh-Hant"]]},{"id":"art-of-war_ch-5_p-1_s-3","passageId":"art-of-war_ch-5_p-1","order":3,"canonicalText":"三軍之眾，可使必受敵而無敗者，奇正是也。","chunks":[["三軍之眾，可使必受敵而無敗者，奇正是也。","zh-Hant"]]},{"id":"art-of-war_ch-5_p-1_s-4","passageId":"art-of-war_ch-5_p-1","order":4,"canonicalText":"兵之所加，如以碬投卵者，虛實是也。","chunks":[["兵之所加，如以碬投卵者，虛實是也。","zh-Hant"]]},{"id":"art-of-war_ch-5_p-2_s-1","passageId":"art-of-war_ch-5_p-2","order":1,"canonicalText":"凡戰者，以正合，以奇勝。","chunks":[["凡戰者，以正合，以奇勝。","zh-Hant"]]},{"id":"art-of-war_ch-5_p-2_s-2","passageId":"art-of-war_ch-5_p-2","order":2,"canonicalText":"故善出奇者，無窮如天地，不竭如江河，終而復始，日月是也；","chunks":[["故善出奇者，無窮如天地，不竭如江河，終而復始，日月是也；","zh-Hant"]]},{"id":"art-of-war_ch-5_p-2_s-3","passageId":"art-of-war_ch-5_p-2","order":3,"canonicalText":"死而復生，四時是也。","chunks":[["死而復生，四時是也。","zh-Hant"]]},{"id":"art-of-war_ch-5_p-2_s-4","passageId":"art-of-war_ch-5_p-2","order":4,"canonicalText":"聲不過五，五聲之變，不可勝聽也。","chunks":[["聲不過五，五聲之變，不可勝聽也。","zh-Hant"]]},{"id":"art-of-war_ch-5_p-2_s-5","passageId":"art-of-war_ch-5_p-2","order":5,"canonicalText":"色不過五，五色之變，不可勝觀也。","chunks":[["色不過五，五色之變，不可勝觀也。","zh-Hant"]]},{"id":"art-of-war_ch-5_p-2_s-6","passageId":"art-of-war_ch-5_p-2","order":6,"canonicalText":"味不過五，五味之變，不可勝嘗也。","chunks":[["味不過五，五味之變，不可勝嘗也。","zh-Hant"]]},{"id":"art-of-war_ch-5_p-2_s-7","passageId":"art-of-war_ch-5_p-2","order":7,"canonicalText":"戰勢不過奇正，奇正之變，不可勝窮也。","chunks":[["戰勢不過奇正，奇正之變，不可勝窮也。","zh-Hant"]]},{"id":"art-of-war_ch-5_p-2_s-8","passageId":"art-of-war_ch-5_p-2","order":8,"canonicalText":"奇正相生，如循環之無端，孰能窮之哉！","chunks":[["奇正相生，如循環之無端，孰能窮之哉！","zh-Hant"]]},{"id":"art-of-war_ch-5_p-3_s-1","passageId":"art-of-war_ch-5_p-3","order":1,"canonicalText":"激水之疾，至於漂石者，勢也。","chunks":[["激水之疾，至於漂石者，勢也。","zh-Hant"]]},{"id":"art-of-war_ch-5_p-3_s-2","passageId":"art-of-war_ch-5_p-3","order":2,"canonicalText":"鷙鳥之擊，至於毀折者，節也。","chunks":[["鷙鳥之擊，至於毀折者，節也。","zh-Hant"]]},{"id":"art-of-war_ch-5_p-3_s-3","passageId":"art-of-war_ch-5_p-3","order":3,"canonicalText":"是故善戰者，其勢險，其節短，勢如張弩，節如機發。","chunks":[["是故善戰者，其勢險，其節短，勢如張弩，節如機發。","zh-Hant"]]},{"id":"art-of-war_ch-5_p-4_s-1","passageId":"art-of-war_ch-5_p-4","order":1,"canonicalText":"紛紛紜紜，鬥亂，而不可亂也。","chunks":[["紛紛紜紜，鬥亂，而不可亂也。","zh-Hant"]]},{"id":"art-of-war_ch-5_p-4_s-2","passageId":"art-of-war_ch-5_p-4","order":2,"canonicalText":"渾渾沌沌，形圓，而不可敗也。","chunks":[["渾渾沌沌，形圓，而不可敗也。","zh-Hant"]]},{"id":"art-of-war_ch-5_p-4_s-3","passageId":"art-of-war_ch-5_p-4","order":3,"canonicalText":"亂生於治，怯生於勇，弱生於強。","chunks":[["亂生於治，怯生於勇，弱生於強。","zh-Hant"]]},{"id":"art-of-war_ch-5_p-4_s-4","passageId":"art-of-war_ch-5_p-4","order":4,"canonicalText":"治亂，數也。","chunks":[["治亂，數也。","zh-Hant"]]},{"id":"art-of-war_ch-5_p-4_s-5","passageId":"art-of-war_ch-5_p-4","order":5,"canonicalText":"勇怯，勢也。","chunks":[["勇怯，勢也。","zh-Hant"]]},{"id":"art-of-war_ch-5_p-4_s-6","passageId":"art-of-war_ch-5_p-4","order":6,"canonicalText":"強弱，形也。","chunks":[["強弱，形也。","zh-Hant"]]},{"id":"art-of-war_ch-5_p-4_s-7","passageId":"art-of-war_ch-5_p-4","order":7,"canonicalText":"故善動敵者，形之，敵必從之；","chunks":[["故善動敵者，形之，敵必從之；","zh-Hant"]]},{"id":"art-of-war_ch-5_p-4_s-8","passageId":"art-of-war_ch-5_p-4","order":8,"canonicalText":"予之，敵必取之；","chunks":[["予之，敵必取之；","zh-Hant"]]},{"id":"art-of-war_ch-5_p-4_s-9","passageId":"art-of-war_ch-5_p-4","order":9,"canonicalText":"以利動之，以實待之。","chunks":[["以利動之，以實待之。","zh-Hant"]]},{"id":"art-of-war_ch-5_p-5_s-1","passageId":"art-of-war_ch-5_p-5","order":1,"canonicalText":"故善戰者，求之於勢，不責於人，故能擇人任勢；","chunks":[["故善戰者，求之於勢，不責於人，故能擇人任勢；","zh-Hant"]]},{"id":"art-of-war_ch-5_p-5_s-2","passageId":"art-of-war_ch-5_p-5","order":2,"canonicalText":"任勢者，其戰人也，如轉木石，木石之性，安則靜，危則動，方則止，圓則行。","chunks":[["任勢者，其戰人也，如轉木石，木石之性，安則靜，危則動，方則止，圓則行。","zh-Hant"]]},{"id":"art-of-war_ch-5_p-5_s-3","passageId":"art-of-war_ch-5_p-5","order":3,"canonicalText":"故善戰人之勢，如轉圓石於千仞之山者，勢也。","chunks":[["故善戰人之勢，如轉圓石於千仞之山者，勢也。","zh-Hant"]]},{"id":"art-of-war_ch-6_p-1_s-1","passageId":"art-of-war_ch-6_p-1","order":1,"canonicalText":"孫子曰：凡先處戰地而待敵者佚，後處戰地而趨戰者勞。","chunks":[["孫子曰：凡先處戰地而待敵者佚，後處戰地而趨戰者勞。","zh-Hant"]]},{"id":"art-of-war_ch-6_p-1_s-2","passageId":"art-of-war_ch-6_p-1","order":2,"canonicalText":"故善戰者，致人而不致於人。","chunks":[["故善戰者，致人而不致於人。","zh-Hant"]]},{"id":"art-of-war_ch-6_p-1_s-3","passageId":"art-of-war_ch-6_p-1","order":3,"canonicalText":"能使敵人自至者，利之也；","chunks":[["能使敵人自至者，利之也；","zh-Hant"]]},{"id":"art-of-war_ch-6_p-1_s-4","passageId":"art-of-war_ch-6_p-1","order":4,"canonicalText":"能使敵不得至者，害之也。","chunks":[["能使敵不得至者，害之也。","zh-Hant"]]},{"id":"art-of-war_ch-6_p-1_s-5","passageId":"art-of-war_ch-6_p-1","order":5,"canonicalText":"故敵佚能勞之，飽能飢之，安能動之。","chunks":[["故敵佚能勞之，飽能飢之，安能動之。","zh-Hant"]]},{"id":"art-of-war_ch-6_p-2_s-1","passageId":"art-of-war_ch-6_p-2","order":1,"canonicalText":"出其所不趨，趨其所不意；","chunks":[["出其所不趨，趨其所不意；","zh-Hant"]]},{"id":"art-of-war_ch-6_p-2_s-2","passageId":"art-of-war_ch-6_p-2","order":2,"canonicalText":"行千里而不勞者，行於無人之地也；","chunks":[["行千里而不勞者，行於無人之地也；","zh-Hant"]]},{"id":"art-of-war_ch-6_p-2_s-3","passageId":"art-of-war_ch-6_p-2","order":3,"canonicalText":"攻而必取者，攻其所不守也；","chunks":[["攻而必取者，攻其所不守也；","zh-Hant"]]},{"id":"art-of-war_ch-6_p-2_s-4","passageId":"art-of-war_ch-6_p-2","order":4,"canonicalText":"守而必固者，守其所不攻也。","chunks":[["守而必固者，守其所不攻也。","zh-Hant"]]},{"id":"art-of-war_ch-6_p-2_s-5","passageId":"art-of-war_ch-6_p-2","order":5,"canonicalText":"故善攻者，敵不知其所守；","chunks":[["故善攻者，敵不知其所守；","zh-Hant"]]},{"id":"art-of-war_ch-6_p-2_s-6","passageId":"art-of-war_ch-6_p-2","order":6,"canonicalText":"善守者，敵不知其所攻。","chunks":[["善守者，敵不知其所攻。","zh-Hant"]]},{"id":"art-of-war_ch-6_p-2_s-7","passageId":"art-of-war_ch-6_p-2","order":7,"canonicalText":"微乎微乎！","chunks":[["微乎微乎！","zh-Hant"]]},{"id":"art-of-war_ch-6_p-2_s-8","passageId":"art-of-war_ch-6_p-2","order":8,"canonicalText":"至於無形；","chunks":[["至於無形；","zh-Hant"]]},{"id":"art-of-war_ch-6_p-2_s-9","passageId":"art-of-war_ch-6_p-2","order":9,"canonicalText":"神乎神乎！","chunks":[["神乎神乎！","zh-Hant"]]},{"id":"art-of-war_ch-6_p-2_s-10","passageId":"art-of-war_ch-6_p-2","order":10,"canonicalText":"至於無聲，故能為敵之司命。","chunks":[["至於無聲，故能為敵之司命。","zh-Hant"]]},{"id":"art-of-war_ch-6_p-2_s-11","passageId":"art-of-war_ch-6_p-2","order":11,"canonicalText":"進而不可禦者，衝其虛也；","chunks":[["進而不可禦者，衝其虛也；","zh-Hant"]]},{"id":"art-of-war_ch-6_p-2_s-12","passageId":"art-of-war_ch-6_p-2","order":12,"canonicalText":"退而不可追者，速而不可及也。","chunks":[["退而不可追者，速而不可及也。","zh-Hant"]]},{"id":"art-of-war_ch-6_p-2_s-13","passageId":"art-of-war_ch-6_p-2","order":13,"canonicalText":"故我欲戰，敵雖高壘深溝，不得不與我戰者，攻其所必救也；","chunks":[["故我欲戰，敵雖高壘深溝，不得不與我戰者，攻其所必救也；","zh-Hant"]]},{"id":"art-of-war_ch-6_p-2_s-14","passageId":"art-of-war_ch-6_p-2","order":14,"canonicalText":"我不欲戰，雖劃地而守之，敵不得與我戰者，乖其所之也。","chunks":[["我不欲戰，雖劃地而守之，敵不得與我戰者，乖其所之也。","zh-Hant"]]},{"id":"art-of-war_ch-6_p-3_s-1","passageId":"art-of-war_ch-6_p-3","order":1,"canonicalText":"故形人而我無形，則我專而敵分，我專為一，敵分為十，是以十攻其一也。","chunks":[["故形人而我無形，則我專而敵分，我專為一，敵分為十，是以十攻其一也。","zh-Hant"]]},{"id":"art-of-war_ch-6_p-3_s-2","passageId":"art-of-war_ch-6_p-3","order":2,"canonicalText":"則我眾而敵寡，能以眾擊寡，則我之所與戰者，約矣。","chunks":[["則我眾而敵寡，能以眾擊寡，則我之所與戰者，約矣。","zh-Hant"]]},{"id":"art-of-war_ch-6_p-4_s-1","passageId":"art-of-war_ch-6_p-4","order":1,"canonicalText":"吾所與戰之地不可知，不可知，則敵所備者多，敵所備者多，則我所與戰者寡矣。","chunks":[["吾所與戰之地不可知，不可知，則敵所備者多，敵所備者多，則我所與戰者寡矣。","zh-Hant"]]},{"id":"art-of-war_ch-6_p-4_s-2","passageId":"art-of-war_ch-6_p-4","order":2,"canonicalText":"故備前則後寡，備後則前寡，備左則右寡，備右則左寡，無所不備，則無所不寡。","chunks":[["故備前則後寡，備後則前寡，備左則右寡，備右則左寡，無所不備，則無所不寡。","zh-Hant"]]},{"id":"art-of-war_ch-6_p-4_s-3","passageId":"art-of-war_ch-6_p-4","order":3,"canonicalText":"寡者，備人者也；","chunks":[["寡者，備人者也；","zh-Hant"]]},{"id":"art-of-war_ch-6_p-4_s-4","passageId":"art-of-war_ch-6_p-4","order":4,"canonicalText":"眾者，使人備己者也。","chunks":[["眾者，使人備己者也。","zh-Hant"]]},{"id":"art-of-war_ch-6_p-5_s-1","passageId":"art-of-war_ch-6_p-5","order":1,"canonicalText":"故知戰之地，知戰之日，則可千里而會戰。","chunks":[["故知戰之地，知戰之日，則可千里而會戰。","zh-Hant"]]},{"id":"art-of-war_ch-6_p-5_s-2","passageId":"art-of-war_ch-6_p-5","order":2,"canonicalText":"不知戰地，不知戰日，則左不能救右，右不能救左，前不能救後，後不能救前，而況遠者數十里，近者數裏乎？","chunks":[["不知戰地，不知戰日，則左不能救右，右不能救左，前不能救後，後不能救前，而況遠者數十里，近者數裏乎？","zh-Hant"]]},{"id":"art-of-war_ch-6_p-5_s-3","passageId":"art-of-war_ch-6_p-5","order":3,"canonicalText":"以吾度之，越人之兵雖多，亦奚益於勝哉？","chunks":[["以吾度之，越人之兵雖多，亦奚益於勝哉？","zh-Hant"]]},{"id":"art-of-war_ch-6_p-5_s-4","passageId":"art-of-war_ch-6_p-5","order":4,"canonicalText":"故曰：勝可為也，敵雖眾，可使無鬥。","chunks":[["故曰：勝可為也，敵雖眾，可使無鬥。","zh-Hant"]]},{"id":"art-of-war_ch-6_p-6_s-1","passageId":"art-of-war_ch-6_p-6","order":1,"canonicalText":"故策之而知得失之計，作之而知動靜之理，形之而知死生之地，角之而知有餘不足之處。","chunks":[["故策之而知得失之計，作之而知動靜之理，形之而知死生之地，角之而知有餘不足之處。","zh-Hant"]]},{"id":"art-of-war_ch-6_p-6_s-2","passageId":"art-of-war_ch-6_p-6","order":2,"canonicalText":"故形兵之極，至於無形；","chunks":[["故形兵之極，至於無形；","zh-Hant"]]},{"id":"art-of-war_ch-6_p-6_s-3","passageId":"art-of-war_ch-6_p-6","order":3,"canonicalText":"無形，則深間不能窺，智者不能謀。","chunks":[["無形，則深間不能窺，智者不能謀。","zh-Hant"]]},{"id":"art-of-war_ch-6_p-6_s-4","passageId":"art-of-war_ch-6_p-6","order":4,"canonicalText":"因形而措勝於眾，眾不能知，人皆知我所以勝之形，而莫知吾所以制勝之形；","chunks":[["因形而措勝於眾，眾不能知，人皆知我所以勝之形，而莫知吾所以制勝之形；","zh-Hant"]]},{"id":"art-of-war_ch-6_p-6_s-5","passageId":"art-of-war_ch-6_p-6","order":5,"canonicalText":"故其戰勝不復，而應形於無窮。","chunks":[["故其戰勝不復，而應形於無窮。","zh-Hant"]]},{"id":"art-of-war_ch-6_p-7_s-1","passageId":"art-of-war_ch-6_p-7","order":1,"canonicalText":"夫兵形象水，水之形，避高而趨下：兵之形，避實而擊虛；","chunks":[["夫兵形象水，水之形，避高而趨下：兵之形，避實而擊虛；","zh-Hant"]]},{"id":"art-of-war_ch-6_p-7_s-2","passageId":"art-of-war_ch-6_p-7","order":2,"canonicalText":"水因地而制流，兵因敵而制勝。","chunks":[["水因地而制流，兵因敵而制勝。","zh-Hant"]]},{"id":"art-of-war_ch-6_p-7_s-3","passageId":"art-of-war_ch-6_p-7","order":3,"canonicalText":"故兵無常勢，水無常形；","chunks":[["故兵無常勢，水無常形；","zh-Hant"]]},{"id":"art-of-war_ch-6_p-7_s-4","passageId":"art-of-war_ch-6_p-7","order":4,"canonicalText":"能因敵變化而取勝，謂之神。","chunks":[["能因敵變化而取勝，謂之神。","zh-Hant"]]},{"id":"art-of-war_ch-6_p-7_s-5","passageId":"art-of-war_ch-6_p-7","order":5,"canonicalText":"故五行無常勝，四時無常位，日有短長，月有死生。","chunks":[["故五行無常勝，四時無常位，日有短長，月有死生。","zh-Hant"]]},{"id":"art-of-war_ch-7_p-1_s-1","passageId":"art-of-war_ch-7_p-1","order":1,"canonicalText":"孫子曰：凡用兵之法，將受命於君，合軍聚眾，交和而舍，莫難於軍爭。","chunks":[["孫子曰：凡用兵之法，將受命於君，合軍聚眾，交和而舍，莫難於軍爭。","zh-Hant"]]},{"id":"art-of-war_ch-7_p-1_s-2","passageId":"art-of-war_ch-7_p-1","order":2,"canonicalText":"軍爭之難者，以迂為直，以患為利。","chunks":[["軍爭之難者，以迂為直，以患為利。","zh-Hant"]]},{"id":"art-of-war_ch-7_p-1_s-3","passageId":"art-of-war_ch-7_p-1","order":3,"canonicalText":"故迂其途，而誘之以利，後人發，先人至，此知迂直之計者也。","chunks":[["故迂其途，而誘之以利，後人發，先人至，此知迂直之計者也。","zh-Hant"]]},{"id":"art-of-war_ch-7_p-1_s-4","passageId":"art-of-war_ch-7_p-1","order":4,"canonicalText":"故軍爭為利，軍爭為危。","chunks":[["故軍爭為利，軍爭為危。","zh-Hant"]]},{"id":"art-of-war_ch-7_p-2_s-1","passageId":"art-of-war_ch-7_p-2","order":1,"canonicalText":"舉軍而爭利，則不及；","chunks":[["舉軍而爭利，則不及；","zh-Hant"]]},{"id":"art-of-war_ch-7_p-2_s-2","passageId":"art-of-war_ch-7_p-2","order":2,"canonicalText":"委軍而爭利，則輜重捐。","chunks":[["委軍而爭利，則輜重捐。","zh-Hant"]]},{"id":"art-of-war_ch-7_p-2_s-3","passageId":"art-of-war_ch-7_p-2","order":3,"canonicalText":"是故卷甲而趨，日夜不處，倍道兼行，百里而爭利，則擒三將軍，勁者先，疲者後，其法十一而至；","chunks":[["是故卷甲而趨，日夜不處，倍道兼行，百里而爭利，則擒三將軍，勁者先，疲者後，其法十一而至；","zh-Hant"]]},{"id":"art-of-war_ch-7_p-2_s-4","passageId":"art-of-war_ch-7_p-2","order":4,"canonicalText":"五十里而爭利，則蹶上將軍，其法半至；","chunks":[["五十里而爭利，則蹶上將軍，其法半至；","zh-Hant"]]},{"id":"art-of-war_ch-7_p-2_s-5","passageId":"art-of-war_ch-7_p-2","order":5,"canonicalText":"卅里而爭利，則三分之二至。","chunks":[["卅里而爭利，則三分之二至。","zh-Hant"]]},{"id":"art-of-war_ch-7_p-2_s-6","passageId":"art-of-war_ch-7_p-2","order":6,"canonicalText":"是故軍無輜重則亡，無糧食則亡，無委積則亡。","chunks":[["是故軍無輜重則亡，無糧食則亡，無委積則亡。","zh-Hant"]]},{"id":"art-of-war_ch-7_p-2_s-7","passageId":"art-of-war_ch-7_p-2","order":7,"canonicalText":"故不知諸侯之謀者，不能豫交；","chunks":[["故不知諸侯之謀者，不能豫交；","zh-Hant"]]},{"id":"art-of-war_ch-7_p-2_s-8","passageId":"art-of-war_ch-7_p-2","order":8,"canonicalText":"不知山林、險阻、沮澤之形者，不能行軍，不能鄉導者，不能得地利。","chunks":[["不知山林、險阻、沮澤之形者，不能行軍，不能鄉導者，不能得地利。","zh-Hant"]]},{"id":"art-of-war_ch-7_p-3_s-1","passageId":"art-of-war_ch-7_p-3","order":1,"canonicalText":"故兵以詐立，以利動，以分合為變者也，故其疾如風，其徐如林，侵掠如火，不動如山，難知如陰，動如雷霆。","chunks":[["故兵以詐立，以利動，以分合為變者也，故其疾如風，其徐如林，侵掠如火，不動如山，難知如陰，動如雷霆。","zh-Hant"]]},{"id":"art-of-war_ch-7_p-3_s-2","passageId":"art-of-war_ch-7_p-3","order":2,"canonicalText":"掠鄉分眾，廓地分利，懸權而動，先知迂直之計者勝，此軍爭之法也。","chunks":[["掠鄉分眾，廓地分利，懸權而動，先知迂直之計者勝，此軍爭之法也。","zh-Hant"]]},{"id":"art-of-war_ch-7_p-4_s-1","passageId":"art-of-war_ch-7_p-4","order":1,"canonicalText":"軍政曰：「言不相聞，故為金鼓；","chunks":[["軍政曰：「言不相聞，故為金鼓；","zh-Hant"]]},{"id":"art-of-war_ch-7_p-4_s-2","passageId":"art-of-war_ch-7_p-4","order":2,"canonicalText":"視不相見，故為旌旗。","chunks":[["視不相見，故為旌旗。","zh-Hant"]]},{"id":"art-of-war_ch-7_p-4_s-3","passageId":"art-of-war_ch-7_p-4","order":3,"canonicalText":"」夫金鼓旌旗者，所以一人之耳目也；","chunks":[["」夫金鼓旌旗者，所以一人之耳目也；","zh-Hant"]]},{"id":"art-of-war_ch-7_p-4_s-4","passageId":"art-of-war_ch-7_p-4","order":4,"canonicalText":"人既專一，則勇者不得獨進，怯者不得獨退，此用眾之法也。","chunks":[["人既專一，則勇者不得獨進，怯者不得獨退，此用眾之法也。","zh-Hant"]]},{"id":"art-of-war_ch-7_p-4_s-5","passageId":"art-of-war_ch-7_p-4","order":5,"canonicalText":"故夜戰多火鼓，晝戰多旌旗，所以變人之耳目也。","chunks":[["故夜戰多火鼓，晝戰多旌旗，所以變人之耳目也。","zh-Hant"]]},{"id":"art-of-war_ch-7_p-5_s-1","passageId":"art-of-war_ch-7_p-5","order":1,"canonicalText":"故三軍可奪氣，將軍可奪心。","chunks":[["故三軍可奪氣，將軍可奪心。","zh-Hant"]]},{"id":"art-of-war_ch-7_p-5_s-2","passageId":"art-of-war_ch-7_p-5","order":2,"canonicalText":"是故朝氣銳，晝氣惰，暮氣歸；","chunks":[["是故朝氣銳，晝氣惰，暮氣歸；","zh-Hant"]]},{"id":"art-of-war_ch-7_p-5_s-3","passageId":"art-of-war_ch-7_p-5","order":3,"canonicalText":"故善用兵者，避其銳氣，擊其惰歸，此治氣者也。","chunks":[["故善用兵者，避其銳氣，擊其惰歸，此治氣者也。","zh-Hant"]]},{"id":"art-of-war_ch-7_p-5_s-4","passageId":"art-of-war_ch-7_p-5","order":4,"canonicalText":"以治待亂，以靜待譁，此治心者也。","chunks":[["以治待亂，以靜待譁，此治心者也。","zh-Hant"]]},{"id":"art-of-war_ch-7_p-5_s-5","passageId":"art-of-war_ch-7_p-5","order":5,"canonicalText":"以近待遠，以佚待勞，以飽待飢，此治力者也。","chunks":[["以近待遠，以佚待勞，以飽待飢，此治力者也。","zh-Hant"]]},{"id":"art-of-war_ch-7_p-6_s-1","passageId":"art-of-war_ch-7_p-6","order":1,"canonicalText":"無邀正正之旗，勿擊堂堂之陣，此治變者也；","chunks":[["無邀正正之旗，勿擊堂堂之陣，此治變者也；","zh-Hant"]]},{"id":"art-of-war_ch-7_p-6_s-2","passageId":"art-of-war_ch-7_p-6","order":2,"canonicalText":"故用兵之法，高陵勿向，背邱勿逆，佯北勿從，銳卒勿攻，餌兵勿食，歸師勿遏，圍師必闕，窮寇勿迫，此用兵之法也。","chunks":[["故用兵之法，高陵勿向，背邱勿逆，佯北勿從，銳卒勿攻，餌兵勿食，歸師勿遏，圍師必闕，窮寇勿迫，此用兵之法也。","zh-Hant"]]},{"id":"art-of-war_ch-8_p-1_s-1","passageId":"art-of-war_ch-8_p-1","order":1,"canonicalText":"孫子曰：凡用兵之法，將受命於君，合軍聚眾；","chunks":[["孫子曰：凡用兵之法，將受命於君，合軍聚眾；","zh-Hant"]]},{"id":"art-of-war_ch-8_p-1_s-2","passageId":"art-of-war_ch-8_p-1","order":2,"canonicalText":"圮地無舍，衢地合交，絕地無留，圍地則謀，死地則戰，途有所不由，軍有所不擊，城有所不攻，地有所不爭，君命有所不受。","chunks":[["圮地無舍，衢地合交，絕地無留，圍地則謀，死地則戰，途有所不由，軍有所不擊，城有所不攻，地有所不爭，君命有所不受。","zh-Hant"]]},{"id":"art-of-war_ch-8_p-1_s-3","passageId":"art-of-war_ch-8_p-1","order":3,"canonicalText":"故將通於九變之利者，知用兵矣。","chunks":[["故將通於九變之利者，知用兵矣。","zh-Hant"]]},{"id":"art-of-war_ch-8_p-1_s-4","passageId":"art-of-war_ch-8_p-1","order":4,"canonicalText":"將不通於九變之利者，雖知地形，不能得地之利矣。","chunks":[["將不通於九變之利者，雖知地形，不能得地之利矣。","zh-Hant"]]},{"id":"art-of-war_ch-8_p-1_s-5","passageId":"art-of-war_ch-8_p-1","order":5,"canonicalText":"治兵不知九變之術，雖知地利，不能得人之用矣。","chunks":[["治兵不知九變之術，雖知地利，不能得人之用矣。","zh-Hant"]]},{"id":"art-of-war_ch-8_p-2_s-1","passageId":"art-of-war_ch-8_p-2","order":1,"canonicalText":"是故智者之慮，必雜於利害，雜於利而務可信也，雜於害而患可解也。","chunks":[["是故智者之慮，必雜於利害，雜於利而務可信也，雜於害而患可解也。","zh-Hant"]]},{"id":"art-of-war_ch-8_p-2_s-2","passageId":"art-of-war_ch-8_p-2","order":2,"canonicalText":"是故屈諸侯者以害，役諸侯者以業，趨諸侯者以利。","chunks":[["是故屈諸侯者以害，役諸侯者以業，趨諸侯者以利。","zh-Hant"]]},{"id":"art-of-war_ch-8_p-3_s-1","passageId":"art-of-war_ch-8_p-3","order":1,"canonicalText":"故用兵之法，無恃其不來，恃吾有以待之；","chunks":[["故用兵之法，無恃其不來，恃吾有以待之；","zh-Hant"]]},{"id":"art-of-war_ch-8_p-3_s-2","passageId":"art-of-war_ch-8_p-3","order":2,"canonicalText":"無恃其不攻，恃吾有所不可攻也。","chunks":[["無恃其不攻，恃吾有所不可攻也。","zh-Hant"]]},{"id":"art-of-war_ch-8_p-4_s-1","passageId":"art-of-war_ch-8_p-4","order":1,"canonicalText":"故將有五危：必死可殺，必生可虜，忿速可侮，廉潔可辱，愛民可煩；","chunks":[["故將有五危：必死可殺，必生可虜，忿速可侮，廉潔可辱，愛民可煩；","zh-Hant"]]},{"id":"art-of-war_ch-8_p-4_s-2","passageId":"art-of-war_ch-8_p-4","order":2,"canonicalText":"凡此五危，將之過也，用兵之災也。","chunks":[["凡此五危，將之過也，用兵之災也。","zh-Hant"]]},{"id":"art-of-war_ch-8_p-4_s-3","passageId":"art-of-war_ch-8_p-4","order":3,"canonicalText":"覆軍殺將，必以五危，不可不察也。","chunks":[["覆軍殺將，必以五危，不可不察也。","zh-Hant"]]},{"id":"art-of-war_ch-9_p-1_s-1","passageId":"art-of-war_ch-9_p-1","order":1,"canonicalText":"孫子曰：凡處軍相敵：絕山依谷，視生處高，戰隆無登，此處山之軍也。","chunks":[["孫子曰：凡處軍相敵：絕山依谷，視生處高，戰隆無登，此處山之軍也。","zh-Hant"]]},{"id":"art-of-war_ch-9_p-1_s-2","passageId":"art-of-war_ch-9_p-1","order":2,"canonicalText":"絕水必遠水，客絕水而來，勿迎於水內，令半濟而擊之利。","chunks":[["絕水必遠水，客絕水而來，勿迎於水內，令半濟而擊之利。","zh-Hant"]]},{"id":"art-of-war_ch-9_p-1_s-3","passageId":"art-of-war_ch-9_p-1","order":3,"canonicalText":"欲戰者，無附於水而迎客，視生處高，無迎水流，此處水上之軍也。","chunks":[["欲戰者，無附於水而迎客，視生處高，無迎水流，此處水上之軍也。","zh-Hant"]]},{"id":"art-of-war_ch-9_p-1_s-4","passageId":"art-of-war_ch-9_p-1","order":4,"canonicalText":"絕斥澤，惟亟去勿留，若交軍於斥澤之中，必依水草，而背眾樹，此處斥澤之軍也。","chunks":[["絕斥澤，惟亟去勿留，若交軍於斥澤之中，必依水草，而背眾樹，此處斥澤之軍也。","zh-Hant"]]},{"id":"art-of-war_ch-9_p-1_s-5","passageId":"art-of-war_ch-9_p-1","order":5,"canonicalText":"平陸處易，右背高，前死後生，此處平陸之軍也。","chunks":[["平陸處易，右背高，前死後生，此處平陸之軍也。","zh-Hant"]]},{"id":"art-of-war_ch-9_p-1_s-6","passageId":"art-of-war_ch-9_p-1","order":6,"canonicalText":"凡此四軍之利，黃帝之所以勝四帝也。","chunks":[["凡此四軍之利，黃帝之所以勝四帝也。","zh-Hant"]]},{"id":"art-of-war_ch-9_p-2_s-1","passageId":"art-of-war_ch-9_p-2","order":1,"canonicalText":"凡軍好高而惡下，貴陽而賤陰，養生處實，軍無百疾，是謂必勝。","chunks":[["凡軍好高而惡下，貴陽而賤陰，養生處實，軍無百疾，是謂必勝。","zh-Hant"]]},{"id":"art-of-war_ch-9_p-2_s-2","passageId":"art-of-war_ch-9_p-2","order":2,"canonicalText":"邱陵隄防，必處其陽，而右背之，此兵之利，地之助也。","chunks":[["邱陵隄防，必處其陽，而右背之，此兵之利，地之助也。","zh-Hant"]]},{"id":"art-of-war_ch-9_p-2_s-3","passageId":"art-of-war_ch-9_p-2","order":3,"canonicalText":"上雨水沫至，欲涉者，待其定也。","chunks":[["上雨水沫至，欲涉者，待其定也。","zh-Hant"]]},{"id":"art-of-war_ch-9_p-2_s-4","passageId":"art-of-war_ch-9_p-2","order":4,"canonicalText":"凡地有絕澗、天井、天牢、天羅、天陷、天隙，必亟去之，勿近也；","chunks":[["凡地有絕澗、天井、天牢、天羅、天陷、天隙，必亟去之，勿近也；","zh-Hant"]]},{"id":"art-of-war_ch-9_p-2_s-5","passageId":"art-of-war_ch-9_p-2","order":5,"canonicalText":"吾遠之，敵近之；","chunks":[["吾遠之，敵近之；","zh-Hant"]]},{"id":"art-of-war_ch-9_p-2_s-6","passageId":"art-of-war_ch-9_p-2","order":6,"canonicalText":"吾迎之，敵背之。","chunks":[["吾迎之，敵背之。","zh-Hant"]]},{"id":"art-of-war_ch-9_p-2_s-7","passageId":"art-of-war_ch-9_p-2","order":7,"canonicalText":"軍旁有險阻、潢井、蒹葭、林木、翳薈者，必謹覆索之，此伏姦之所也。","chunks":[["軍旁有險阻、潢井、蒹葭、林木、翳薈者，必謹覆索之，此伏姦之所也。","zh-Hant"]]},{"id":"art-of-war_ch-9_p-3_s-1","passageId":"art-of-war_ch-9_p-3","order":1,"canonicalText":"敵近而靜者，恃其險也。","chunks":[["敵近而靜者，恃其險也。","zh-Hant"]]},{"id":"art-of-war_ch-9_p-3_s-2","passageId":"art-of-war_ch-9_p-3","order":2,"canonicalText":"遠而挑戰者，欲人之進也。","chunks":[["遠而挑戰者，欲人之進也。","zh-Hant"]]},{"id":"art-of-war_ch-9_p-3_s-3","passageId":"art-of-war_ch-9_p-3","order":3,"canonicalText":"其所居易者，利也。","chunks":[["其所居易者，利也。","zh-Hant"]]},{"id":"art-of-war_ch-9_p-3_s-4","passageId":"art-of-war_ch-9_p-3","order":4,"canonicalText":"眾樹動者，來也。","chunks":[["眾樹動者，來也。","zh-Hant"]]},{"id":"art-of-war_ch-9_p-3_s-5","passageId":"art-of-war_ch-9_p-3","order":5,"canonicalText":"眾草多障者，疑也。","chunks":[["眾草多障者，疑也。","zh-Hant"]]},{"id":"art-of-war_ch-9_p-3_s-6","passageId":"art-of-war_ch-9_p-3","order":6,"canonicalText":"鳥起者，伏也。","chunks":[["鳥起者，伏也。","zh-Hant"]]},{"id":"art-of-war_ch-9_p-3_s-7","passageId":"art-of-war_ch-9_p-3","order":7,"canonicalText":"獸駭者，覆也。","chunks":[["獸駭者，覆也。","zh-Hant"]]},{"id":"art-of-war_ch-9_p-3_s-8","passageId":"art-of-war_ch-9_p-3","order":8,"canonicalText":"塵：高而銳者，車來也；","chunks":[["塵：高而銳者，車來也；","zh-Hant"]]},{"id":"art-of-war_ch-9_p-3_s-9","passageId":"art-of-war_ch-9_p-3","order":9,"canonicalText":"卑而廣者，徒來也；","chunks":[["卑而廣者，徒來也；","zh-Hant"]]},{"id":"art-of-war_ch-9_p-3_s-10","passageId":"art-of-war_ch-9_p-3","order":10,"canonicalText":"散而條違者，樵採也；","chunks":[["散而條違者，樵採也；","zh-Hant"]]},{"id":"art-of-war_ch-9_p-3_s-11","passageId":"art-of-war_ch-9_p-3","order":11,"canonicalText":"少而往來者，營軍也。","chunks":[["少而往來者，營軍也。","zh-Hant"]]},{"id":"art-of-war_ch-9_p-3_s-12","passageId":"art-of-war_ch-9_p-3","order":12,"canonicalText":"辭卑而益備者，進也。","chunks":[["辭卑而益備者，進也。","zh-Hant"]]},{"id":"art-of-war_ch-9_p-3_s-13","passageId":"art-of-war_ch-9_p-3","order":13,"canonicalText":"辭強而進驅者，退也。","chunks":[["辭強而進驅者，退也。","zh-Hant"]]},{"id":"art-of-war_ch-9_p-3_s-14","passageId":"art-of-war_ch-9_p-3","order":14,"canonicalText":"輕車先出其側者，陣也。","chunks":[["輕車先出其側者，陣也。","zh-Hant"]]},{"id":"art-of-war_ch-9_p-3_s-15","passageId":"art-of-war_ch-9_p-3","order":15,"canonicalText":"無約而請和者，謀也。","chunks":[["無約而請和者，謀也。","zh-Hant"]]},{"id":"art-of-war_ch-9_p-3_s-16","passageId":"art-of-war_ch-9_p-3","order":16,"canonicalText":"奔走而陳兵者，期也。","chunks":[["奔走而陳兵者，期也。","zh-Hant"]]},{"id":"art-of-war_ch-9_p-3_s-17","passageId":"art-of-war_ch-9_p-3","order":17,"canonicalText":"半進半退者，誘也。","chunks":[["半進半退者，誘也。","zh-Hant"]]},{"id":"art-of-war_ch-9_p-3_s-18","passageId":"art-of-war_ch-9_p-3","order":18,"canonicalText":"仗而立者，飢也。","chunks":[["仗而立者，飢也。","zh-Hant"]]},{"id":"art-of-war_ch-9_p-3_s-19","passageId":"art-of-war_ch-9_p-3","order":19,"canonicalText":"汲而先飲者，渴也。","chunks":[["汲而先飲者，渴也。","zh-Hant"]]},{"id":"art-of-war_ch-9_p-3_s-20","passageId":"art-of-war_ch-9_p-3","order":20,"canonicalText":"見利而不進者，勞也。","chunks":[["見利而不進者，勞也。","zh-Hant"]]},{"id":"art-of-war_ch-9_p-3_s-21","passageId":"art-of-war_ch-9_p-3","order":21,"canonicalText":"鳥集者，虛也。","chunks":[["鳥集者，虛也。","zh-Hant"]]},{"id":"art-of-war_ch-9_p-3_s-22","passageId":"art-of-war_ch-9_p-3","order":22,"canonicalText":"夜呼者，恐也。","chunks":[["夜呼者，恐也。","zh-Hant"]]},{"id":"art-of-war_ch-9_p-3_s-23","passageId":"art-of-war_ch-9_p-3","order":23,"canonicalText":"軍擾者，將不重也。","chunks":[["軍擾者，將不重也。","zh-Hant"]]},{"id":"art-of-war_ch-9_p-3_s-24","passageId":"art-of-war_ch-9_p-3","order":24,"canonicalText":"旌旗動者，亂也。","chunks":[["旌旗動者，亂也。","zh-Hant"]]},{"id":"art-of-war_ch-9_p-3_s-25","passageId":"art-of-war_ch-9_p-3","order":25,"canonicalText":"吏怒者，倦也。","chunks":[["吏怒者，倦也。","zh-Hant"]]},{"id":"art-of-war_ch-9_p-3_s-26","passageId":"art-of-war_ch-9_p-3","order":26,"canonicalText":"殺馬肉食者，軍無糧也。","chunks":[["殺馬肉食者，軍無糧也。","zh-Hant"]]},{"id":"art-of-war_ch-9_p-3_s-27","passageId":"art-of-war_ch-9_p-3","order":27,"canonicalText":"懸缶不返其舍者，窮寇也。","chunks":[["懸缶不返其舍者，窮寇也。","zh-Hant"]]},{"id":"art-of-war_ch-9_p-3_s-28","passageId":"art-of-war_ch-9_p-3","order":28,"canonicalText":"諄諄翕翕，徐與人言者，失眾也。","chunks":[["諄諄翕翕，徐與人言者，失眾也。","zh-Hant"]]},{"id":"art-of-war_ch-9_p-3_s-29","passageId":"art-of-war_ch-9_p-3","order":29,"canonicalText":"數賞者，窘也。","chunks":[["數賞者，窘也。","zh-Hant"]]},{"id":"art-of-war_ch-9_p-3_s-30","passageId":"art-of-war_ch-9_p-3","order":30,"canonicalText":"數罰者，困也。","chunks":[["數罰者，困也。","zh-Hant"]]},{"id":"art-of-war_ch-9_p-3_s-31","passageId":"art-of-war_ch-9_p-3","order":31,"canonicalText":"先暴而後畏其眾者，不精之至也。","chunks":[["先暴而後畏其眾者，不精之至也。","zh-Hant"]]},{"id":"art-of-war_ch-9_p-3_s-32","passageId":"art-of-war_ch-9_p-3","order":32,"canonicalText":"來委謝者，欲休息也。","chunks":[["來委謝者，欲休息也。","zh-Hant"]]},{"id":"art-of-war_ch-9_p-3_s-33","passageId":"art-of-war_ch-9_p-3","order":33,"canonicalText":"兵怒而相迎，久而不合，又不相去，必謹察之。","chunks":[["兵怒而相迎，久而不合，又不相去，必謹察之。","zh-Hant"]]},{"id":"art-of-war_ch-9_p-4_s-1","passageId":"art-of-war_ch-9_p-4","order":1,"canonicalText":"兵非貴益多，惟無武進，足以併力料敵取人而已。","chunks":[["兵非貴益多，惟無武進，足以併力料敵取人而已。","zh-Hant"]]},{"id":"art-of-war_ch-9_p-4_s-2","passageId":"art-of-war_ch-9_p-4","order":2,"canonicalText":"夫惟無慮而易敵者，必擒於人。","chunks":[["夫惟無慮而易敵者，必擒於人。","zh-Hant"]]},{"id":"art-of-war_ch-9_p-5_s-1","passageId":"art-of-war_ch-9_p-5","order":1,"canonicalText":"卒未親附而罰之，則不服，不服則難用。","chunks":[["卒未親附而罰之，則不服，不服則難用。","zh-Hant"]]},{"id":"art-of-war_ch-9_p-5_s-2","passageId":"art-of-war_ch-9_p-5","order":2,"canonicalText":"卒已親附而罰不行，則不可用。","chunks":[["卒已親附而罰不行，則不可用。","zh-Hant"]]},{"id":"art-of-war_ch-9_p-5_s-3","passageId":"art-of-war_ch-9_p-5","order":3,"canonicalText":"故令之以文，齊之以武，是謂必取。","chunks":[["故令之以文，齊之以武，是謂必取。","zh-Hant"]]},{"id":"art-of-war_ch-9_p-5_s-4","passageId":"art-of-war_ch-9_p-5","order":4,"canonicalText":"令素行以教其民，則民服；","chunks":[["令素行以教其民，則民服；","zh-Hant"]]},{"id":"art-of-war_ch-9_p-5_s-5","passageId":"art-of-war_ch-9_p-5","order":5,"canonicalText":"令不素行以教其民，則民不服；","chunks":[["令不素行以教其民，則民不服；","zh-Hant"]]},{"id":"art-of-war_ch-9_p-5_s-6","passageId":"art-of-war_ch-9_p-5","order":6,"canonicalText":"令素行，與眾相得也。","chunks":[["令素行，與眾相得也。","zh-Hant"]]},{"id":"art-of-war_ch-10_p-1_s-1","passageId":"art-of-war_ch-10_p-1","order":1,"canonicalText":"孫子曰：地形有通者，有掛者，有支者，有隘者，有險者，有遠者。","chunks":[["孫子曰：地形有通者，有掛者，有支者，有隘者，有險者，有遠者。","zh-Hant"]]},{"id":"art-of-war_ch-10_p-1_s-2","passageId":"art-of-war_ch-10_p-1","order":2,"canonicalText":"我可以往，彼可以來，曰通；","chunks":[["我可以往，彼可以來，曰通；","zh-Hant"]]},{"id":"art-of-war_ch-10_p-1_s-3","passageId":"art-of-war_ch-10_p-1","order":3,"canonicalText":"通形者，先居高陽，利糧道以戰，則利。","chunks":[["通形者，先居高陽，利糧道以戰，則利。","zh-Hant"]]},{"id":"art-of-war_ch-10_p-1_s-4","passageId":"art-of-war_ch-10_p-1","order":4,"canonicalText":"可以往，難以返，曰掛；","chunks":[["可以往，難以返，曰掛；","zh-Hant"]]},{"id":"art-of-war_ch-10_p-1_s-5","passageId":"art-of-war_ch-10_p-1","order":5,"canonicalText":"掛形者，敵無備，出而勝之，敵若有備，出而不勝，難以返，不利。","chunks":[["掛形者，敵無備，出而勝之，敵若有備，出而不勝，難以返，不利。","zh-Hant"]]},{"id":"art-of-war_ch-10_p-1_s-6","passageId":"art-of-war_ch-10_p-1","order":6,"canonicalText":"我出而不利，彼出而不利，曰支；","chunks":[["我出而不利，彼出而不利，曰支；","zh-Hant"]]},{"id":"art-of-war_ch-10_p-1_s-7","passageId":"art-of-war_ch-10_p-1","order":7,"canonicalText":"支形者，敵雖利我，我無出也；","chunks":[["支形者，敵雖利我，我無出也；","zh-Hant"]]},{"id":"art-of-war_ch-10_p-1_s-8","passageId":"art-of-war_ch-10_p-1","order":8,"canonicalText":"引而去之，令敵半出而擊之，利。","chunks":[["引而去之，令敵半出而擊之，利。","zh-Hant"]]},{"id":"art-of-war_ch-10_p-1_s-9","passageId":"art-of-war_ch-10_p-1","order":9,"canonicalText":"隘形者，我先居之，必盈以待敵；","chunks":[["隘形者，我先居之，必盈以待敵；","zh-Hant"]]},{"id":"art-of-war_ch-10_p-1_s-10","passageId":"art-of-war_ch-10_p-1","order":10,"canonicalText":"若敵先居之，盈而勿從，不盈而從之。","chunks":[["若敵先居之，盈而勿從，不盈而從之。","zh-Hant"]]},{"id":"art-of-war_ch-10_p-1_s-11","passageId":"art-of-war_ch-10_p-1","order":11,"canonicalText":"險形者，我先居之，必居高陽以待敵；","chunks":[["險形者，我先居之，必居高陽以待敵；","zh-Hant"]]},{"id":"art-of-war_ch-10_p-1_s-12","passageId":"art-of-war_ch-10_p-1","order":12,"canonicalText":"若敵先居之，引而去之，勿從也。","chunks":[["若敵先居之，引而去之，勿從也。","zh-Hant"]]},{"id":"art-of-war_ch-10_p-1_s-13","passageId":"art-of-war_ch-10_p-1","order":13,"canonicalText":"遠形者，勢均，難以挑戰，戰而不利。","chunks":[["遠形者，勢均，難以挑戰，戰而不利。","zh-Hant"]]},{"id":"art-of-war_ch-10_p-1_s-14","passageId":"art-of-war_ch-10_p-1","order":14,"canonicalText":"凡此六者，地之道也，將之至任，不可不察也。","chunks":[["凡此六者，地之道也，將之至任，不可不察也。","zh-Hant"]]},{"id":"art-of-war_ch-10_p-2_s-1","passageId":"art-of-war_ch-10_p-2","order":1,"canonicalText":"故兵有走者，有弛者，有陷者，有崩者，有亂者，有北者；","chunks":[["故兵有走者，有弛者，有陷者，有崩者，有亂者，有北者；","zh-Hant"]]},{"id":"art-of-war_ch-10_p-2_s-2","passageId":"art-of-war_ch-10_p-2","order":2,"canonicalText":"凡此六者，非天地之災，將之過也。","chunks":[["凡此六者，非天地之災，將之過也。","zh-Hant"]]},{"id":"art-of-war_ch-10_p-2_s-3","passageId":"art-of-war_ch-10_p-2","order":3,"canonicalText":"夫勢均，以一擊十，曰走。","chunks":[["夫勢均，以一擊十，曰走。","zh-Hant"]]},{"id":"art-of-war_ch-10_p-2_s-4","passageId":"art-of-war_ch-10_p-2","order":4,"canonicalText":"卒強吏弱，曰弛。","chunks":[["卒強吏弱，曰弛。","zh-Hant"]]},{"id":"art-of-war_ch-10_p-2_s-5","passageId":"art-of-war_ch-10_p-2","order":5,"canonicalText":"吏強卒弱，曰陷。","chunks":[["吏強卒弱，曰陷。","zh-Hant"]]},{"id":"art-of-war_ch-10_p-2_s-6","passageId":"art-of-war_ch-10_p-2","order":6,"canonicalText":"大吏怒而不服，遇敵懟而自戰，將不知其能，曰崩。","chunks":[["大吏怒而不服，遇敵懟而自戰，將不知其能，曰崩。","zh-Hant"]]},{"id":"art-of-war_ch-10_p-2_s-7","passageId":"art-of-war_ch-10_p-2","order":7,"canonicalText":"將弱不嚴，教道不明，吏卒無常，陳兵縱橫，曰亂。","chunks":[["將弱不嚴，教道不明，吏卒無常，陳兵縱橫，曰亂。","zh-Hant"]]},{"id":"art-of-war_ch-10_p-2_s-8","passageId":"art-of-war_ch-10_p-2","order":8,"canonicalText":"將不能料敵，以少合眾，以弱擊強，兵無選鋒，曰北。","chunks":[["將不能料敵，以少合眾，以弱擊強，兵無選鋒，曰北。","zh-Hant"]]},{"id":"art-of-war_ch-10_p-2_s-9","passageId":"art-of-war_ch-10_p-2","order":9,"canonicalText":"凡此六者，敗之道也。","chunks":[["凡此六者，敗之道也。","zh-Hant"]]},{"id":"art-of-war_ch-10_p-2_s-10","passageId":"art-of-war_ch-10_p-2","order":10,"canonicalText":"將之至任，不可不察也。","chunks":[["將之至任，不可不察也。","zh-Hant"]]},{"id":"art-of-war_ch-10_p-3_s-1","passageId":"art-of-war_ch-10_p-3","order":1,"canonicalText":"夫地形者，兵之助也。","chunks":[["夫地形者，兵之助也。","zh-Hant"]]},{"id":"art-of-war_ch-10_p-3_s-2","passageId":"art-of-war_ch-10_p-3","order":2,"canonicalText":"料敵制勝，計險阨遠近，上將之道也。","chunks":[["料敵制勝，計險阨遠近，上將之道也。","zh-Hant"]]},{"id":"art-of-war_ch-10_p-3_s-3","passageId":"art-of-war_ch-10_p-3","order":3,"canonicalText":"知此而用戰者，必勝；","chunks":[["知此而用戰者，必勝；","zh-Hant"]]},{"id":"art-of-war_ch-10_p-3_s-4","passageId":"art-of-war_ch-10_p-3","order":4,"canonicalText":"不知此而用戰者必敗。","chunks":[["不知此而用戰者必敗。","zh-Hant"]]},{"id":"art-of-war_ch-10_p-3_s-5","passageId":"art-of-war_ch-10_p-3","order":5,"canonicalText":"故戰道必勝；","chunks":[["故戰道必勝；","zh-Hant"]]},{"id":"art-of-war_ch-10_p-3_s-6","passageId":"art-of-war_ch-10_p-3","order":6,"canonicalText":"主曰：無戰；","chunks":[["主曰：無戰；","zh-Hant"]]},{"id":"art-of-war_ch-10_p-3_s-7","passageId":"art-of-war_ch-10_p-3","order":7,"canonicalText":"必戰可也。","chunks":[["必戰可也。","zh-Hant"]]},{"id":"art-of-war_ch-10_p-3_s-8","passageId":"art-of-war_ch-10_p-3","order":8,"canonicalText":"戰道不勝，主曰必戰，無戰可也。","chunks":[["戰道不勝，主曰必戰，無戰可也。","zh-Hant"]]},{"id":"art-of-war_ch-10_p-3_s-9","passageId":"art-of-war_ch-10_p-3","order":9,"canonicalText":"故進不求名，退不避罪，唯民是保，而利於主，國之寶也。","chunks":[["故進不求名，退不避罪，唯民是保，而利於主，國之寶也。","zh-Hant"]]},{"id":"art-of-war_ch-10_p-4_s-1","passageId":"art-of-war_ch-10_p-4","order":1,"canonicalText":"視卒如嬰兒，故可與之赴深谿；","chunks":[["視卒如嬰兒，故可與之赴深谿；","zh-Hant"]]},{"id":"art-of-war_ch-10_p-4_s-2","passageId":"art-of-war_ch-10_p-4","order":2,"canonicalText":"視卒如愛子，故可與之俱死。","chunks":[["視卒如愛子，故可與之俱死。","zh-Hant"]]},{"id":"art-of-war_ch-10_p-4_s-3","passageId":"art-of-war_ch-10_p-4","order":3,"canonicalText":"厚而不能使，愛而不能令，亂而不能治，譬若驕子，不可用也。","chunks":[["厚而不能使，愛而不能令，亂而不能治，譬若驕子，不可用也。","zh-Hant"]]},{"id":"art-of-war_ch-10_p-5_s-1","passageId":"art-of-war_ch-10_p-5","order":1,"canonicalText":"知吾卒之可以擊，而不知敵之不可擊，勝之半也；","chunks":[["知吾卒之可以擊，而不知敵之不可擊，勝之半也；","zh-Hant"]]},{"id":"art-of-war_ch-10_p-5_s-2","passageId":"art-of-war_ch-10_p-5","order":2,"canonicalText":"知敵之可擊，而不知吾卒之不可擊，勝之半也。","chunks":[["知敵之可擊，而不知吾卒之不可擊，勝之半也。","zh-Hant"]]},{"id":"art-of-war_ch-10_p-5_s-3","passageId":"art-of-war_ch-10_p-5","order":3,"canonicalText":"知敵之可擊，知吾卒之可以擊，而不知地形之不可以戰，勝之半也。","chunks":[["知敵之可擊，知吾卒之可以擊，而不知地形之不可以戰，勝之半也。","zh-Hant"]]},{"id":"art-of-war_ch-10_p-5_s-4","passageId":"art-of-war_ch-10_p-5","order":4,"canonicalText":"故知兵者，動而不迷，舉而不窮。","chunks":[["故知兵者，動而不迷，舉而不窮。","zh-Hant"]]},{"id":"art-of-war_ch-10_p-5_s-5","passageId":"art-of-war_ch-10_p-5","order":5,"canonicalText":"故曰：知彼知己，勝乃不殆；","chunks":[["故曰：知彼知己，勝乃不殆；","zh-Hant"]]},{"id":"art-of-war_ch-10_p-5_s-6","passageId":"art-of-war_ch-10_p-5","order":6,"canonicalText":"知天知地，勝乃可全。","chunks":[["知天知地，勝乃可全。","zh-Hant"]]},{"id":"art-of-war_ch-11_p-1_s-1","passageId":"art-of-war_ch-11_p-1","order":1,"canonicalText":"孫子曰：用兵之法，有散地，有輕地，有爭地，有交地，有衢地，有重地，有圮地，有圍地，有死地。","chunks":[["孫子曰：用兵之法，有散地，有輕地，有爭地，有交地，有衢地，有重地，有圮地，有圍地，有死地。","zh-Hant"]]},{"id":"art-of-war_ch-11_p-1_s-2","passageId":"art-of-war_ch-11_p-1","order":2,"canonicalText":"諸侯自戰其地者，為散地。","chunks":[["諸侯自戰其地者，為散地。","zh-Hant"]]},{"id":"art-of-war_ch-11_p-1_s-3","passageId":"art-of-war_ch-11_p-1","order":3,"canonicalText":"入人之地而不深者，為輕地。","chunks":[["入人之地而不深者，為輕地。","zh-Hant"]]},{"id":"art-of-war_ch-11_p-1_s-4","passageId":"art-of-war_ch-11_p-1","order":4,"canonicalText":"我得則利，彼得亦利者，為爭地。","chunks":[["我得則利，彼得亦利者，為爭地。","zh-Hant"]]},{"id":"art-of-war_ch-11_p-1_s-5","passageId":"art-of-war_ch-11_p-1","order":5,"canonicalText":"我可以往，彼可以來者，為交地。","chunks":[["我可以往，彼可以來者，為交地。","zh-Hant"]]},{"id":"art-of-war_ch-11_p-1_s-6","passageId":"art-of-war_ch-11_p-1","order":6,"canonicalText":"諸侯之地三屬，先至而得天下之眾者，為衢地。","chunks":[["諸侯之地三屬，先至而得天下之眾者，為衢地。","zh-Hant"]]},{"id":"art-of-war_ch-11_p-1_s-7","passageId":"art-of-war_ch-11_p-1","order":7,"canonicalText":"入人之地深，背城邑多者，為重地。","chunks":[["入人之地深，背城邑多者，為重地。","zh-Hant"]]},{"id":"art-of-war_ch-11_p-1_s-8","passageId":"art-of-war_ch-11_p-1","order":8,"canonicalText":"山林、險阻、沮澤，凡難行之道者，為圮地。","chunks":[["山林、險阻、沮澤，凡難行之道者，為圮地。","zh-Hant"]]},{"id":"art-of-war_ch-11_p-1_s-9","passageId":"art-of-war_ch-11_p-1","order":9,"canonicalText":"所由入者隘，所從歸者迂，彼寡可以擊吾之眾者，為圍地。","chunks":[["所由入者隘，所從歸者迂，彼寡可以擊吾之眾者，為圍地。","zh-Hant"]]},{"id":"art-of-war_ch-11_p-1_s-10","passageId":"art-of-war_ch-11_p-1","order":10,"canonicalText":"疾戰則存，不疾戰則亡者，為死地。","chunks":[["疾戰則存，不疾戰則亡者，為死地。","zh-Hant"]]},{"id":"art-of-war_ch-11_p-1_s-11","passageId":"art-of-war_ch-11_p-1","order":11,"canonicalText":"是故散地則無戰，輕地則無止，爭地則無攻，交地則無絕，衢地則合交，重地則掠，圮地則行，圍地則謀，死地則戰。","chunks":[["是故散地則無戰，輕地則無止，爭地則無攻，交地則無絕，衢地則合交，重地則掠，圮地則行，圍地則謀，死地則戰。","zh-Hant"]]},{"id":"art-of-war_ch-11_p-2_s-1","passageId":"art-of-war_ch-11_p-2","order":1,"canonicalText":"古之所謂善用兵者，能使敵人前後不相及，眾寡不相恃，貴賤不相救，上下不相收，卒離而不集，兵合而不齊。","chunks":[["古之所謂善用兵者，能使敵人前後不相及，眾寡不相恃，貴賤不相救，上下不相收，卒離而不集，兵合而不齊。","zh-Hant"]]},{"id":"art-of-war_ch-11_p-2_s-2","passageId":"art-of-war_ch-11_p-2","order":2,"canonicalText":"合於利而動，不合於利而止。","chunks":[["合於利而動，不合於利而止。","zh-Hant"]]},{"id":"art-of-war_ch-11_p-2_s-3","passageId":"art-of-war_ch-11_p-2","order":3,"canonicalText":"敢問：「敵眾整而將來，待之若何？","chunks":[["敢問：「敵眾整而將來，待之若何？","zh-Hant"]]},{"id":"art-of-war_ch-11_p-2_s-4","passageId":"art-of-war_ch-11_p-2","order":4,"canonicalText":"」曰：「先奪其所愛，則聽矣；","chunks":[["」曰：「先奪其所愛，則聽矣；","zh-Hant"]]},{"id":"art-of-war_ch-11_p-2_s-5","passageId":"art-of-war_ch-11_p-2","order":5,"canonicalText":"兵之情主速，乘人之不及，由不虞之道，攻其所不戒也。","chunks":[["兵之情主速，乘人之不及，由不虞之道，攻其所不戒也。","zh-Hant"]]},{"id":"art-of-war_ch-11_p-2_s-6","passageId":"art-of-war_ch-11_p-2","order":6,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"art-of-war_ch-11_p-3_s-1","passageId":"art-of-war_ch-11_p-3","order":1,"canonicalText":"凡為客之道，深入則專，主人不克，掠於饒野，三軍足食，謹養而無勞，併氣積力，運兵計謀，為不可測，投之無所往，死且不北，死焉不得，士人盡力。","chunks":[["凡為客之道，深入則專，主人不克，掠於饒野，三軍足食，謹養而無勞，併氣積力，運兵計謀，為不可測，投之無所往，死且不北，死焉不得，士人盡力。","zh-Hant"]]},{"id":"art-of-war_ch-11_p-3_s-2","passageId":"art-of-war_ch-11_p-3","order":2,"canonicalText":"兵士甚陷則不懼，無所往則固，深入則拘，不得已則鬥。","chunks":[["兵士甚陷則不懼，無所往則固，深入則拘，不得已則鬥。","zh-Hant"]]},{"id":"art-of-war_ch-11_p-3_s-3","passageId":"art-of-war_ch-11_p-3","order":3,"canonicalText":"是故，其兵不修而戒，不求而得，不約而親，不令而信，禁祥去疑，至死無所之。","chunks":[["是故，其兵不修而戒，不求而得，不約而親，不令而信，禁祥去疑，至死無所之。","zh-Hant"]]},{"id":"art-of-war_ch-11_p-3_s-4","passageId":"art-of-war_ch-11_p-3","order":4,"canonicalText":"吾士無餘財，非惡貨也；","chunks":[["吾士無餘財，非惡貨也；","zh-Hant"]]},{"id":"art-of-war_ch-11_p-3_s-5","passageId":"art-of-war_ch-11_p-3","order":5,"canonicalText":"無餘命，非惡壽也。","chunks":[["無餘命，非惡壽也。","zh-Hant"]]},{"id":"art-of-war_ch-11_p-3_s-6","passageId":"art-of-war_ch-11_p-3","order":6,"canonicalText":"令發之日，士卒坐者涕沾襟，偃臥者涕交頤，投之無所往，則諸劌之勇也。","chunks":[["令發之日，士卒坐者涕沾襟，偃臥者涕交頤，投之無所往，則諸劌之勇也。","zh-Hant"]]},{"id":"art-of-war_ch-11_p-4_s-1","passageId":"art-of-war_ch-11_p-4","order":1,"canonicalText":"故善用兵者，譬如率然；","chunks":[["故善用兵者，譬如率然；","zh-Hant"]]},{"id":"art-of-war_ch-11_p-4_s-2","passageId":"art-of-war_ch-11_p-4","order":2,"canonicalText":"率然者，常山之蛇也，擊其首，則尾至，擊其尾，則首至，擊其中，則首尾俱至。","chunks":[["率然者，常山之蛇也，擊其首，則尾至，擊其尾，則首至，擊其中，則首尾俱至。","zh-Hant"]]},{"id":"art-of-war_ch-11_p-4_s-3","passageId":"art-of-war_ch-11_p-4","order":3,"canonicalText":"敢問：「兵可使如率然乎？","chunks":[["敢問：「兵可使如率然乎？","zh-Hant"]]},{"id":"art-of-war_ch-11_p-4_s-4","passageId":"art-of-war_ch-11_p-4","order":4,"canonicalText":"」曰：「可。","chunks":[["」曰：「可。","zh-Hant"]]},{"id":"art-of-war_ch-11_p-4_s-5","passageId":"art-of-war_ch-11_p-4","order":5,"canonicalText":"」夫吳人與越人相惡也，當其同舟濟而遇風，其相救也如左右手。","chunks":[["」夫吳人與越人相惡也，當其同舟濟而遇風，其相救也如左右手。","zh-Hant"]]},{"id":"art-of-war_ch-11_p-4_s-6","passageId":"art-of-war_ch-11_p-4","order":6,"canonicalText":"是故，方馬埋輪，未足恃也，齊勇若一，政之道也；","chunks":[["是故，方馬埋輪，未足恃也，齊勇若一，政之道也；","zh-Hant"]]},{"id":"art-of-war_ch-11_p-4_s-7","passageId":"art-of-war_ch-11_p-4","order":7,"canonicalText":"剛柔皆得，地之理也。","chunks":[["剛柔皆得，地之理也。","zh-Hant"]]},{"id":"art-of-war_ch-11_p-4_s-8","passageId":"art-of-war_ch-11_p-4","order":8,"canonicalText":"故善用兵者，攜手若使一人，不得已也。","chunks":[["故善用兵者，攜手若使一人，不得已也。","zh-Hant"]]},{"id":"art-of-war_ch-11_p-5_s-1","passageId":"art-of-war_ch-11_p-5","order":1,"canonicalText":"將軍之事，靜以幽，正以治，能愚士卒之耳目，使之無知。","chunks":[["將軍之事，靜以幽，正以治，能愚士卒之耳目，使之無知。","zh-Hant"]]},{"id":"art-of-war_ch-11_p-5_s-2","passageId":"art-of-war_ch-11_p-5","order":2,"canonicalText":"易其事，革其謀，使人無識，易其居，迂其途，使人不得慮。","chunks":[["易其事，革其謀，使人無識，易其居，迂其途，使人不得慮。","zh-Hant"]]},{"id":"art-of-war_ch-11_p-5_s-3","passageId":"art-of-war_ch-11_p-5","order":3,"canonicalText":"帥與之期，如登高而去其梯，帥與之深，入諸侯之地而發其機。","chunks":[["帥與之期，如登高而去其梯，帥與之深，入諸侯之地而發其機。","zh-Hant"]]},{"id":"art-of-war_ch-11_p-5_s-4","passageId":"art-of-war_ch-11_p-5","order":4,"canonicalText":"若驅羣羊，驅而往，驅而來，莫知所之。","chunks":[["若驅羣羊，驅而往，驅而來，莫知所之。","zh-Hant"]]},{"id":"art-of-war_ch-11_p-5_s-5","passageId":"art-of-war_ch-11_p-5","order":5,"canonicalText":"聚三軍之眾，投之於險，此將軍之事也。","chunks":[["聚三軍之眾，投之於險，此將軍之事也。","zh-Hant"]]},{"id":"art-of-war_ch-11_p-5_s-6","passageId":"art-of-war_ch-11_p-5","order":6,"canonicalText":"九地之變，屈伸之利，人情之理，不可不察也。","chunks":[["九地之變，屈伸之利，人情之理，不可不察也。","zh-Hant"]]},{"id":"art-of-war_ch-11_p-6_s-1","passageId":"art-of-war_ch-11_p-6","order":1,"canonicalText":"凡為客之道，深則專，淺則散；","chunks":[["凡為客之道，深則專，淺則散；","zh-Hant"]]},{"id":"art-of-war_ch-11_p-6_s-2","passageId":"art-of-war_ch-11_p-6","order":2,"canonicalText":"去國越境而師者，絕地也；","chunks":[["去國越境而師者，絕地也；","zh-Hant"]]},{"id":"art-of-war_ch-11_p-6_s-3","passageId":"art-of-war_ch-11_p-6","order":3,"canonicalText":"四達者，衢地也；","chunks":[["四達者，衢地也；","zh-Hant"]]},{"id":"art-of-war_ch-11_p-6_s-4","passageId":"art-of-war_ch-11_p-6","order":4,"canonicalText":"入深者，重地也；","chunks":[["入深者，重地也；","zh-Hant"]]},{"id":"art-of-war_ch-11_p-6_s-5","passageId":"art-of-war_ch-11_p-6","order":5,"canonicalText":"入淺者，輕地也；","chunks":[["入淺者，輕地也；","zh-Hant"]]},{"id":"art-of-war_ch-11_p-6_s-6","passageId":"art-of-war_ch-11_p-6","order":6,"canonicalText":"背固前隘者，圍地也；","chunks":[["背固前隘者，圍地也；","zh-Hant"]]},{"id":"art-of-war_ch-11_p-6_s-7","passageId":"art-of-war_ch-11_p-6","order":7,"canonicalText":"無所往者，死地也。","chunks":[["無所往者，死地也。","zh-Hant"]]},{"id":"art-of-war_ch-11_p-6_s-8","passageId":"art-of-war_ch-11_p-6","order":8,"canonicalText":"是故散地吾將一其志，輕地吾將使之屬，爭地吾將趨其後，交地吾將謹其守，衢地吾將固其結，重地吾將繼其食，圮地吾將進其途，圍地吾將塞其闕，死地吾將示之以不活。","chunks":[["是故散地吾將一其志，輕地吾將使之屬，爭地吾將趨其後，交地吾將謹其守，衢地吾將固其結，重地吾將繼其食，圮地吾將進其途，圍地吾將塞其闕，死地吾將示之以不活。","zh-Hant"]]},{"id":"art-of-war_ch-11_p-6_s-9","passageId":"art-of-war_ch-11_p-6","order":9,"canonicalText":"故兵之情，圍則禦，不得已則鬥，逼則從。","chunks":[["故兵之情，圍則禦，不得已則鬥，逼則從。","zh-Hant"]]},{"id":"art-of-war_ch-11_p-7_s-1","passageId":"art-of-war_ch-11_p-7","order":1,"canonicalText":"是故不知諸侯之謀者，不能預交，不知山林險阻沮澤之形者，不能行軍，不用鄉導者，不能得地利，此三者不知一，非霸王之兵也。","chunks":[["是故不知諸侯之謀者，不能預交，不知山林險阻沮澤之形者，不能行軍，不用鄉導者，不能得地利，此三者不知一，非霸王之兵也。","zh-Hant"]]},{"id":"art-of-war_ch-11_p-7_s-2","passageId":"art-of-war_ch-11_p-7","order":2,"canonicalText":"夫霸王之兵，伐大國則其眾不得聚，威加於敵，則其交不得合。","chunks":[["夫霸王之兵，伐大國則其眾不得聚，威加於敵，則其交不得合。","zh-Hant"]]},{"id":"art-of-war_ch-11_p-7_s-3","passageId":"art-of-war_ch-11_p-7","order":3,"canonicalText":"是故不爭天下之交，不養天下之權，信己之私，威加於敵，故其城可拔，其國可墮。","chunks":[["是故不爭天下之交，不養天下之權，信己之私，威加於敵，故其城可拔，其國可墮。","zh-Hant"]]},{"id":"art-of-war_ch-11_p-7_s-4","passageId":"art-of-war_ch-11_p-7","order":4,"canonicalText":"施無法之賞，懸無政之令，犯三軍之眾，若使一人。","chunks":[["施無法之賞，懸無政之令，犯三軍之眾，若使一人。","zh-Hant"]]},{"id":"art-of-war_ch-11_p-7_s-5","passageId":"art-of-war_ch-11_p-7","order":5,"canonicalText":"犯之以事，勿告以言；","chunks":[["犯之以事，勿告以言；","zh-Hant"]]},{"id":"art-of-war_ch-11_p-7_s-6","passageId":"art-of-war_ch-11_p-7","order":6,"canonicalText":"犯之以利，勿告以害；","chunks":[["犯之以利，勿告以害；","zh-Hant"]]},{"id":"art-of-war_ch-11_p-7_s-7","passageId":"art-of-war_ch-11_p-7","order":7,"canonicalText":"投之亡地然後存，陷之死地然後生。","chunks":[["投之亡地然後存，陷之死地然後生。","zh-Hant"]]},{"id":"art-of-war_ch-11_p-7_s-8","passageId":"art-of-war_ch-11_p-7","order":8,"canonicalText":"夫眾陷於害，然後能為勝敗，故為兵之事，在於順詳敵之意，併力一向，千里殺將，是謂巧能成事。","chunks":[["夫眾陷於害，然後能為勝敗，故為兵之事，在於順詳敵之意，併力一向，千里殺將，是謂巧能成事。","zh-Hant"]]},{"id":"art-of-war_ch-11_p-8_s-1","passageId":"art-of-war_ch-11_p-8","order":1,"canonicalText":"是故政舉之日，夷關折符，無通其使，厲於廊廟之上，以誅其事，敵人開闔，必亟入之。","chunks":[["是故政舉之日，夷關折符，無通其使，厲於廊廟之上，以誅其事，敵人開闔，必亟入之。","zh-Hant"]]},{"id":"art-of-war_ch-11_p-8_s-2","passageId":"art-of-war_ch-11_p-8","order":2,"canonicalText":"先其所愛，微與之期，賤墨隨敵，以決戰爭。","chunks":[["先其所愛，微與之期，賤墨隨敵，以決戰爭。","zh-Hant"]]},{"id":"art-of-war_ch-11_p-8_s-3","passageId":"art-of-war_ch-11_p-8","order":3,"canonicalText":"是故始如處女，敵人開戶，後如脫兔，敵不及拒。","chunks":[["是故始如處女，敵人開戶，後如脫兔，敵不及拒。","zh-Hant"]]},{"id":"art-of-war_ch-12_p-1_s-1","passageId":"art-of-war_ch-12_p-1","order":1,"canonicalText":"孫子曰：凡火攻有五：一曰火人，二曰火積，三曰火輜，四曰火庫，五曰火隊。","chunks":[["孫子曰：凡火攻有五：一曰火人，二曰火積，三曰火輜，四曰火庫，五曰火隊。","zh-Hant"]]},{"id":"art-of-war_ch-12_p-1_s-2","passageId":"art-of-war_ch-12_p-1","order":2,"canonicalText":"行火必有因，煙火必素具。","chunks":[["行火必有因，煙火必素具。","zh-Hant"]]},{"id":"art-of-war_ch-12_p-1_s-3","passageId":"art-of-war_ch-12_p-1","order":3,"canonicalText":"發火有時，起火有日。","chunks":[["發火有時，起火有日。","zh-Hant"]]},{"id":"art-of-war_ch-12_p-1_s-4","passageId":"art-of-war_ch-12_p-1","order":4,"canonicalText":"時者，天之燥也。","chunks":[["時者，天之燥也。","zh-Hant"]]},{"id":"art-of-war_ch-12_p-1_s-5","passageId":"art-of-war_ch-12_p-1","order":5,"canonicalText":"日者，月在箕壁翼軫也。","chunks":[["日者，月在箕壁翼軫也。","zh-Hant"]]},{"id":"art-of-war_ch-12_p-1_s-6","passageId":"art-of-war_ch-12_p-1","order":6,"canonicalText":"凡此四宿者，風起之日也。","chunks":[["凡此四宿者，風起之日也。","zh-Hant"]]},{"id":"art-of-war_ch-12_p-2_s-1","passageId":"art-of-war_ch-12_p-2","order":1,"canonicalText":"凡火攻，必因五火之變而應之，火發於內，則早應之於外。","chunks":[["凡火攻，必因五火之變而應之，火發於內，則早應之於外。","zh-Hant"]]},{"id":"art-of-war_ch-12_p-2_s-2","passageId":"art-of-war_ch-12_p-2","order":2,"canonicalText":"火發而其兵靜者，待而勿攻。","chunks":[["火發而其兵靜者，待而勿攻。","zh-Hant"]]},{"id":"art-of-war_ch-12_p-2_s-3","passageId":"art-of-war_ch-12_p-2","order":3,"canonicalText":"極其火力，可從而從之，不可從而止。","chunks":[["極其火力，可從而從之，不可從而止。","zh-Hant"]]},{"id":"art-of-war_ch-12_p-2_s-4","passageId":"art-of-war_ch-12_p-2","order":4,"canonicalText":"火可發於外，無待於內，以時發之。","chunks":[["火可發於外，無待於內，以時發之。","zh-Hant"]]},{"id":"art-of-war_ch-12_p-2_s-5","passageId":"art-of-war_ch-12_p-2","order":5,"canonicalText":"火發上風，無攻下風，晝風久，夜風止。","chunks":[["火發上風，無攻下風，晝風久，夜風止。","zh-Hant"]]},{"id":"art-of-war_ch-12_p-2_s-6","passageId":"art-of-war_ch-12_p-2","order":6,"canonicalText":"凡軍必知五火之變，以數守之。","chunks":[["凡軍必知五火之變，以數守之。","zh-Hant"]]},{"id":"art-of-war_ch-12_p-2_s-7","passageId":"art-of-war_ch-12_p-2","order":7,"canonicalText":"故以火佐攻者明，以水佐攻者強，水可以絕，不可以奪。","chunks":[["故以火佐攻者明，以水佐攻者強，水可以絕，不可以奪。","zh-Hant"]]},{"id":"art-of-war_ch-12_p-3_s-1","passageId":"art-of-war_ch-12_p-3","order":1,"canonicalText":"夫戰勝攻取，而不修其攻者兇，命曰費留。","chunks":[["夫戰勝攻取，而不修其攻者兇，命曰費留。","zh-Hant"]]},{"id":"art-of-war_ch-12_p-3_s-2","passageId":"art-of-war_ch-12_p-3","order":2,"canonicalText":"故曰：明主慮之，良將修之，非利不動，非得不用，非危不戰。","chunks":[["故曰：明主慮之，良將修之，非利不動，非得不用，非危不戰。","zh-Hant"]]},{"id":"art-of-war_ch-12_p-3_s-3","passageId":"art-of-war_ch-12_p-3","order":3,"canonicalText":"主不可以怒而興師，將不可以慍而致戰；","chunks":[["主不可以怒而興師，將不可以慍而致戰；","zh-Hant"]]},{"id":"art-of-war_ch-12_p-3_s-4","passageId":"art-of-war_ch-12_p-3","order":4,"canonicalText":"合於利而動，不合於利而止。","chunks":[["合於利而動，不合於利而止。","zh-Hant"]]},{"id":"art-of-war_ch-12_p-3_s-5","passageId":"art-of-war_ch-12_p-3","order":5,"canonicalText":"怒可以復喜，慍可以復悅，亡國不可以復存，死者不可以復生。","chunks":[["怒可以復喜，慍可以復悅，亡國不可以復存，死者不可以復生。","zh-Hant"]]},{"id":"art-of-war_ch-12_p-3_s-6","passageId":"art-of-war_ch-12_p-3","order":6,"canonicalText":"故明君慎之，良將警之，此安國全軍之道也。","chunks":[["故明君慎之，良將警之，此安國全軍之道也。","zh-Hant"]]},{"id":"art-of-war_ch-13_p-1_s-1","passageId":"art-of-war_ch-13_p-1","order":1,"canonicalText":"孫子曰：凡興師十萬，出征千里，百姓之費，公家之奉，日費千金，內外騷動，怠於道路，不得操事者，七十萬家，相守數年，以爭一日之勝，而愛爵祿百金，不知敵之情者，不仁之至也，非人之將也，非主之佐也，非勝之主也。","chunks":[["孫子曰：凡興師十萬，出征千里，百姓之費，公家之奉，日費千金，內外騷動，怠於道路，不得操事者，七十萬家，相守數年，以爭一日之勝，而愛爵祿百金，不知敵之情者，不仁之至也，非人之將也，非主之佐也，非勝之主也。","zh-Hant"]]},{"id":"art-of-war_ch-13_p-1_s-2","passageId":"art-of-war_ch-13_p-1","order":2,"canonicalText":"故明君賢將，所以動而勝人，成功出於眾者，先知也；","chunks":[["故明君賢將，所以動而勝人，成功出於眾者，先知也；","zh-Hant"]]},{"id":"art-of-war_ch-13_p-1_s-3","passageId":"art-of-war_ch-13_p-1","order":3,"canonicalText":"先知者，不可取於鬼神，不可象於事，不可驗於度；","chunks":[["先知者，不可取於鬼神，不可象於事，不可驗於度；","zh-Hant"]]},{"id":"art-of-war_ch-13_p-1_s-4","passageId":"art-of-war_ch-13_p-1","order":4,"canonicalText":"必取於人，知敵之情者也。","chunks":[["必取於人，知敵之情者也。","zh-Hant"]]},{"id":"art-of-war_ch-13_p-2_s-1","passageId":"art-of-war_ch-13_p-2","order":1,"canonicalText":"故用間有五：有鄉間、有內間、有反間、有死間、有生間。","chunks":[["故用間有五：有鄉間、有內間、有反間、有死間、有生間。","zh-Hant"]]},{"id":"art-of-war_ch-13_p-2_s-2","passageId":"art-of-war_ch-13_p-2","order":2,"canonicalText":"五間俱起，莫知其道，是謂神紀，人君之寶也。","chunks":[["五間俱起，莫知其道，是謂神紀，人君之寶也。","zh-Hant"]]},{"id":"art-of-war_ch-13_p-2_s-3","passageId":"art-of-war_ch-13_p-2","order":3,"canonicalText":"鄉間者，因其鄉人而用之。","chunks":[["鄉間者，因其鄉人而用之。","zh-Hant"]]},{"id":"art-of-war_ch-13_p-2_s-4","passageId":"art-of-war_ch-13_p-2","order":4,"canonicalText":"內間者，因其官人而用之。","chunks":[["內間者，因其官人而用之。","zh-Hant"]]},{"id":"art-of-war_ch-13_p-2_s-5","passageId":"art-of-war_ch-13_p-2","order":5,"canonicalText":"反間者，因其敵間而用之。","chunks":[["反間者，因其敵間而用之。","zh-Hant"]]},{"id":"art-of-war_ch-13_p-2_s-6","passageId":"art-of-war_ch-13_p-2","order":6,"canonicalText":"死間者，為誑事於外，令吾間知之，而傳於敵。","chunks":[["死間者，為誑事於外，令吾間知之，而傳於敵。","zh-Hant"]]},{"id":"art-of-war_ch-13_p-2_s-7","passageId":"art-of-war_ch-13_p-2","order":7,"canonicalText":"生間者，反報也。","chunks":[["生間者，反報也。","zh-Hant"]]},{"id":"art-of-war_ch-13_p-3_s-1","passageId":"art-of-war_ch-13_p-3","order":1,"canonicalText":"故三軍之事，親莫親於間，賞莫厚於間，事莫密於間，非聖智不能用間，非仁義不能使間，非微妙不能得間之實。","chunks":[["故三軍之事，親莫親於間，賞莫厚於間，事莫密於間，非聖智不能用間，非仁義不能使間，非微妙不能得間之實。","zh-Hant"]]},{"id":"art-of-war_ch-13_p-3_s-2","passageId":"art-of-war_ch-13_p-3","order":2,"canonicalText":"微哉，微哉，無所不用間也。","chunks":[["微哉，微哉，無所不用間也。","zh-Hant"]]},{"id":"art-of-war_ch-13_p-3_s-3","passageId":"art-of-war_ch-13_p-3","order":3,"canonicalText":"間事未發而先聞者，間與所告者皆死。","chunks":[["間事未發而先聞者，間與所告者皆死。","zh-Hant"]]},{"id":"art-of-war_ch-13_p-4_s-1","passageId":"art-of-war_ch-13_p-4","order":1,"canonicalText":"凡軍之所欲擊，城之所欲攻，人之所欲殺；","chunks":[["凡軍之所欲擊，城之所欲攻，人之所欲殺；","zh-Hant"]]},{"id":"art-of-war_ch-13_p-4_s-2","passageId":"art-of-war_ch-13_p-4","order":2,"canonicalText":"必先知其守將，左右，謁者，門者，舍人之姓名，令吾間必索知之。","chunks":[["必先知其守將，左右，謁者，門者，舍人之姓名，令吾間必索知之。","zh-Hant"]]},{"id":"art-of-war_ch-13_p-4_s-3","passageId":"art-of-war_ch-13_p-4","order":3,"canonicalText":"必索敵間之來間我者，因而利之，導而舍之，故反間可得而使也。","chunks":[["必索敵間之來間我者，因而利之，導而舍之，故反間可得而使也。","zh-Hant"]]},{"id":"art-of-war_ch-13_p-4_s-4","passageId":"art-of-war_ch-13_p-4","order":4,"canonicalText":"因是而知之，故鄉間內間可得而使也；","chunks":[["因是而知之，故鄉間內間可得而使也；","zh-Hant"]]},{"id":"art-of-war_ch-13_p-4_s-5","passageId":"art-of-war_ch-13_p-4","order":5,"canonicalText":"因是而知之，故死間為誑事，可使告敵；","chunks":[["因是而知之，故死間為誑事，可使告敵；","zh-Hant"]]},{"id":"art-of-war_ch-13_p-4_s-6","passageId":"art-of-war_ch-13_p-4","order":6,"canonicalText":"因是而知之，故生間可使如期。","chunks":[["因是而知之，故生間可使如期。","zh-Hant"]]},{"id":"art-of-war_ch-13_p-4_s-7","passageId":"art-of-war_ch-13_p-4","order":7,"canonicalText":"五間之事，主必知之，知之必在於反間，故反間不可不厚也。","chunks":[["五間之事，主必知之，知之必在於反間，故反間不可不厚也。","zh-Hant"]]},{"id":"art-of-war_ch-13_p-5_s-1","passageId":"art-of-war_ch-13_p-5","order":1,"canonicalText":"昔殷之興也，伊摯在夏。","chunks":[["昔殷之興也，伊摯在夏。","zh-Hant"]]},{"id":"art-of-war_ch-13_p-5_s-2","passageId":"art-of-war_ch-13_p-5","order":2,"canonicalText":"周之興也，呂牙在殷。","chunks":[["周之興也，呂牙在殷。","zh-Hant"]]},{"id":"art-of-war_ch-13_p-5_s-3","passageId":"art-of-war_ch-13_p-5","order":3,"canonicalText":"故明君賢將，能以上智為間者，必成大功，此兵之要，三軍之所恃而動也。","chunks":[["故明君賢將，能以上智為間者，必成大功，此兵之要，三軍之所恃而動也。","zh-Hant"]]}]}');export{a as default};
